(window.GAMES = window.GAMES || {})[2019] = [{"t":"198X","p":["Windows","PlayStation 4"],"u":"Hi-Bit Studios","g":"Action","r":"June 20","l":"https://en.wikipedia.org/wiki/198X","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m2h.jpg","s":"198X is not just a beat ’em up, a shoot ’em up, a racing game, a ninja game and an RPG. This is a love letter to the golden age of arcade games – yet with a scope that was never possible in the actual 1980s. It’s a story about finding yourself – and your self-confidence – in the world of video games. A coming-of-age story told through multiple game genres, worlds and characters. Feel the sensation of fighting, shooting, driving, jumping and role-playing – combined with emotional, cinematic storytelling.\n\nAnd what happens when the line between reality and game starts to blur…?"},{"t":"3 Little Pigs & Bad Wolf","p":["Nintendo Switch"],"g":"Puzzle, Strategy, Card & Board Game","l":"https://en.wikipedia.org/wiki/3_Little_Pigs_&_Bad_Wolf","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co267n.jpg","s":"Play 3 little pigs with parents and children\nAn intelligence board game with parents and children"},{"t":"60 Seconds! Reatomized","p":["macOS","Windows"],"d":"Robot Gentleman Studios","u":"Robot Gentleman Studios","g":"Role-playing (RPG), Simulator, Strategy, Adventure, Indie","r":"July 25, 2019","l":"https://www.igdb.com/games/60-seconds-reatomized","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2t2j.jpg","s":"Dolores, Ted, Mary Jane and Timmy return to face the nuclear apocalypse in this new, remastered edition of the classic atomic adventure - 60 Seconds! Reatomized, featuring 4K support, refreshed 2D graphics and hand-drawn 3D textures, new interactive menu, improved UI system, a technical refresh, and of course... new content!\n\nWith only 60 seconds left to impact, go on a mad dash through the house in search of family members and useful supplies. Everything will be against you: time, your very own furniture, a house that's different every time you play, and the fundamental question... what to take with you and who to leave behind?\n\nReaching the fallout shelter in time, alive, is only the beginning. Whatever you scavenged and whoever you saved will play a vital role in your survival. Each survival story will be different, with every day surprising you with unexpected events. Will all of these stories end well? It's up to you. Ration food and water, make best use of your supplies, face difficult choices and even venture into the wasteland.\n\nGood luck."},{"t":"8-bit ADV Steins;Gate","p":["Nintendo Switch"],"u":"Spike Chunsoft","g":"Visual novel","r":"February 19","l":"https://en.wikipedia.org/wiki/8-bit_ADV_Steins;Gate"},{"t":"9-Nine","p":[],"l":"https://en.wikipedia.org/wiki/9-Nine"},{"t":"A Fisherman's Tale","p":["PlayStation 4","Meta Quest","Windows"],"d":"InnerspaceVR","u":"Vertigo Games","g":"Virtual reality, puzzle game","r":"January 22, 2019","l":"https://en.wikipedia.org/wiki/A_Fisherman's_Tale","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1iaz.jpg","s":"\"Bend and twist reality in A Fisherman's Tale, the mind-bending VR puzzle adventure game in which being turned upside down and inside out is not merely a play on words.\n\nPlaying as Bob, a tiny fisherman puppet, you live alone in your tiny cabin, oblivious to the world outside. When your radio broadcasts a storm alert, you have to get to the top of the lighthouse and turn on the light! But as you try to leave your cabin with the help of some uncanny sidekicks, you realize what's waiting outside is not at all what you expected...\""},{"t":"A Plague Tale: Innocence","p":["Windows","PlayStation 4","Xbox One"],"u":"Focus Home Interactive","g":"Action-adventure, Puzzle","r":"May 14","l":"https://www.igdb.com/games/a-plague-tale-innocence","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1lat.jpg","s":"A Plague Tale: Innocence is a third-person action-adventure game set in 14th-century France during the Black Death. Players control Amicia, a young girl protecting her little brother Hugo as they flee the Inquisition and navigate environments overrun by swarms of plague rats. Gameplay combines stealth, puzzle-solving, and light combat, with an emphasis on using fire and light to manage the rat hordes."},{"t":"A Short Hike","p":["Windows","macOS","Linux"],"g":"Adventure","r":"July 30, 2019","l":"https://en.wikipedia.org/wiki/A_Short_Hike","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6e83.jpg","s":"A Short Hike is an exploration adventure game set in Hawk Peak Provincial Park. Players control Claire, a young bird who sets out to reach the summit of Hawk Peak while waiting for an important phone call.\n\nThe game allows players to climb, glide and explore the park at their own pace, meeting other visitors, completing small tasks and collecting items that improve Claire’s movement."},{"t":"A-Train Express","p":["PlayStation 4","PlayStation VR"],"u":"Degica Games","g":"Simulation","r":"June 7","l":"https://en.wikipedia.org/wiki/A-Train_Express"},{"t":"Ace Angler","p":["Nintendo Switch"],"d":"Bandai Namco Entertainment","u":"Bandai Namco Entertainment","g":"Fishing","r":"July 25, 2019","l":"https://en.wikipedia.org/wiki/Ace_Angler","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6oed.jpg","s":"A fishing stimulation game where you reel in small fishes such as clownfish and boxfish as well as the big fishes such as angler shark, giant squid using a ‘Rod Controller’! Acquire medals when you catch a fish and get even more medals when you reel in the big fishes!\n\nNEW TECHNIQUE - Enjoy the realistic force feedback of casting the line and reeling in the fish with Joy-Con \"Rod Technique\"\nFISH FOR REAL - Responsive HD vibration where the rod responses when the fish takes the bait as though you’re fishing for real!\nAuthentic Arcade-style Fishing Action - Multiple gameplay modes including Medal Mode, Adventure Mode and Competition Mode!"},{"t":"Ace Combat 7: Skies Unknown","p":["PlayStation 4","Xbox One","Windows"],"u":"Bandai Namco Entertainment","g":"Vehicular combat (plane)","r":"January 18","l":"https://www.igdb.com/games/ace-combat-7-skies-unknown","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ilk.jpg","s":"Leveraging the trueSKY technology and developed utilizing Unreal Engine 4, Ace Combat 7 will astound players with beautifully rendered skies and highly detailed cityscapes but also set the stage for the most engaging aerial battles in the franchise’s storied 20 year history accompanied with an immersive soundtrack. Ace Combat 7 will take the elements that the series is known for to a whole new level! Aces who have proven their combat prowess in Ace Combat 7’s campaign mode can take their dogfighting skills further with furious online multiplayer battles.\n\nPlayStation4 players will also be able to get immersed in ACE COMBAT 7’s realism through exclusive features developed specifically for PlayStationVR."},{"t":"Action Taimanin","p":["Android","iOS","Windows"],"d":"Gremory Games, Lilith","u":"Gremory Games, Infini-Brain inc.","g":"Action role-playing, hack and slash","r":"December 24, 2019","l":"https://en.wikipedia.org/wiki/Action_Taimanin","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaaza.jpg","s":"An intense, gorgeous hack-and-slash action RPG from the Taimanin fame!"},{"t":"AFK Arena","p":["iOS","Android"],"d":"Lilith Games","u":"Lilith Games","g":"Role-playing video game","r":"April 2019","l":"https://en.wikipedia.org/wiki/AFK_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jud.jpg","s":"AFK Arena is a classic RPG with stunning artistic beauty. It is the best RPG for busy you.\nEnjoy 80+ heroes, 7 unique factions, and earn rewards effortlessly!\nJoin players all over the world in this journey of fantasy and prevent an ancient evil from destroying the realm of Esperia."},{"t":"Afterparty","p":["Windows","PlayStation 4","Xbox One"],"u":"Night School Studio","g":"Adventure","r":"October 29","l":"https://en.wikipedia.org/wiki/Afterparty_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tys.jpg","s":"In Afterparty, you are Milo and Lola, recently deceased best buds who suddenly find themselves staring down an eternity in Hell. But there's a loophole: outdrink Satan and he'll grant you re-entry to Earth."},{"t":"Age of Empires II: Definitive Edition","p":["Windows"],"u":"Xbox Game Studios","g":"RTS","r":"November 14","l":"https://www.igdb.com/games/age-of-empires-ii-definitive-edition","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coar0y.jpg","s":"Age of Empires II: Definitive Edition celebrates the 20th anniversary of one of the most popular strategy games ever with stunning 4K Ultra HD graphics, a new and fully remastered soundtrack, and brand-new content, “The Last Khans” with 3 new campaigns and 4 new civilizations."},{"t":"Age of Wonders: Planetfall","p":["Windows","PlayStation 4","Xbox One"],"u":"Paradox Interactive","g":"4X , TBS","r":"August 6","l":"https://www.igdb.com/games/age-of-wonders-planetfall","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r6n.jpg","s":"Age of Wonders: Planetfall is the new strategy game from Triumph Studios, creators of the critically acclaimed Age of Wonders and Overlord series, bringing all the exciting tactical-turn based combat and in-depth 4X empire building of its predecessors to space in an all-new sci-fi setting.\n\nEmerge from the cosmic dark age of a fallen galactic empire to craft a new future for your people. Explore the planetary ruins and encounter other surviving factions that have each evolved in their own way, as you unravel the history of a shattered civilization. Fight, build, negotiate and technologically advance your way to utopia, in a deep single player campaign, on random maps and against friends in multiplayer."},{"t":"Aggelos","p":["PlayStation 4","Xbox One"],"u":"PQube","g":"Action, Platformer","r":"July 12"},{"t":"AI Dungeon","p":["Browser","Windows","macOS","Linux","Android","iOS"],"d":"Latitude","g":"Interactive fiction","r":"December 5, 2019","l":"https://en.wikipedia.org/wiki/AI_Dungeon","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4x76.jpg","s":"An AI-powered text-based RPG like you've never played before. Write stories, interact with realistic characters, and experience virtually infinite worlds and genres. Escape to alternate universes where you direct the action and anything is possible!"},{"t":"AI: The Somnium Files","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Spike Chunsoft","g":"Adventure","r":"September 17","l":"https://www.igdb.com/games/ai-the-somnium-files","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobbvz.jpg","s":"Play as detective Kaname Date on the case of an elusive serial killer in this thrilling, sci-fi murder mystery."},{"t":"Aikatsu on Parade!","p":["Arcade"],"g":"Music, Arcade","l":"https://en.wikipedia.org/wiki/Aikatsu_on_Parade!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8yov.jpg","s":"Aikatsu On Parade! is an arcade collectible card game in Bandai's Data Carddass line of machines. It is the successor to Aikatsu Friends! and a crossover with the past generations of the Aikatsu series."},{"t":"Alien League","p":["Windows"],"u":"Kraken Ink.","g":"Party","r":"March 1"},{"t":"Alien: Isolation","p":["Nintendo Switch"],"u":"Sega","g":"FPS","r":"December 5"},{"t":"Alternate Jake Hunter: Daedalus The Awakening of Golden Jazz","p":["Windows"],"u":"Arc System Works","g":"Adventure","r":"July 4","l":"https://en.wikipedia.org/wiki/Jake_Hunter"},{"t":"Alvastia Chronicles","p":["Windows","Xbox One"],"u":"Kemco","g":"RPG","r":"January 18"},{"t":"Amazing Brick Breaker","p":["Nintendo Switch"],"g":"Puzzle, Arcade","l":"https://en.wikipedia.org/wiki/Amazing_Brick_Breaker","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8cin.jpg","s":"Enjoy easy game control, clear graphic, and the best strike!"},{"t":"American Fugitive","p":["PlayStation 4","Windows","Nintendo Switch","Xbox One"],"d":"Fallen Tree Games","u":"Curve Games","g":"Action-adventure","r":"May 21, 2019","l":"https://en.wikipedia.org/wiki/American_Fugitive","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rdk.jpg","s":"Set in a sleepy American country town in the 1980s, American Fugitive invites you to play as Will Riley. You're no angel, but you're not a killer. Yet the cold-blooded murder of your dad is the crime they've locked you up for. Fuelled by grief and a burning desire for vengeance, you must break out of jail to find the real culprit. It's payback time."},{"t":"American Ninja Warrior: Challenge","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"GameMill Entertainment","g":"Action","r":"March 19"},{"t":"Amid Evil","p":["Windows"],"u":"New Blood Interactive","g":"FPS","r":"June 20","l":"https://en.wikipedia.org/wiki/Amid_Evil","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2pf7.jpg","s":"Once branded a heretic. Now you have been chosen. Reclaim our sacred weapons. Take back our ancestral lands. If you can stand... Amid Evil."},{"t":"Among the Sleep: Enhanced Edition","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Krillbite Studio","g":"Survival horror, Action-adventure","r":"May 28","l":"https://en.wikipedia.org/wiki/Among_the_Sleep"},{"t":"Ancestors: The Humankind Odyssey","p":["Windows","PlayStation 4","Xbox One"],"d":"Panache Digital Games","u":"Private Division","g":"Survival","r":"August 27","l":"https://www.igdb.com/games/ancestors-the-humankind-odyssey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rg8.jpg","s":"Ancestors: The Humankind Odyssey is a single-player survival game played from a third-person view and set in an open world. Players control a member of a hominid clan and manage its needs by eating, drinking, and sleeping while facing predators and other dangers in the wild. Exploring new places and being hunted can trigger a state of fear, which is offset by rewarding actions such as crafting tools and making discoveries. As the clan learns and grows, players unlock new skills through a neural development system and can switch between clan members, passing acquired abilities to future generations. The game has no structured narrative campaign and instead lets players shape their own experience."},{"t":"Angry Birds Go! Turbo Edition","p":[],"l":"https://en.wikipedia.org/wiki/Angry_Birds_Go!_Turbo_Edition"},{"t":"Angry Birds VR: Isle of Pigs","p":["Meta Quest","PlayStation VR","Oculus VR","SteamVR"],"g":"Puzzle","l":"https://en.wikipedia.org/wiki/Angry_Birds_VR:_Isle_of_Pigs","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2dvn.jpg","s":"Join Red, Chuck, Bomb and the Blues to save the stolen eggs in Angry Birds VR: Isle of Pigs, an immersive VR adventure!\n\nExplore the remote island where the greedy green pigs take their vacation in 50+ fun-filled levels (and more to come!) Make your way up to party city through exotic beaches, steep cliffs and snowy slopes, destroying their structures in the most spectacular way to earn those all-important stars.\n\nChoose from different angles to make your slingshot, using classic Angry Birds gameplay elements to progress and strive for the best possible score. Tough boss pigs, balloons, boulders and fans make each level a challenging puzzle in its own right. And using the bird’s special skills - like Chuck’s super speed or Bomb’s explosive power - will help you earn maximum points."},{"t":"Anno 1800","p":["Windows"],"u":"Ubisoft","g":"City builder, RTS","r":"April 16","l":"https://en.wikipedia.org/wiki/Anno_1800","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r67.jpg","s":"Anno 1800: Lead the Industrial Revolution! Welcome to the dawn of the Industrial Age. The path you choose will define your world. Are you an innovator or an exploiter? A conqueror or a liberator? How the world remembers your name is up to you."},{"t":"Anodyne 2: Return to Dust","p":["Windows","macOS","Linux"],"u":"Analgesic Productions","g":"Action-adventure","r":"August 12"},{"t":"Anthem","p":["Windows","PlayStation 4","Xbox One"],"u":"Electronic Arts","g":"Action RPG","r":"February 22","l":"https://en.wikipedia.org/wiki/Anthem_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2n94.jpg","s":"Anthem is a shared-world action RPG, where players can delve into a vast landscape teeming with amazing technology and forgotten treasures. This is a world where Freelancers are called upon to defeat savage beasts, ruthless marauders, and forces plotting to conquer humanity."},{"t":"Ape Out","p":["Windows","Nintendo Switch"],"d":"Gabe Cuzzillo","u":"Devolver Digital","g":"Beat 'em up","r":"February 28, 2019","l":"https://en.wikipedia.org/wiki/Ape_Out","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zta.jpg","s":"Ape Out is a wildly intense and colorfully stylized smash ‘em up about primal escape, rhythmic violence, and frenetic jazz. Build up nearly unstoppable momentum and use your captors as both weapons and shields to crush everyone on your procedurally generated path to freedom."},{"t":"Aperture Hand Lab","p":["Windows"],"d":"Cloudhead Games","u":"Valve","g":"Virtual reality","r":"June 25, 2019","l":"https://en.wikipedia.org/wiki/Aperture_Hand_Lab","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6f1c.jpg","s":"These Aren't Your Daddy's Hands.\n\nThese aren't even your hands. These are precision-tuned sensor-rich re-imaginings of your hands, presented in high-fidelity simulated reality.\n\nIf you've always longed to try these exciting edge-of-your-wrist hand maneuvers, but wanted the chance to practice first in the safety of a non-judgmental virtual world, Aperture Hand Lab is easily in the top three options currently available to you in VR."},{"t":"Apex Legends","p":["Windows","PlayStation 4","Xbox One"],"u":"Electronic Arts","g":"Battle royale, FPS","r":"February 4","l":"https://en.wikipedia.org/wiki/Apex_Legends","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocqh2.jpg","s":"Conquer with character in Apex Legends, a free-to-play Hero shooter where legendary characters with powerful abilities team up to battle for fame & fortune on the fringes of the Frontier.\n\nMaster an ever-growing roster of diverse Legends, deep tactical squad play and bold new innovations that go beyond the Battle Royale experience—all within a rugged world where anything goes. Welcome to the next evolution of Hero Shooter."},{"t":"App Monster - Defense","p":[],"l":"https://en.wikipedia.org/wiki/App_Monster_-_Defense"},{"t":"Aquapark.io","p":["iOS","Android"],"d":"Voodoo","u":"Voodoo","g":"Racing, Indie, Arcade","r":"February 26, 2019","l":"https://www.igdb.com/games/aquapark-dot-io","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ukb.jpg","s":"Reach to the end of the water slide, try to be the first. Bump other players during the race and have fun playing this colorful and sunny water slide game."},{"t":"Aragami: Shadow Edition","p":["Nintendo Switch"],"u":"Lince Works","g":"Action-adventure","r":"February 21","l":"https://en.wikipedia.org/wiki/Aragami_(video_game)"},{"t":"Arcade Spirits","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Fiction Factory Games","u":"PQube","g":"Dating sim, visual novel","l":"https://en.wikipedia.org/wiki/Arcade_Spirits","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co235i.jpg","s":"\"Set in 20XX, Arcade Spirits follows an alternative timeline where the 1983 video game crash never occurred - after a turbulant work history you are granted employment at the Funplex, a popular arcade, home to a host of unique personalities and customers. Where will this new found employment take you? Who will you meet along the way? Will you find the romance you're seeking?\""},{"t":"ARIDA: Backland's Awakening","p":["Windows","Android","iOS"],"d":"Aoca Game Lab","u":"Aoca Game Lab","g":"Adventure and Survival","r":"August 15, 2019","l":"https://en.wikipedia.org/wiki/ARIDA:_Backland's_Awakening","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3xxj.jpg","s":"An adventure game with survival elements in the Brazilian backlands. Explore through the arid regions to collect items, solve quests and find the fate of Cicera."},{"t":"Arise: A Simple Story","p":["PlayStation 4","Windows","Xbox One"],"d":"Piccolo Studio","u":"Untold Tales, Techland","g":"Puzzle-platform","r":"December 3, 2019","l":"https://en.wikipedia.org/wiki/Arise:_A_Simple_Story","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ekb.jpg","s":"Set out on an emotional journey through the bittersweet lives of two people where memories come alive and time bends to your will. Lose yourself in moments of happiness and overcome every hardship as you relive your life’s story. A story of joy and sorrow. A simple story."},{"t":"Arknights","p":["iOS","Android"],"u":"Hypergryph","g":"Tactical RPG, Tower defense","r":"May 1","l":"https://en.wikipedia.org/wiki/Arknights","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4uni.jpg","s":"Take on the role of a key member of Rhodes Island, a pharmaceutical company that fights both a deadly infection and the unrest it leaves in its wake. Together with your leader Amiya, you’ll recruit Operators, train them, then assign them to various operations to protect the innocent and resist those who would thrust the world into turmoil."},{"t":"Art Sqool","p":["Windows","macOS","Nintendo Switch"],"u":"RedDeerGames, Sonka","g":"Art","r":"February 5","l":"https://en.wikipedia.org/wiki/Art_Sqool"},{"t":"Asdivine Dios","p":["Windows","Xbox One"],"u":"Kemco","g":"RPG","r":"June 4","l":"https://en.wikipedia.org/wiki/Asdivine_Dios"},{"t":"Asdivine Hearts 2","p":["PlayStation 4","PlayStation Vita"],"u":"Kemco","g":"RPG","r":"January 15","l":"https://en.wikipedia.org/wiki/Asdivine_Hearts_II"},{"t":"Asdivine Menace","p":["Xbox One"],"u":"Kemco","g":"RPG","r":"August 3","l":"https://en.wikipedia.org/wiki/Asdivine_Menace"},{"t":"Asgard's Wrath","p":["Windows"],"d":"Sanzaru Games","u":"Oculus Studios","g":"Action role-playing","r":"October 10, 2019","l":"https://en.wikipedia.org/wiki/Asgard's_Wrath","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co980d.jpg","s":"Unleash the wrath of the Gods in a mythical Norse adventure that can only unfold in VR. Forge your destiny as both a mortal hero and living god in an action role playing game of unworldly depth."},{"t":"Assassin's Creed III Remastered","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"u":"Ubisoft","g":"Action-adventure, Stealth","r":"March 29","l":"https://en.wikipedia.org/wiki/Assassin%27s_Creed_III_Remastered","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gjw.jpg","s":"Relive the American Revolution or experience it for the first time in Assassin's Creed III Remastered, with enhanced graphics and improved gameplay mechanics.\nAlso includes all the original solo DLC, including The Tyranny of King Washington."},{"t":"Assassin's Creed Odyssey","p":["Stadia"],"u":"Ubisoft Quebec","g":"Action-adventure","r":"November 19","l":"https://en.wikipedia.org/wiki/Assassin%27s_Creed_Odyssey"},{"t":"Assemble with Care","p":["iOS","macOS","tvOS"],"d":"Ustwo","u":"Ustwo","g":"Puzzle","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Assemble_with_Care","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r0i.jpg","s":"From the studio that brought you Monument Valley, comes a story about taking things apart and putting ourselves back together. Assemble With Care tells its evocative story through meaningful, tactile gameplay, vibrant handcrafted visuals and powerful writing."},{"t":"Assetto Corsa Competizione","p":["Windows"],"d":"Kunos Simulazioni","u":"Kunos Simulazioni, 505 Games","g":"Sim racing","r":"May 29, 2019","l":"https://en.wikipedia.org/wiki/Assetto_Corsa_Competizione","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co790f.jpg","s":"Assetto Corsa Competizione, the official GT World Challenge videogame. Thanks to the extraordinary quality of simulation, you will experience the atmosphere of the GT3 championship. Compete against official drivers, teams, cars and official circuits reproduced to the highest quality ever seen."},{"t":"Astral Chain","p":["Nintendo Switch"],"u":"Nintendo","g":"Action","r":"August 30","l":"https://en.wikipedia.org/wiki/Astral_Chain","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobd39.jpg","s":"Astral Chain is a stylish action game that blends fast-paced combat with investigation elements. Players fight alongside a controllable companion called a Legion, using coordinated attacks, restraints, and abilities to overcome enemies and solve environmental challenges.\nThe game mixes high-energy battles with exploration and light detective work, offering varied gameplay and a strong focus on fluid, dual-character combat."},{"t":"Astrologaster","p":["iOS","Windows","macOS"],"d":"Nyamyam","u":"Nyamyam","g":"Strategy, Adventure, Indie, Visual Novel","r":"May 2, 2019","l":"https://en.wikipedia.org/wiki/Astrologaster","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1i6a.jpg","s":"Astrologaster is an astrological comedy game in which you take the role of Simon Forman, Elizabethan Astrologer and doctor. Cast and interpret astrological charts to answer your patients' questions about political intrigues, romantic entanglements, deadly illnesses and missing spoons."},{"t":"Astroneer","p":["Windows","Xbox One","PlayStation 4"],"d":"System Era Softworks","u":"System Era Softworks","g":"Sandbox, adventure","r":"February 6, 2019","l":"https://en.wikipedia.org/wiki/Astroneer","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobyfe.jpg","s":"Interact with strange new worlds in a unique and tactile way, molding the environment itself as if it were clay in your hands. Build your base, master resource management, automate your production lines, and more as you unravel the mysteries of the universe, alone or with friends."},{"t":"At the Gates","p":["Windows"],"u":"Conifer Games","g":"4X , Strategy","r":"January 23","l":"https://en.wikipedia.org/wiki/At_the_Gates_(video_game)"},{"t":"Atelier Lulua: The Scion of Arland","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Koei Tecmo","g":"RPG","r":"May 21"},{"t":"Atelier Ryza: Ever Darkness & the Secret Hideout","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Koei Tecmo","g":"RPG","r":"October 29","l":"https://www.igdb.com/games/atelier-ryza-ever-darkness-and-the-secret-hideout","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20uc.jpg","s":"The next game in the Atelier franchise and the start of a new series of games.\n\nThe collection system has been redesigned, the items found are the same but different tools or actions will be required to find them at collection points.\nThe crafting system has been updated and a new item making system has been added, to be revealed at a later date.\nThe turn-based combat is getting changed in some fashion to make it more tense, also to be revealed later."},{"t":"Attack on Titan 2: Final Battle","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One","Stadia"],"u":"Koei Tecmo","g":"Action","r":"July 5","l":"https://en.wikipedia.org/wiki/Attack_on_Titan_2"},{"t":"Away: Journey to the Unexpected","p":["PlayStation 4","Nintendo Switch","Xbox One","Windows"],"d":"Aurélien Regard Games","u":"Dear Villagers","g":"Action-adventure","r":"February 5, 2019","l":"https://en.wikipedia.org/wiki/Away:_Journey_to_the_Unexpected","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/aspc6oouotr45wtsukuj.jpg","s":"Away: Journey to the Unexpected is a colorful first person adventure game that combines action, negotiation and rogue-lite elements\n\nProgress through the levels and the story, choose your path, but above all, recruit allies. All the strange characters you meet in game can be played in first person, and it’s up to you to find the right answers to get them to join your team!\n\nIdiotic workmen, mysteries from outer space, oddball friends, and fast combat await!"},{"t":"Azur Lane","p":[],"l":"https://en.wikipedia.org/wiki/Azur_Lane"},{"t":"Azur Lane: Crosswave","p":["PlayStation 4"],"u":"Idea Factory","g":"Action RPG","r":"August 29"},{"t":"Baba Is You","p":["Windows","Nintendo Switch"],"u":"Hempuli","g":"Puzzle","r":"March 13","l":"https://en.wikipedia.org/wiki/Baba_Is_You","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hqt.jpg","s":"Baba Is You is a puzzle game where you can change the rules by which you play. In every level, the rules themselves are present as blocks you can interact with; by manipulating them, you can change how the level works and cause surprising, unexpected interactions! With some simple block-pushing you can turn yourself into a rock, turn patches of grass into dangerously hot obstacles, and even change the goal you need to reach to something entirely different."},{"t":"Bail or Jail","p":["Nintendo Switch"],"d":"Free Style","u":"Konami","g":"Action","r":"August 1, 2019","l":"https://en.wikipedia.org/wiki/Bail_or_Jail","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4uy6.jpg","s":"A 3 minute tag-battle with extra twists! Play as a Monster who must lock everyone into jail before time runs out, or as a Human who must avoid capture and bail their teammates out of trouble. Invite your friends and family to play this speedy game of cat and mouse - or rather, Monsters and Humans!"},{"t":"Bakutsuri Hunters","p":[],"l":"https://en.wikipedia.org/wiki/Bakutsuri_Hunters"},{"t":"Balconing Simulator 2020","p":["Windows"],"u":"Humble Publishing","g":"Simulation","r":"December 13"},{"t":"Baldur's Gate II: Enhanced Edition","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Skybound Games","g":"RPG","r":"September 24"},{"t":"Baldur's Gate: Enhanced Edition","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Skybound Games","g":"RPG","r":"September 24"},{"t":"Baldur's Gate: Siege of Dragonspear","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Skybound Games","g":"RPG","r":"September 24"},{"t":"Ball Attraction","p":["Nintendo Switch"],"l":"https://en.wikipedia.org/wiki/Ball_Attraction","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co571k.jpg","s":"Ball attraction is an easy, simple but challenge game."},{"t":"Barry Bradford's Putt Panic Party","p":["Nintendo Switch"],"g":"Sport, Arcade","l":"https://en.wikipedia.org/wiki/Barry_Bradford's_Putt_Panic_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5726.jpg","s":"Tee off with up to three friends simultaneously for maximum fun! You have a limited time to aim your shot and the timer gets shorter every turn! It’s a party of putting with panic guaranteed. - Party and Single modes. - Three difficulty settings. - Forward and reverse holes. - Four unique courses. - Loads of wacky hazards. Bring your friends, select your characters and get ready to Putt Panic Party all night long with the world's greatest Putt Panic Party Player, Barry Bradford!"},{"t":"Battalion 1944","p":["Windows"],"d":"Bulkhead","u":"Square Enix Collective","g":"First-person shooter","r":"May 23, 2019","l":"https://en.wikipedia.org/wiki/Battalion_1944","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6y56.jpg","s":"Battalion Legacy recaptures the core of classic multiplayer shooters and propels WW2 into the next generation. Battalion Legacy utilizes the most advanced industry technology to create a visceral and heart-thumping multiplayer experience that has been crafted by the designers who have grown up playing Medal of Honor and Call of Duty 2.\n\nFight in real world locations such as the streets of Carentan, the forests of Bastogne and many more in our spiritual successor to the great multiplayer shooters of the past. Precise aim with your Kar98, covering fire with your M1 Garand and quick thinking with your Thompson are key to your success, all packaged into a competitive multiplayer environment. In short, Battalion Legacy is an infantry based first person shooter with an emphasis on raw skill. No grinding, no 'exosuits', just you and your skill as a player.\n\nJoin a Battalion and compete season to season with BattleRank, our global competition system. Contribute to your Battalion's season objective to earn cosmetic rewards for your character, weapons and accessories within our realistic art style. Flaunt your success through your player profile to become a renowned player within the community. BattleRank’s highly tuned stat tracking system enables Battalion Legacy to go beyond the standard mould of shooters gone by and enables players to compete globally for rewards, glory and honour.\n\nFuelled by the power of Unreal Engine 4, Battalion Legacy resurges World War 2 back into the modern gaming spotlight in our spiritual successor to the great multiplayer shooters of the past such as Call of Duty 2 and Enemy Territory. On BattleRank, it’s down to skilled soldiers like you to fight for your battalion."},{"t":"Battle & Crash","p":["Nintendo Switch"],"g":"Arcade","l":"https://en.wikipedia.org/wiki/Battle_&_Crash","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5a3b.jpg","s":"Battle & Crash is a Car Battle Action Game in which you take out car after car in a battle royal to achieve victory. Compete for unique Rifles, Missiles, Lasers, and clash and take out your enemies in an ultimate battle royal! This game contains 3 game modes: \"Battle League\", \"Team Battle\", and \"Survival\". All game modes can be played by up to 4 Players."},{"t":"Battle Worlds: Kronos","p":["Nintendo Switch"],"u":"THQ Nordic","g":"TBS","r":"June 11"},{"t":"Battlefleet Gothic: Armada 2","p":["Windows"],"u":"Focus Home Interactive","g":"Strategy, RTT","r":"January 24"},{"t":"BattoJutsu","p":["Nintendo Switch"],"g":"Fighting","l":"https://en.wikipedia.org/wiki/BattoJutsu","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co572j.jpg","s":"\"Battojutsu\" is a simple fighting game that you can play with your Family and Good Friends."},{"t":"Bayani: Fighting Game","p":["Windows"],"d":"Ranida Games","g":"Fighting","r":"June 12, 2019","l":"https://en.wikipedia.org/wiki/Bayani:_Fighting_Game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2f5n.jpg","s":"Bayani is the first All-Filipino made fighting game that is heavily inspired by the Philippines’ rich history, culture, and mythology."},{"t":"Beat Saber","p":["Windows","PlayStation 4","Meta Quest"],"d":"Beat Games","u":"Beat Games","g":"Rhythm","r":"May 21, 2019","l":"https://en.wikipedia.org/wiki/Beat_Saber","i":"images/steam-620980.jpg","s":"Slash the beats, get moving, and experience the world's most popular VR rhythm game!* Duck, dodge, and flow through 300+ handcrafted songs from artists like Coldplay, Imagine Dragons, and Metallica. Play solo, compete online, or pass the headset at your next party. Jump in with 60+ songs included!"},{"t":"Beats Runner","p":["Nintendo Switch"],"g":"Music, Platform, Adventure","l":"https://en.wikipedia.org/wiki/Beats_Runner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4dq3.jpg","s":"Beats Runner is a bite-sized retro-cyberpunk rhythm action platform game. Just follow the beats and rush forward! Caution for the spikes and traps! Rush forward and collect as much stars and coins as possible!Unlock unique characters for more fun, and level up for more challenges!"},{"t":"Beyond Enemy Lines: Covert Operations","p":["Nintendo Switch"],"g":"Shooter","l":"https://en.wikipedia.org/wiki/Beyond_Enemy_Lines:_Covert_Operations","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co572s.jpg","s":"Think your way in, observe the enemies and sneak into their base and complete your objective. You have the total freedom to choose your path - guns blazing or silent assassin - it's your choice! Beyond Enemy Lines is an unforgiving, intense experience where skill and tactical decisions matter! Beyond Enemy Lines: Covert Operations is taking the unique Beyond Enemy Lines gameplay to the Nintendo Switch. And is one of the first hardcore tactical FPS for Nintendos console. Beyond Enemy Lines: Covert Operations is a port of the 8 mission long story campaign of Beyond Enemy Lines from 2017. It contains the full experience of it's PCs bigger brother. While running on an entirly new game core directly adapted for the use on Nintendo Switch."},{"t":"Beyond: Two Souls","p":["Windows"],"u":"Quantic Dream","g":"Interactive drama","r":"July 22"},{"t":"Black Future '88","p":["Windows","Nintendo Switch"],"d":"SUPERSCARYSNAKES","u":"Good Shepherd Entertainment","g":"Roguelike","r":"November 21, 2019","l":"https://en.wikipedia.org/wiki/Black_Future_'88","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wni.jpg","s":"Climb a procedural tower in an alternate version of 1988 to kill its insane owner. Then do it again, and again. The constantly evolving world is influenced by other players as you experience this bold and wildly exciting dungeon crawler."},{"t":"Blacksad: Under the Skin","p":["Windows","macOS","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Pendulo Studios, YS Interactive","u":"Microïds","g":"Adventure","r":"November 5, 2019","l":"https://en.wikipedia.org/wiki/Blacksad:_Under_the_Skin","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsoo.jpg","s":"BLACKSAD: Under the Skin - A dark corruption scandal in the heart of the New York City's underworld for charismatic detective John Blacksad!\n\nBased on the noir comic series by the same name. The game features a noir detective story about a PI by the name of Blacksad that gets dragged into the case of a murdered boxing club. The game feature an interactive system much reminiscent of Grim Fandango where you have direct control of the character and only things that catch his gaze is interactable."},{"t":"Blair Witch","p":["Windows","Xbox One","PlayStation 4"],"u":"Lionsgate Games","g":"Survival horror","r":"August 30","l":"https://en.wikipedia.org/wiki/Blair_Witch_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobtgz.jpg","s":"Inspired by the cinematic lore of Blair Witch, experience a new story-driven psychological horror game that studies your reactions to fear and stress.\n\nA story of the human descent into darkness.\nExperience an original story based on the legend of Blair Witch from the makers of Layers of Fear.\n\nFind the way through the haunted woods.\nNavigate your way through a cursed forest that warps and distorts both time and space.\n\nYour sanity against her curse.\nStand against the horrors of the Blair Witch and the decaying sanity of a man burdened by his past.\n\nHow will you face your fears?\nHow you react to danger and behave under pressure will ultimately teach you more about yourself."},{"t":"Blasphemous","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"The Game Kitchen","u":"Team17","g":"Metroidvania","r":"September 10, 2019","l":"https://en.wikipedia.org/wiki/Blasphemous_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob0xj.jpg","s":"Blasphemous is a punishing action-platformer that combines the fast-paced, skilled combat of a hack-n-slash game with a deep and evocative narrative core. Explore this nightmarish world of twisted religion and discover its many secrets hidden deep inside. Use devastating combos and brutal executions to smite the hordes of grotesque monsters and titanic bosses, who are all ready to rip your limbs off. Locate and equip relics, rosary beads and prayers that call on the powers of the heavens to aid you in your quest to break your eternal damnation."},{"t":"Blaster Master","p":["Nintendo Switch"],"g":"Platformer, Run and gun, Metroidvania","r":"January 16","l":"https://en.wikipedia.org/wiki/Blaster_Master_(video_game)"},{"t":"Blaster Master Zero","p":["Windows"],"u":"Inti Creates","g":"Action, Platformer","r":"June 14","l":"https://en.wikipedia.org/wiki/Blaster_Master_Zero"},{"t":"BlazBlue: Central Fiction","p":["Nintendo Switch"],"u":"Arc System Works","g":"Fighting","r":"February 7"},{"t":"Blazing Chrome","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"The Arcade Crew","g":"Run and gun","r":"July 11","l":"https://en.wikipedia.org/wiki/Blazing_Chrome","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rs5.jpg","s":"Blazing Chrome is a classic co-op run 'n gun with an original arcade feel. Players can choose between Mavra, the badass human resistance, soldier or Doyle, the groovy rebel robot, to kick some metal ass."},{"t":"Bleak Sword","p":["iOS","macOS","tvOS"],"d":"more8bit","u":"Devolver Digital","g":"Action role-playing","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Bleak_Sword","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4a5c.jpg","s":"Bleak Sword is a dark fantasy action game tasking players to struggle across compact, cursed diorama battlefields. Through nine tense chapters, heroes must lift the curse of the legendary Bleak Sword by striking down all manner of creatures in every forest, swamp, castle, and dungeon on their journey. Invoke powerful magic, uncover helpful items, and level up your character to upgrade your stats before facing down menacing guardians. Once the curse has been lifted the challenging Arena Mode and thirty unlockable achievements await even the most accomplished warrior.\n\nBleak Sword is designed to be able to play it easily with elegant controls allowing heroes to roll, parry, attack and counter-attack using basic movements on gamepads and touch controls. Scored by award-winning composer Jim Guthrie with sound by famed designer Joonas Turner."},{"t":"Blindy","p":["Nintendo Switch"],"g":"Platform, Arcade","l":"https://en.wikipedia.org/wiki/Blindy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coak2x.jpg","s":"It is not a unfair platformer but its very challenging."},{"t":"Blood & Truth","p":["PlayStation 4"],"u":"Sony Interactive Entertainment","g":"FPS","r":"May 28","l":"https://en.wikipedia.org/wiki/Blood_%26_Truth"},{"t":"Blood: Fresh Supply","p":["Windows"],"g":"Shooter","l":"https://en.wikipedia.org/wiki/Blood:_Fresh_Supply","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7y87.jpg","s":"Originally released in 1997, Blood is a First-Person Shooter that helped redefine the genre and introduced many elements now accepted as commonplace. In the original and the updated Blood: Fresh Supply, players jump into the boots of undead gunslinger Caleb as he seeks revenge against the dark god Chernobog. Caleb’s arsenal features a mix of standard and occult weaponry, which he uses to devastating and gore-filled effect. In the game, players visit a terrifying world populated by hordes of bloodthirsty fiends – including cultists, gargoyles, zombies, hellhounds, and an unholy host of other terrors.\n\nThis remaster makes several graphical improvements and adds several multiplayer modes, as well as improved mod support."},{"t":"Bloodstained: Ritual of the Night","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"u":"505 Games","g":"Metroidvania, Action-adventure","r":"June 18","l":"https://www.igdb.com/games/bloodstained-ritual-of-the-night","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobc4a.jpg","s":"Bloodstained: Ritual of the Night is a gothic horror action side-scrolling RPG set in 19th century England. A paranormal force has summoned a demon-infested castle, revealing crystal shards infused with tremendous magical power.\n\nPlay as Miriam, an orphan scarred by an alchemist's curse which slowly crystallizes her body. To save humanity, and herself in the process, Miriam must fight through the castle and defeat the summoner, Gebel.\n\nCollect, craft and unlock a vast array of weapons, equipment and loot to defeat the countless minions and bosses of hell that await!"},{"t":"Bonds of the Skies","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Kemco","g":"RPG","r":"March 14","l":"https://en.wikipedia.org/wiki/Bonds_of_the_Skies"},{"t":"Boneworks","p":["Windows"],"u":"Stress Level Zero","g":"FPS","r":"December 10","l":"https://en.wikipedia.org/wiki/Boneworks"},{"t":"Borderlands 3","p":["Windows","PlayStation 4","Xbox One","Stadia"],"u":"2K Games","g":"FPS","r":"September 13","l":"https://en.wikipedia.org/wiki/Borderlands_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20r3.jpg","s":"Borderlands 3 is a first-person looter shooter set seven years after the events of Borderlands 2. Players select one of four new Vault Hunters and travel across multiple planets to stop Troy and Tyreen Calypso, twin cult leaders seeking to harness the power of alien Vaults scattered throughout the galaxy. The game features procedurally generated weapons, cooperative multiplayer for up to four players, expanded skill trees with multiple action skills per character, and new traversal mechanics including sliding and mantling."},{"t":"Borderlands: Game of the Year Enhanced","p":["Windows"],"d":"Gearbox Software, Blind Squirrel Games","u":"2K","g":"Shooter, Role-playing (RPG)","r":"April 3, 2019","l":"https://www.igdb.com/games/borderlands-game-of-the-year-enhanced","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qqa.jpg","s":"Borderlands: Game of the Year Enhanced is a co‑op shooter‑looter where four distinct vault hunters hunt for alien secrets on the lawless world of Pandora, collecting procedurally generated weapons, driving into frenetic vehicular combat, and tackling DLC campaigns solo or with up to four players.\nThis enhanced edition adds higher‑resolution character models, environments, weapons, and textures (4K support), new weapon variants and character heads, new gold chests and keys, and includes all four original add‑on campaigns, while preserving the game’s signature cel‑shaded art and chaotic co‑op gameplay."},{"t":"Bouncy Bullets","p":["PlayStation 4","PlayStation Vita","Xbox One","Nintendo Switch"],"d":"Petite Games","u":"Ratalaika Games","g":"Platform, shooter","r":"July 9, 2019","l":"https://en.wikipedia.org/wiki/Bouncy_Bullets","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24ga.jpg","s":"In a world where the sky is blue and water is pink, with icebergs replaced by floating ice-creams, Bouncy Bullets is a colourfully vibrant first-person shooter that will task players to traverse wonderful terrains, in a bid to reach the portal that awaits them at the end of every level!"},{"t":"BoxBoy! + BoxGirl!","p":["Nintendo Switch"],"u":"Nintendo","g":"Puzzle-platformer","r":"April 26","l":"https://en.wikipedia.org/wiki/BoxBoy!_%2B_BoxGirl!"},{"t":"Brain Age: Nintendo Switch Training","p":["Nintendo Switch"],"u":"Nintendo","g":"Puzzle","r":"December 27"},{"t":"Brawl Brothers","p":["Nintendo Switch"],"g":"Brawler","r":"September 5","l":"https://en.wikipedia.org/wiki/Brawl_Brothers"},{"t":"Breaking Bad: Criminal Elements","p":["iOS","Android"],"g":"Real Time Strategy (RTS), Strategy","l":"https://en.wikipedia.org/wiki/Breaking_Bad:_Criminal_Elements","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gez.jpg","s":"Run your own meth business alongside your favourite characters from the hit AMC show Breaking Bad."},{"t":"Breath of Fire","p":["Nintendo Switch"],"g":"RPG","r":"September 5","l":"https://en.wikipedia.org/wiki/Breath_of_Fire_(video_game)"},{"t":"Breath of Fire II","p":["Nintendo Switch"],"g":"RPG","r":"December 12","l":"https://en.wikipedia.org/wiki/Breath_of_Fire_II"},{"t":"Bright Memory","p":["Windows"],"u":"FYQD Personal Studio","g":"FPS","r":"January 12","l":"https://en.wikipedia.org/wiki/Bright_Memory"},{"t":"Brothers: A Tale of Two Sons","p":["Nintendo Switch"],"u":"505 Games","g":"Adventure","r":"May 28"},{"t":"BTS World","p":["iOS","Android"],"d":"Takeone Company Corp","u":"Netmarble","g":"Visual novel","r":"June 26, 2019","l":"https://en.wikipedia.org/wiki/BTS_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m3g.jpg","s":"The world turns upside down the moment you grab the ticket. When you open your eyes, you’re somewhere unfamiliar, back in the year 2012. Wait, you’re a BigHit employee? \n \nYou've just become BTS's manager in a world where BTS doesn't even exist yet. Their debut is now in your hands!"},{"t":"Bubble Cats Rescue","p":["Nintendo Switch"],"g":"Puzzle, Arcade","l":"https://en.wikipedia.org/wiki/Bubble_Cats_Rescue","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co576m.jpg","s":"Experience an adventure and join Alice the Cat as she races around the world to free all of her baby kitties! They need your help! Rescue them from the evil bubbles. You’ll need to be skillful and accurate. With awesome next-generation physics, spectacular chain reactions, amazing power-ups and countless levels... Bubble Cats Rescue takes your gaming experience to the next level. Start your adventure today. Shoot the bubbles!"},{"t":"Bubsy: Paws on Fire!","p":["Windows","PlayStation 4"],"u":"UFO Interactive Games","g":"Platformer","r":"May 16"},{"t":"Bug Fables: The Everlasting Sapling","p":["Windows"],"d":"Moonsprout Games","u":"Dangen Entertainment","g":"Role-playing","r":"November 21, 2019","l":"https://en.wikipedia.org/wiki/Bug_Fables:_The_Everlasting_Sapling","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6r8x.jpg","s":"Bug Fables: The Everlasting Sapling is an adventure RPG following three heroes, Vi, Kabbu, and Leif, as they embark on an epic quest in Bugaria in search of treasure and immortality. The game combines flat objects with 3D physics as the player jumps and utilizes the heroes’ unique abilities to solve puzzles and stun enemies while exploring a variety of unique, colorful areas. Battles are turn-based and with timed button inputs that can enhance your abilities."},{"t":"Bullet Battle: Evolution","p":["Nintendo Switch"],"l":"https://en.wikipedia.org/wiki/Bullet_Battle:_Evolution","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5aw1.jpg","s":"Team up with friends (or even your enemies!), strategize and defeat your foes in this top-tier multiplayer TPS. With graphics this good, you'd swear you were really there."},{"t":"BurgerTime Party!","p":["Nintendo Switch"],"u":"Xseed Games","g":"Action, Puzzle","r":"October 8","l":"https://en.wikipedia.org/wiki/BurgerTime_Party"},{"t":"Bustafellows","p":["Nintendo Switch","iOS","Android"],"d":"Nippon Cultural Broadcasting Extend","u":"Nippon Cultural Broadcasting Extend, PQube","g":"Visual novel, otome game","r":"December 19, 2019","l":"https://en.wikipedia.org/wiki/Bustafellows"},{"t":"Cadence of Hyrule","p":["Nintendo Switch"],"u":"Nintendo","g":"Roguelike, Rhythm","r":"June 13","l":"https://en.wikipedia.org/wiki/Cadence_of_Hyrule"},{"t":"Cadence of Hyrule: Crypt of the NecroDancer Featuring the Legend of Zelda","p":["Nintendo Switch"],"d":"Brace Yourself Games","u":"Nintendo, Spike Chunsoft","g":"Music, Adventure","r":"June 13, 2019","l":"https://www.igdb.com/games/cadence-of-hyrule-crypt-of-the-necrodancer-featuring-the-legend-of-zelda","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob88s.jpg","s":"Cadence of Hyrule: Crypt of the NecroDancer Featuring The Legend of Zelda is a rhythmic action-adventure game where you can enjoy the gameplay of Crypt of the NecroDancer in the setting of The Legend of Zelda series. As Link - or even as Princess Zelda - you'll explore the randomly generated overworld and procedurally generated dungeons on a quest to save Hyrule. Every beat of each remixed Legend of Zelda tune is a chance to move, attack, defend, and more, so stay one step ahead of each enemy and boss… or face the music."},{"t":"Café Enchanté","p":["Nintendo Switch"],"g":"Simulator, Adventure","l":"https://en.wikipedia.org/wiki/Caf%C3%A9_Enchant%C3%A9","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jrh.jpg","s":"Café Enchanté is an otome visual novel. Prepare for chaos as handsome beings from different worlds step through a magical portal into your café! Learn more about your new companions and your grandfather as more surprises show up at your door. Discover an enchanting, uplifting, coffee-fueled tale filled with magic, monsters, and mysteries."},{"t":"Call of Duty: Mobile","p":["iOS","Android"],"u":"Activision","g":"FPS, Battle royale","r":"October 1","l":"https://www.igdb.com/games/call-of-duty-mobile","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vqe.jpg","s":"The Call of Duty you know and love now on your mobile device. With classic multiplayer modes such as Team Deathmatch, Domination, and Kill-Confirmed on iconic maps such as Shipment, Raid, and Standoff, as well as 100 player Battle Royale, Call of Duty: Mobile has it all!"},{"t":"Call of Duty: Modern Warfare","p":["Windows","PlayStation 4","Xbox One"],"u":"Activision","g":"FPS","r":"October 25","l":"https://www.igdb.com/games/call-of-duty-modern-warfare","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rsg.jpg","s":"Call of Duty: Modern Warfare is a first-person shooter that serves as a reboot of the Modern Warfare sub-series. The game features a single-player campaign, cooperative Special Ops missions, and a multiplayer suite with cross-platform play. The campaign emphasizes tactical realism, with morally complex scenarios, civilian threat assessments, and night-vision operations. Multiplayer introduces a revised gunplay system with extensive weapon customization, a Realism mode that removes the HUD, a Ground War mode supporting over 100 players, and a 2v2 Gunfight mode. Post-launch, the game received the free-to-play battle royale mode Warzone. The traditional season pass was replaced with free content updates delivered through seasonal battle passes."},{"t":"Caravan Stories","p":["PlayStation 4"],"u":"Aiming","g":"MMO, RPG","r":"September 10"},{"t":"Card of Darkness","p":["iOS","tvOS","macOS"],"d":"Zach Gage, Choice Provisions","u":"Zach Gage","g":"Puzzle","l":"https://en.wikipedia.org/wiki/Card_of_Darkness","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21c1.jpg","s":"Embark on an epic hand-animated adventure in Card of Darkness. Cast powerful spells, slay fantastic monsters, discover ancient secrets, and ultimately save the world - just by picking up the right cards. Card of Darkness is a full-featured adventure designed around an accessible, minimalist, card game core."},{"t":"Case Closed Skateboard Run: Phantom Thief Kid and the Mysterious Treasures","p":[],"l":"https://en.wikipedia.org/wiki/Case_Closed_Skateboard_Run:_Phantom_Thief_Kid_and_the_Mysterious_Treasures"},{"t":"Castlevania Anniversary Collection","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Konami","g":"Platformer","r":"May 16","l":"https://en.wikipedia.org/wiki/Castlevania_Anniversary_Collection"},{"t":"Castlevania: Grimoire of Souls","p":["Android","iOS"],"g":"Platform, Role-playing (RPG), Adventure","l":"https://en.wikipedia.org/wiki/Castlevania:_Grimoire_of_Souls","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co69wd.jpg","s":"Castlevania: Grimoire of Souls is a side-scrolling action RPG with characters from previous games available to be played.\n\nThe game also has an up to 4 player boss-rush mode as well as a 4v4 PvP mode.\n\nApart from the 2 new main characters, Genya Arikado and Lucy, 6 returning characters have been revealed:\nAlucard (Castlevania: Symphony of the Night)\nSimon Belmont (Castlevania)\nCharlotte Aulin (Castlevania: Portrait of Ruin)\nMaria Renard (Castlevania: Rondo of Blood)\nSoma Cruz (Castlevania: Aria of Sorrow)\nShanoa (Castlevania: Order of Ecclesia)"},{"t":"Cat Quest II","p":["iOS","macOS","PlayStation 4","Windows","Xbox One","Nintendo Switch"],"d":"The Gentlebros","u":"PQube","g":"Action role-playing","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Cat_Quest_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r4f.jpg","s":"Cat Quest II, a fantasy action-adventure RPG, returns to the world of Felingard to expand on the original with more explosive spells, expanded weapon options, an exciting new character switch mechanic, and local co-op! Play as both a cat and dog as you explore their kingdoms solo or with a friend! Quest in a world filled with magic, curious monsters, and go on a catventure like never before!"},{"t":"Catherine Classic","p":["Windows"],"u":"Sega","g":"Puzzle","r":"January 10","l":"https://en.wikipedia.org/wiki/Catherine_(video_game)"},{"t":"Catherine: Full Body","p":["PlayStation 4"],"u":"Atlus","g":"Puzzle-platformer","r":"September 3","l":"https://www.igdb.com/games/catherine-full-body","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e3g.jpg","s":"Catherine: Full Body is an enhanced remaster of the adult-oriented puzzle-platformer Catherine. Full Body features a new love interest, online multiplayer, new puzzle mechanics, harder difficulties, new story segments, and new endings."},{"t":"Cell to Singularity","p":["iOS"],"g":"Incremental , Educational","r":"August 29","l":"https://en.wikipedia.org/wiki/Cell_to_Singularity"},{"t":"Chaos;Child","p":["Windows"],"u":"Spike Chunsoft","g":"Visual novel","r":"January 22","l":"https://en.wikipedia.org/wiki/Chaos;Child"},{"t":"ChessCraft","p":["Android"],"g":"Strategy","l":"https://en.wikipedia.org/wiki/ChessCraft","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5cnm.jpg","s":"Never play the same game of chess again! ChessCraft is a chess AI sandbox. Create your own chess boards, rules, and pieces. Play against the computer or your friends online, or win loot by playing one of 80 built-in chess boards in adventure mode."},{"t":"Chiki-Chiki Boxy Pro Wrestling","p":["Nintendo Switch"],"g":"Fighting, Sport","l":"https://en.wikipedia.org/wiki/Chiki-Chiki_Boxy_Pro_Wrestling","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m5t.jpg","s":"Voxel wrestlers intensely and furiously slamming into each other!Enjoy the fun, over the top moves that this game has to offer!\n\nThe battle gong sounds! Make your way through the tournament, aiming for the top!\n\nThe controls are easy! You can bust out flashy moves with just a single button.\n\nUnleash jump attacks, drops, holds, and specials, carrying them out just how you think of them!\n\nUp to 6 players can play. Compete in intense battles with players from all around the world!\n\nCombine your favorite parts and moves to create your very own custom wrestler!"},{"t":"Children of Morta","p":["Windows","macOS","PlayStation 4","Xbox One","Nintendo Switch"],"u":"11 Bit Studios","g":"Action RPG","r":"September 3","l":"https://en.wikipedia.org/wiki/Children_of_Morta","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsbm.jpg","s":"Children of Morta is a narrative driven hack and slash roguelike. Take on the role of a member of the Bergson family, the Guardians of Mount Morta, as you fight desperately against the Corruption. Experience not only what it means to be a hero, but to be part of a family that bears the weight of the mountain together."},{"t":"Chocobo's Mystery Dungeon Every Buddy!","p":["Nintendo Switch","PlayStation 4"],"u":"Square Enix","g":"RPG, Roguelike","r":"March 20","l":"https://en.wikipedia.org/wiki/Chocobo%27s_Mystery_Dungeon_Every_Buddy!"},{"t":"Ciconia When They Cry – Phase 1: For You, the Replaceable Ones","p":["Windows","macOS"],"u":"07th Expansion , MangaGamer","g":"Visual novel","r":"October 4","l":"https://en.wikipedia.org/wiki/Ciconia_When_They_Cry"},{"t":"City Connection","p":["Nintendo Switch"],"g":"Platformer","r":"June 12","l":"https://en.wikipedia.org/wiki/City_Connection"},{"t":"Civilization VI: Gathering Storm","p":["Windows","macOS","Linux","Nintendo Switch","PlayStation 4","Xbox One","Android"],"d":"Firaxis Games","u":"2K Games","g":"Turn-based strategy, 4X","r":"February 14, 2019","l":"https://en.wikipedia.org/wiki/Civilization_VI:_Gathering_Storm"},{"t":"Clannad","p":["Nintendo Switch"],"u":"Prototype","g":"Visual novel","r":"July 4","l":"https://en.wikipedia.org/wiki/Clannad_(visual_novel)"},{"t":"Classic Games Collection Vol.1","p":[],"l":"https://en.wikipedia.org/wiki/Classic_Games_Collection_Vol.1"},{"t":"Close to the Sun","p":["Windows"],"u":"Wired Productions","g":"Adventure, Survival horror","r":"May 2","l":"https://en.wikipedia.org/wiki/Close_to_the_Sun_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1klo.jpg","s":"Close to the Sun is a story-driven horror game that takes place at the turn of the 20th century on a mysterious ship complex created by Nikola Tesla for the sake of knowledge. In this alternative version of history, his scientific breakthroughs have already had a major impact on the world. You’re a young journalist looking for your sister and, as you approach this enormous and glorious complex for the first time, you quickly realize that something there has gone horribly wrong...\""},{"t":"Clu Clu Land","p":["Nintendo Switch"],"g":"Puzzle","r":"May 15","l":"https://en.wikipedia.org/wiki/Clu_Clu_Land"},{"t":"Clu Clu Land: Welcome to New Cluclu Land","p":["Nintendo Switch"],"g":"Puzzle","r":"May 15","l":"https://en.wikipedia.org/wiki/Clu_Clu_Land#Legacy"},{"t":"Code 7: Episode 2 — Memory and Episode 3 — Backdoor","p":["Windows","macOS","Linux"],"u":"Goodwolf Studio","g":"Adventure","r":"April 12"},{"t":"Code Vein","p":["Windows","PlayStation 4","Xbox One"],"u":"Bandai Namco Entertainment","g":"Action RPG","r":"September 27","l":"https://en.wikipedia.org/wiki/Code_Vein","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r69.jpg","s":"Code Vein is set in the not too distant future where a disaster has brought the world to ruin and vampire-like beings battle for dominance."},{"t":"Collection of Mana","p":["Nintendo Switch"],"u":"Square Enix","g":"Action RPG","r":"June 11","l":"https://en.wikipedia.org/wiki/Collection_of_Mana"},{"t":"Collide-a-Ball 2","p":["Nintendo Switch"],"g":"Puzzle, Simulator","l":"https://en.wikipedia.org/wiki/Collide-a-Ball_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co57al.jpg","s":"Roll the balls towards the goal."},{"t":"Command: Modern Air Naval Operations","p":["Windows"],"d":"Warfare Sims","u":"Matrix Games","g":"Real-time strategy, warfare","l":"https://en.wikipedia.org/wiki/Command:_Modern_Air_Naval_Operations"},{"t":"Conarium","p":["PlayStation 4","Xbox One"],"u":"Iceberg Interactive","g":"Adventure","r":"February 12","l":"https://en.wikipedia.org/wiki/Conarium_(video_game)"},{"t":"Concrete Genie","p":["PlayStation 4"],"u":"Sony Interactive Entertainment","g":"Action-adventure","r":"October 8","l":"https://en.wikipedia.org/wiki/Concrete_Genie","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3u25.jpg","s":"Concrete Genie is a game about Ash, a young boy who is bullied but discovers a magical paint that might save his home town."},{"t":"Conqueror's Blade","p":["Windows"],"d":"Booming Tech","u":"My.com, Mail.ru","g":"Real-time tactics, MMO","r":"June 24, 2019","l":"https://en.wikipedia.org/wiki/Conqueror's_Blade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1nhb.jpg","s":"Master the art of medieval warcraft in this free-to-play tactical action MMO. Create a unique warlord from 10+ different classes, and wage war in epic siege battles, and sandbox territory wars. Employ special abilities, devastating weapons, and cunning strategies to reshape this vast open world into your new empire with your friends."},{"t":"Contra Anniversary Collection","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Konami","g":"Action, Platformer","r":"June 11","l":"https://en.wikipedia.org/wiki/Contra_Anniversary_Collection"},{"t":"Contra: Rogue Corps","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Konami","g":"Run and gun","r":"September 24"},{"t":"Control","p":["Windows","PlayStation 4","Xbox One"],"u":"505 Games","g":"TPS, Action-adventure","r":"August 27","l":"https://en.wikipedia.org/wiki/Control_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2evj.jpg","s":"Control is a third-person action-adventure game set in the Federal Bureau of Control, a secretive U.S. government agency that studies paranormal phenomena. Players control Jesse Faden, who arrives at the Bureau's headquarters, the Oldest House, to find it invaded by a hostile force called the Hiss. Gameplay combines supernatural abilities with a shape-shifting firearm, and the environment is reactive and destructible."},{"t":"Cooking Simulator","p":["Windows"],"d":"Big Cheese Studio","u":"PlayWay S.A., Forever Entertainment, Big Cheese Studio","g":"Simulation, cooking","r":"June 6, 2019","l":"https://en.wikipedia.org/wiki/Cooking_Simulator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20ud.jpg","s":"Cooking Simulator is a single-player simulation game that recreates restaurant cooking using a physics-based engine and detailed kitchen mechanics. Players prepare a wide range of recipes from many ingredients, handling ovens, stoves, pots, pans, and utensils in a fully interactive kitchen. It includes several modes, such as a career mode where players run a kitchen and build up fame by filling orders, a free-form sandbox with no time limits, and a set of tutorials that teach the mechanics. Additional content adds themed kitchens and specialties like pizza, cakes, and cookies."},{"t":"Corpse Party 2: Dead Patient – Chapter 1","p":["Windows"],"u":"Xseed Games , Marvelous USA","g":"Survival horror","r":"October 23"},{"t":"Corpse Party: Blood Drive","p":["Windows","Nintendo Switch"],"u":"Marvelous USA / Marvelous Europe","g":"Survival horror","r":"October 10"},{"t":"CounterAttack: Uprising","p":["Windows","Linux","macOS"],"d":"Relative Games","u":"Relative Software Ltd.","g":"Scrolling shooter","r":"March 11, 2019","l":"https://en.wikipedia.org/wiki/CounterAttack:_Uprising"},{"t":"Crackdown 3","p":["Windows","Xbox One"],"u":"Xbox Game Studios","g":"Action-adventure","r":"February 15","l":"https://en.wikipedia.org/wiki/Crackdown_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2388.jpg","s":"Stop crime as a super-powered Agent of justice in Crackdown 3's hyper-powered sandbox of mayhem and destruction. Explore the heights of a futuristic city, race through the streets in a transforming vehicle, and use your powerful abilities to stop a ruthless criminal empire. Developed by original creator Dave Jones, Crackdown 3 delivers cooperative mayhem and an all-new multiplayer mode where destruction is your ultimate weapon."},{"t":"Crash Team Racing Nitro-Fueled","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Activision","g":"Racing (kart)","r":"June 21","l":"https://en.wikipedia.org/wiki/Crash_Team_Racing_Nitro-Fueled","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2wvy.jpg","s":"Crash Team Racing Nitro-Fueled is a kart racing game developed by Beenox and published by Activision. It is a remaster of Crash Team Racing, which was originally developed by Naughty Dog for the PlayStation."},{"t":"Crawlco Block Knockers","p":["Windows"],"d":"CosmiKankei","u":"Shady Corner Games, Eastasiasoft","g":"Puzzle","r":"August 1, 2019","l":"https://en.wikipedia.org/wiki/Crawlco_Block_Knockers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2v6c.jpg","s":"Return to the feel of smokey ‘90s Japanese arcades as you pull, kick and match blocks to reveal hidden images of the lovely ladies behind each stage! As blocks enter the play field, knock them into marked zones while avoiding and smashing enemies, all as your workspace gets tighter. Aim carefully to boost your score, but don’t get boxed in!"},{"t":"Creature in the Well","p":["Windows","Nintendo Switch","Xbox One"],"d":"Flight School Studio","u":"Flight School Studio, MWM Interactive","g":"Action-adventure, dungeon crawler","r":"September 6, 2019","l":"https://en.wikipedia.org/wiki/Creature_in_the_Well","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4om3.jpg","s":"Creature in the Well is a top-down, pinball-inspired hack and slash dungeon crawler. As the last remaining BOT-C unit, venture deep into a desert mountain to restore power to an ancient facility, haunted by a desperate Creature. Uncover and upgrade powerful gear in order to save the city of Mirage from a deadly sandstorm."},{"t":"Cricket 19","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Big Ant Studios","g":"Sports","r":"May 31","l":"https://en.wikipedia.org/wiki/Cricket_19"},{"t":"CRSED: F.O.A.D.","p":["Windows","Linux","PlayStation 4","PlayStation 5","Xbox One","Xbox Series X/S","Nintendo Switch","Android"],"d":"Darkflow Studio","u":"Gaijin Entertainment","g":"First-person shooter, third-person shooter, battle royale","r":"December 12, 2019","l":"https://en.wikipedia.org/wiki/CRSED:_F.O.A.D.","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2lc1.jpg","s":"CRSED: F.O.A.D. – is a brutal MMO last-man-standing shooter with realistic weaponry, elements of lethal mystic forces and incredible superpowers!"},{"t":"Crying Suns","p":["Windows","macOS"],"d":"Alt Shift","u":"Humble Bundle","g":"Strategy, roguelike","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Crying_Suns","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vq8.jpg","s":"Crying Suns is a tactical rogue-lite that puts you in the role of a space fleet commander as you explore a mysteriously fallen empire. In this story rich experience inspired by Dune and Foundation, each successful run will uncover the truth about the Empire... and yourself as well."},{"t":"Crystal Crisis","p":["Nintendo Switch","PlayStation 4","Windows"],"u":"Nicalis","g":"Puzzle","r":"May 28","l":"https://en.wikipedia.org/wiki/Crystal_Crisis"},{"t":"Crystalis","p":["Nintendo Switch"],"g":"Action RPG","r":"December 12","l":"https://en.wikipedia.org/wiki/Crystalis"},{"t":"Crystar","p":["Windows","PlayStation 4"],"u":"Spike Chunsoft","g":"Action RPG","r":"August 27","l":"https://en.wikipedia.org/wiki/Crystar"},{"t":"Cube World","p":["Windows"],"u":"Picroma","g":"Action RPG","r":"September 30","l":"https://en.wikipedia.org/wiki/Cube_World"},{"t":"Cue!","p":["Mobile phone"],"g":"Visual Novel","l":"https://en.wikipedia.org/wiki/Cue!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2la2.jpg"},{"t":"Cuphead","p":["Nintendo Switch"],"u":"StudioMDHR","g":"Run and gun","r":"April 18","l":"https://en.wikipedia.org/wiki/Cuphead"},{"t":"Cyber Hunter","p":["Android","iOS","Windows"],"d":"NetEase","u":"NetEase","g":"Battle royale","r":"April 26, 2019","l":"https://en.wikipedia.org/wiki/Cyber_Hunter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co25l9.jpg","s":"Cyber Hunter is a next-generation, competitive sandbox mobile game. It's packed with a host of different elements, including survival, shooting, exploration, skills and much more, even including parkour! In short, it's a brand new gaming experience. The game tells the story of our future, after brain-computer interfacing technology has become highly advanced and human civilization has experienced another evolutionary leap, during which, great events have begun to unfold. Justice faces off against evil. The old stands against the new. And forces of conservatism clash with radicalism.\nIn this virtual world, all our heroes and heroines have acquired a “super power” through the help of quantum droids – the ability to turn quantum cube energy into any tactical support device they need. From Optical Camouflage to Quantum Barriers, from a detector that alerts you of approaching enemies, to a medical instrument that heals squad mates; anything and everything can be built, by you, and that's not all. You can choose whatever skills you think will help your strategy the most in any battle.\nWe've even created a vertical combat concept. With parkour features including climbing, gliding, and rolling, players can experience vertical battles on a variety of terrain, including mountains, swamps and deserts. In this game, the arena that hosts your battles are not just a huge, flat map, but a world where you can fly in the sky and move underground. We have also created a number of exploration points scattered throughout the world. Here, you can explore temples in the desert with a chance of finding E-Cores to unlock new skills and weapons. Amid mounds of destroyed robots, you can also find gloves that greatly increase your climbing speed."},{"t":"Cyber Troopers Virtual-On Masterpiece 1995~2001","p":["PlayStation 4"],"u":"Sega","g":"Action","r":"November 27","l":"https://en.wikipedia.org/wiki/Virtual_On"},{"t":"Cytus Alpha","p":["Nintendo Switch"],"g":"Music, Arcade","l":"https://en.wikipedia.org/wiki/Cytus_Alpha","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n4i.jpg","s":"The rhythm game is a “perfect version” of the popular smartphone title Cytus, now with new visuals and over 200 songs, including new songs and collaborations. A new mode where players can compete for scores against other players online has also been added."},{"t":"Daemon X Machina","p":["Nintendo Switch"],"u":"Nintendo","g":"Action, TPS","r":"September 13","l":"https://en.wikipedia.org/wiki/Daemon_X_Machina","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4ejh.jpg","s":"Daemon X Machina is a third-person action-shooter game in which players; represented by their avatars called Outers, pilot highly customizable mechs known as Arsenals on missions to suppress various mechanized foes. Choose and equip your Arsenal with a multitude of weapons, obtain more from downed enemy Arsenals, and swap them on the fly to suit your strategy in the face of ever-changing threats."},{"t":"Dance Dance Revolution A20","p":["Arcade"],"d":"Konami, Bemani","u":"Konami","g":"Music, exercise","r":"March 20, 2019","l":"https://en.wikipedia.org/wiki/Dance_Dance_Revolution_A20","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2puh.jpg","s":"Dance Dance Revolution A20 (pronounced Ace Two Oh) is a music video game, the 16th installment of the Dance Dance Revolution series, and the sequel to Dance Dance Revolution A. The game was released on new, golden cabinets on March 20, 2019 in Japan. A software upgrade for older cabinets for Japan and Asia was released on July 24, 2019, with Korea receiving a localized release on August 1, 2019, and North America on September 24, 2019. A location test in Europe began on October 7, 2019, and ended on March 16, 2020. Dance Dance Revolution A20 Plus is an update that adds 14 new songs, available on July 1, 2020 for Japanese 20th Anniversary cabinets."},{"t":"Dance of Death: Du Lac & Fey","p":["Windows"],"d":"Salix Games","g":"Adventure game","r":"April 5, 2019","l":"https://en.wikipedia.org/wiki/Dance_of_Death:_Du_Lac_&_Fey"},{"t":"Dangerous Driving","p":["Windows","PlayStation 4","Xbox One"],"u":"Maximum Games","g":"Racing","r":"April 9","l":"https://en.wikipedia.org/wiki/Dangerous_Driving_(video_game)"},{"t":"Darius Cozmic Collection","p":["Nintendo Switch"],"d":"M2","u":"Taito, ININ Games","g":"Scrolling shooter","r":"February 28, 2019","l":"https://en.wikipedia.org/wiki/Darius_Cozmic_Collection"},{"t":"Dark Devotion","p":["Windows","PlayStation 4","Nintendo Switch"],"d":"Hibernian Workshop","u":"The Arcade Crew","g":"Action role-playing","r":"April 25, 2019","l":"https://en.wikipedia.org/wiki/Dark_Devotion","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2t7g.jpg","s":"Trapped in a dark and gloomy temple, find your inner strength and courage to face its dangers. Show your Devotion!\n\nDark Devotion invites you in a rich and peculiar universe. You will go through more and more confrontations. If you happen to succeed once, good job. But don’t even think that the next step will be as effortless as the previous one.\n\nTake part into rageous and bloody fights in which your opponents won't do you any favours. Be prepared to face foes that you won't forget. And remember, enemies as well as the Temple itself will want to strike you down : each and every fight is a duel to the death in which the slightest error may cost you your life."},{"t":"Darksiders Genesis","p":["Windows","Stadia"],"u":"THQ Nordic","g":"Hack and slash, RPG","r":"December 5","l":"https://en.wikipedia.org/wiki/Darksiders_Genesis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n1f.jpg","s":"In this Action RPG spin-off, the fourth Horseman of the Apocalypse Strife is called upon to save humankind from certain destruction at the hands of Lucifer. True to its roots, Darksiders Genesis will feature intense combat, exploration, puzzle-solving, epic boss battles and serpent holes from heaven to hell. The game marks the first, full-scale Darksiders adventure played from the top-down perspective."},{"t":"Darksiders II: Deathinitive Edition","p":["Nintendo Switch"],"u":"THQ Nordic","g":"Action RPG, Hack and slash","r":"September 26","l":"https://en.wikipedia.org/wiki/Darksiders_II"},{"t":"Darksiders: Warmastered Edition","p":["Nintendo Switch"],"u":"THQ Nordic","g":"Hack and slash, Action-adventure","r":"April 2","l":"https://en.wikipedia.org/wiki/Darksiders_(video_game)"},{"t":"Darkwood","p":["PlayStation 4","Nintendo Switch","Xbox One"],"u":"Acid Wizard Studio","g":"Survival horror, Action-adventure","r":"May 14","l":"https://en.wikipedia.org/wiki/Darkwood"},{"t":"Darq","p":["Windows"],"d":"Unfold Games","u":"Feardemic","g":"Puzzle, stealth","r":"August 15, 2019","l":"https://en.wikipedia.org/wiki/Darq","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rq9.jpg","s":"Darq tells the story of Lloyd, a boy who becomes aware of the fact that he is dreaming. To Lloyd's misfortune, the dream quickly turns into a nightmare and all attempts to wake up end in failure. While exploring the darkest corners of his subconscious, Lloyd learns how to survive the nightmare by bending the laws of physics and manipulating the fluid fabric of the dream world."},{"t":"Dauntless","p":["Windows","PlayStation 4","Xbox One"],"u":"Epic Games","g":"Action RPG","r":"May 21","l":"https://en.wikipedia.org/wiki/Dauntless_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co93as.jpg","s":"Dauntless takes place in a fantasy setting, where a cataclysmic event has torn the world apart, releasing monster-like Behemoths that prey on the surviving humans. As a Slayer of Ramsgate, you are all that stands between your world and the Behemoths that seek to devour it. Hunt huge monsters, alongside other Slayers on any platform, and craft awesome gear in this stylish free-to-play co-op action RPG."},{"t":"Dawn of Man","p":["Windows","macOS","PlayStation 4","Xbox One"],"d":"Madruga Works","u":"Madruga Works","g":"City-building, survival","r":"March 1, 2019","l":"https://en.wikipedia.org/wiki/Dawn_of_Man","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qv9.jpg","s":"Command a settlement of ancient humans, guide them through the ages in their struggle for survival. Hunt, gather, craft tools, fight, research new techs and face the challenges the environment will throw at you."},{"t":"Dawn of Survivors","p":["Nintendo Switch"],"g":"Role-playing (RPG), Simulator, Adventure","l":"https://en.wikipedia.org/wiki/Dawn_of_Survivors","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co57dv.jpg","s":"Take on players from around the world in this zombie survivor game. From decaying cities to dark forests, you will fight through hordes of zombies and desperate scavengers. Find food. Build shelter. Team up. Prepare yourself. For when the sun rises, so do the dead."},{"t":"Daymare: 1998","p":["Windows"],"d":"Invader Studios","u":"Destructive Creations, All in! Games","g":"Survival horror","r":"September 17, 2019","l":"https://en.wikipedia.org/wiki/Daymare:_1998","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24fl.jpg","s":"Daymare: 1998 is a third-person survival horror game that recreates the mood of iconic titles from the '90s, with a fresh storyline. An incident that turns a small town into a deadly zone, three characters to play with and little time to find the truth, before its mutated citizens abruptly end your mission."},{"t":"Days Gone","p":["PlayStation 4"],"u":"Sony Interactive Entertainment","g":"Action-adventure, Survival horror","r":"April 26","l":"https://en.wikipedia.org/wiki/Days_Gone","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co94bn.jpg","s":"Days Gone is an open-world action-adventure game developed by Bend Studio and published by Sony Interactive Entertainment. Released in April 2019 for PlayStation 4 and later for PC in May 2021, the game is set in a post-apocalyptic world where players control Deacon St. John, a drifter and bounty hunter navigating a landscape overrun by \"Freakers,\" zombie-like creatures created by a global pandemic.\n\nThe gameplay focuses on exploration, combat, and survival elements, with players able to use various weapons, craft supplies, and upgrade Deacon’s motorcycle, essential for travelling across the vast and hostile environment. Days Gone combines narrative-driven missions with an open world filled with dynamic events, enemy camps, and environmental challenges."},{"t":"Dead or Alive 6","p":["Windows","PlayStation 4","Xbox One"],"u":"Koei Tecmo","g":"Fighting","r":"March 1","l":"https://en.wikipedia.org/wiki/Dead_or_Alive_6","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1nzf.jpg","s":"Dead or Alive 6,produced by Koei Tecmo Games,features fast-paced 3D fighting entertainment with multi-tiered stages that are now both dynamic and critical parts of the competitive experience."},{"t":"Deadly Premonition: Origins","p":["Nintendo Switch"],"u":"Rising Star Games","g":"Survival horror","r":"September 4","l":"https://en.wikipedia.org/wiki/Deadly_Premonition"},{"t":"Dear Reader","p":["iOS","macOS","tvOS"],"d":"Local No. 12","u":"Local No. 12","g":"Word puzzle","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Dear_Reader_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rws.jpg","s":"Dear Reader lets you curl up and play your favorite books, turning classic literature into fun word puzzles. Unscramble passages from famous books, unlock unique puzzles, and add new books to your library—from Pride and Prejudice to the Wizard of Oz.\n\nDear Reader includes fifty literary classics and dozens of different word puzzles, from unscrambling anagrams to swapping lines of text. As far as we know, this is the first game where you can dive in and play with the actual written words from so many tempting books.\n\nAnd it’s fun! As Michelle Ehrhardt of Kill Screen wrote, “As novel as the game is, it plays with the same confidence as a 100-year old classic.”"},{"t":"Death end re;Quest","p":["PlayStation 4"],"u":"Idea Factory","g":"RPG","r":"February 19","l":"https://en.wikipedia.org/wiki/Death_end_re;Quest"},{"t":"Death Horizon: Reloaded","p":["Meta Quest","Oculus Rift","SteamVR","PlayStation VR"],"d":"Dream Dev Studio VR","g":"First-person shooter","r":"September 26, 2019","l":"https://en.wikipedia.org/wiki/Death_Horizon:_Reloaded"},{"t":"Death Stranding","p":["PlayStation 4"],"u":"Sony Interactive Entertainment","g":"Action","r":"November 8","l":"https://en.wikipedia.org/wiki/Death_Stranding","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsvh.jpg","s":"Death Stranding is an action game set in a post-apocalyptic United States.\n\nPlayers control Sam Porter Bridges, a courier tasked with reconnecting isolated cities via a communication network while delivering essential cargo. The gameplay blends traversal, resource management, and narrative elements, with a focus on social connectivity through asynchronous multiplayer. It is known for its unique mechanics, atmospheric world, and philosophical themes."},{"t":"Degrees of Separation","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Moondrop","u":"Modus Games","g":"Puzzle video game, Platform video game","r":"February 14, 2019","l":"https://en.wikipedia.org/wiki/Degrees_of_Separation","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsok.jpg","s":"Degrees of Separation is a puzzle platformer where cooperation is built into every move. Two contrasting souls, Ember and Rime, fall in love, but are separated by an enigmatic force, and must use their powers to progress through a spectacular world of fantasy and adventure. Players solve environmental obstacles by drawing upon the contrasting temperatures of warm and cold in single-player and cooperative multiplayer."},{"t":"Deltarune: Chapter 1","p":["Nintendo Switch","PlayStation 4"],"u":"Toby Fox","g":"RPG, Adventure","r":"February 28","l":"https://en.wikipedia.org/wiki/Deltarune#Chapter_1_–_The_Beginning"},{"t":"Demon's Crest","p":["Nintendo Switch"],"g":"Platformer","r":"September 5","l":"https://en.wikipedia.org/wiki/Demon%27s_Crest"},{"t":"Demon's Tilt","p":["macOS","Windows","Xbox One","Nintendo Switch"],"d":"Adam Ferrando","u":"Flarb","g":"Pinball","r":"December 13, 2019","l":"https://en.wikipedia.org/wiki/Demon's_Tilt","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob7s4.jpg","s":"Turbo charged pinball returns! Now with bigger sprites, more baddies, more secrets & more bullets! Demon's Tilt pushes the limits of the Video Pinball genre with Shump & Hack N' Slash elements."},{"t":"Desolate","p":["Windows"],"d":"Nearga","u":"HypeTrain Digital","g":"Survival, action-adventure","r":"January 17, 2019","l":"https://en.wikipedia.org/wiki/Desolate_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1j11.jpg","s":"DESOLATE is a first person survival horror. Form a research team with up to 4 other players and explore an open world filled with mysteries and unsolved questions or do it all by yourself."},{"t":"Destiny 2","p":["Stadia"],"u":"Bungie","g":"FPS","r":"November 19","l":"https://en.wikipedia.org/wiki/Destiny_2"},{"t":"Destiny 2: Shadowkeep","p":["Windows","PlayStation 4","Xbox One"],"u":"Bungie","g":"Action RPG, FPS","r":"October 1"},{"t":"Detective Di: The Silk Rose Murders","p":["Windows","Linux"],"u":"Nupixo Games","g":"PCA","r":"May 1"},{"t":"Detroit: Become Human","p":["Windows"],"u":"Quantic Dream","g":"Adventure","r":"December 12"},{"t":"Devil May Cry","p":["Nintendo Switch"],"u":"Capcom","g":"Action-adventure, Hack and slash","r":"June 25","l":"https://en.wikipedia.org/wiki/Devil_May_Cry_(video_game)"},{"t":"Devil May Cry 2","p":["Nintendo Switch"],"u":"Capcom","g":"Action-adventure, Hack and slash","r":"September 19","l":"https://en.wikipedia.org/wiki/Devil_May_Cry_2"},{"t":"Devil May Cry 5","p":["Windows","PlayStation 4","Xbox One"],"u":"Capcom","g":"Action-adventure, Hack and slash","r":"March 8","l":"https://en.wikipedia.org/wiki/Devil_May_Cry_5","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rb4.jpg","s":"Devil May Cry 5 is a brand-new entry in the legendary over-the-top action series Devil May Cry. The game features three playable characters, each with a radically different stylish combat play style as they take on the city overrun with demons. Developed with Capcom’s in-house proprietary RE engine, the series continues to achieve new heights in fidelity with graphics that utilize photorealistic character designs and stunning lighting and environmental effects."},{"t":"Devolver Bootleg","p":["Windows"],"d":"Doinksoft","u":"Devolver Digital","g":"Various","r":"June 10, 2019","l":"https://en.wikipedia.org/wiki/Devolver_Bootleg","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4a5b.jpg","s":"Devolver Bootleg contains eight original rip-offs of Devolver Digital games including:\n\nEnter The Gun Dungeon\nImagine a dungeon crawler but instead of swords it’s guns. But also everything is made out of guns and bullets and stuff. Like, everything.\n\nHotline Milwaukee\nBrutal, fast-paced, stealth action and a whole lot of blood. From your garbage person apartment in historically interesting and relevant Milwaukee, pick up the phone, and answer the call--of murder. Follow instructions and follow the stairs deeper and deeper into the mysterious basement. Where does it go? Who are you?\n\nApe Out Jr.\nEscape out of ape prison in this classic arcade-style platformer where you play as an orange gorilla who will kill everyone so he can to see his dad again. Grab unsuspecting guards to use as weapons and shields in this completely original idea set to an interpretive chiptune jazz drummer soundtrack. Please, Ape Out was my father’s name.\n\nShootyboots\nIt’s the never-ending story of a young boy falling down a well, wearing a giant boot as if it was overalls, which also is a gun. Collect gems, squash and shoot the fauna, fall deeper into the infinite well, and wear some other equally large and ballistically designed shoes.\n\nSuper Absolver Mini: Turbo Fighting Championship\n(2 Players Only)\nA competitive fighting game where you play as your choice of one of four masked combat disciples. You choose two special moves. You fight two rounds. The winner is absolved of the obligation to ever have to fight again, but probably will anyway because the one true resolve of the flesh is a fist colliding with it.\n\nCatsylvania\nIt’s a cat inside of a suit of armor. It’s a cat...In full plate armor. What else do you want?\n\nPikuBiku Ball Stars\n(2 Players Only)\nEverybody’s favorite red thing with legs is back and ready to sink some baskets with a friend. Nothing but net baby. Slam freakin’ dunk.\n\nLuftrousers\nHello, I am Rami Ismail, ½ of Dutch independent game development studio, Vlambeer. We made a version of Luftrausers that had a typo, and JW left the thumbdrive containing the source at a coffee shop somewhere while I was doing a talk in Berlin, then Nairobi, then in Los Angeles the following day. If you find the thumbdrive, can you please return it and please PLEASE do not share the contents with anyone or add it to a compilation of pirated, under-the-table ripoffs of games that Devolver has published."},{"t":"Devotion","p":["Windows","macOS"],"d":"Red Candle Games","u":"Red Candle Games","g":"Survival horror, puzzle","r":"February 19, 2019","l":"https://en.wikipedia.org/wiki/Devotion_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2muf.jpg","s":"‘Devotion’ is a first-person atmospheric horror game set in the 1980s Taiwan.\n\nThe story centers around a seemingly ordinary family of three that lived in an old apartment complex. Explore the nostalgic house in the 80s where religion plays a significant role in their daily life. When one day the same house that once filled with joy and love had turned into a hell-like nightmare, and by venturing in the haunted and confined space, each puzzle leads you closer to the mysteries nested deep inside."},{"t":"Diabolik Lovers: Chaos Lineage","p":[],"l":"https://en.wikipedia.org/wiki/Diabolik_Lovers:_Chaos_Lineage"},{"t":"Dicey Dungeons","p":["Linux","macOS","Windows","Xbox Series X/S"],"d":"Terry Cavanagh","u":"Terry Cavanagh","g":"Roguelike deck-building","r":"August 13, 2019","l":"https://en.wikipedia.org/wiki/Dicey_Dungeons","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2h3y.jpg","s":"Fighting against fortune would be a lot easier if you weren't a walking dice."},{"t":"Dies irae: Interview with Kaziklu Bey","p":["Windows"],"u":"Light","g":"Visual novel","r":"February 28"},{"t":"Digimon Story Cyber Sleuth: Complete Edition","p":["Windows","Nintendo Switch"],"u":"Bandai Namco Entertainment","g":"RPG","r":"October 18"},{"t":"Dirt Rally 2.0","p":["Windows","PlayStation 4","Xbox One"],"u":"Codemasters","g":"Racing","r":"February 26","l":"https://en.wikipedia.org/wiki/Dirt_Rally_2.0","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1sro.jpg","s":"Dirt Rally 2.0 dares you to carve your way through a selection of iconic rally locations from across the globe, in the most powerful off-road vehicles ever made, knowing that the smallest mistake could end your stage."},{"t":"Disco Elysium","p":["Windows"],"d":"ZA/UM","u":"ZA/UM","g":"RPG","r":"October 15, 2019","l":"https://en.wikipedia.org/wiki/Disco_Elysium","i":"images/steam-632470.jpg","s":"Disco Elysium - The Final Cut is a groundbreaking role playing game. You’re a detective with a unique skill system at your disposal and a whole city to carve your path across. Interrogate unforgettable characters, crack murders or take bribes. Become a hero or an absolute disaster of a human being."},{"t":"Disgaea 4 Complete+","p":["Nintendo Switch","PlayStation 4"],"u":"NIS America","g":"Tactical RPG","r":"October 29","l":"https://en.wikipedia.org/wiki/Disgaea_4"},{"t":"Disgaea RPG","p":["iOS","Android","Windows"],"d":"Drecom, ForwardWorks","u":"Nippon Ichi Software","g":"Role-playing game","r":"March 19, 2019","l":"https://en.wikipedia.org/wiki/Disgaea_RPG","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vy0.jpg","s":"A departure from the grid-based tactics gameplay of the main series, the game uses teams of 5 characters, from throughout the series, to fight waves of enemies in turn-based battles.\nCharacters can have star ratings from 2 to 6, that have various level caps with the end goal of a 6 star character being upgraded to level 9999.\nThe game is region locked in Japan.\n\nOriginally released in March 2019 with bugs and server issues, the game was taken offline to work on fixes and improve the game. it was re-launched in November 2019."},{"t":"Disney Tsum Tsum Festival","p":["Nintendo Switch"],"u":"Bandai Namco Entertainment","g":"Puzzle","r":"November 8","l":"https://en.wikipedia.org/wiki/Disney_Tsum_Tsum_Festival"},{"t":"Divinity: Original Sin II","p":["Nintendo Switch"],"u":"Bandai Namco Entertainment","g":"RPG","r":"September 4"},{"t":"Divinity: Original Sin II – Definitive Edition","p":["Nintendo Switch"],"d":"Larian Studios","u":"Larian Studios","r":"September 4, 2019"},{"t":"Doggie Ninja: The Golden Mission","p":["Nintendo Switch"],"l":"https://en.wikipedia.org/wiki/Doggie_Ninja:_The_Golden_Mission","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co57ep.jpg","s":"\"Doggie Ninja The Golden Mission\" is a PvP action game up to 4 players can play. Let's enjoy this game with anyone, anytime, and anywhere! - Break the castle!! Crush the rivals! Let's throw the wall blocks to break the castle! But watch out! If you break all the blocks holding the roof, the roof will fall down! Once the falling roof hits a Doggie Ninja, He/she will be blown away!"},{"t":"Don't Escape: 4 Days to Survive","p":["Windows","macOS"],"d":"Mateusz Sokalszczuk","u":"Armor Games","g":"Adventure, survival","r":"March 11, 2019","l":"https://en.wikipedia.org/wiki/Don't_Escape:_4_Days_to_Survive","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1l1t.jpg","s":"After scraping out a bleak existence in the post-apocalyptic wastelands, you thought you were prepared for anything. But now there’s no way to run. The choices you make determine how everything plays out in this classic point-and-click adventure."},{"t":"Donkey Kong 3","p":["Nintendo Switch"],"g":"Shoot 'em up","r":"July 17","l":"https://en.wikipedia.org/wiki/Donkey_Kong_3"},{"t":"Donkey Kong Jr.","p":["Nintendo Switch"],"g":"Platformer","r":"May 15","l":"https://en.wikipedia.org/wiki/Donkey_Kong_Jr."},{"t":"Doom","p":["iOS","Android","PlayStation 4","Nintendo Switch","Xbox One"],"d":"id Software, Nerve Software","u":"Bethesda Softworks","g":"Shooter","r":"July 26, 2019","l":"https://www.igdb.com/games/doom--4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3m5h.jpg","s":"Doom is a sci-fi first-person shooter game developed by id Software and Nerve Software and published by Bethesda Softworks. It is an updated version of the original 1993 Doom that uses the Unity engine as a shell for the id Tech 1 engine.\n\nThis game, as well as Doom II Classic, was initially released in a suite of classic Doom ports for PlayStation 4, Xbox One, Nintendo Switch, iOS, and Android, however, the ports were initially heavily criticized due to its poor quality and inaccuracies compared to the previous console generation ports while implementing an always-online DRM that required the player to sign into a Bethesda.net account (meant to unlock Slayers Club rewards) to play the game, despite these ports not having any online multiplayer features.\n\nAfter the initial criticism of the ports, Nerve Software eventually rectified the issues of the log-in requirements and problems with the ports through patches. A PC version of Doom Classic was released through Bethesda.net on January 9, 2020, which was later re-released through Steam on September 3, 2020 as a free update to existing owners of The Ultimate Doom."},{"t":"Doraemon Story of Seasons","p":["Nintendo Switch","Windows"],"u":"Bandai Namco Entertainment","g":"Farming , RPG","r":"June 13","l":"https://en.wikipedia.org/wiki/Doraemon_Story_of_Seasons"},{"t":"Doraemon: Nobita's Chronicle of the Moon Exploration","p":[],"l":"https://en.wikipedia.org/wiki/Doraemon:_Nobita's_Chronicle_of_the_Moon_Exploration_(video_game)"},{"t":"Dota Auto Chess","p":["Linux","macOS","Windows"],"d":"Drodo Studio","g":"Auto battler","r":"January 4, 2019","l":"https://en.wikipedia.org/wiki/Dota_Auto_Chess","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m1d.jpg","s":"Auto Chess is the original auto battler game that had a significant worldwide influence with its brand new gameplay mode and strategic competitive features. It has also attracted tens of millions of players around the globe. Each player can play against others through the internet and enjoy a brand new strategy competitive experience."},{"t":"Double Cross","p":["Windows","Nintendo Switch","Xbox One"],"d":"13AM Games","u":"Graffiti Games","g":"Action, platform","r":"January 10, 2019","l":"https://en.wikipedia.org/wiki/Double_Cross_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co77du.jpg","s":"\"Double Cross is an adventure-game style investigation crossed with an intense action platformer. Players are also free to customize Zahra’s play style in order to become the top RIFT agent.\""},{"t":"Double Dragon II: The Revenge","p":["Nintendo Switch"],"g":"Brawler","r":"June 12"},{"t":"Downtown Nekketsu March: Super-Awesome Field Day!","p":["Nintendo Switch"],"g":"Action, Sports","r":"August 21"},{"t":"Dr Kawashima's Brain Training for Nintendo Switch","p":["Nintendo Switch"],"d":"Nintendo EPD, indieszero","u":"Nintendo","g":"Edutainment, Puzzle","r":"December 27, 2019","l":"https://en.wikipedia.org/wiki/Dr_Kawashima's_Brain_Training_for_Nintendo_Switch","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob6ee.jpg","s":"Get ready to challenge your brain in a variety of ways in Dr Kawashima’s Brain Training for Nintendo Switch! Enjoy new exercises, some of them making use of the right Joy-Con’s IR Motion Camera, or tap and train with classic exercises from past Brain Training games that you can play using a stylus (included with the packaged version from retail stores) or your finger. It’s in your hands!"},{"t":"Dr. Doe's Chemistry Quiz","p":["Browser"],"d":"alfa995","u":"alfa995","g":"Quiz/Trivia","r":"January 17, 2019","l":"https://www.igdb.com/games/dr-does-chemistry-quiz","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4vub.jpg","s":"The adorable science deer Dr. Doe is here to test your knowledge of chemistry! Answer correctly, she strips. Answer all perfectly and.. well you can imagine what your reward will be!"},{"t":"Dr. Mario World","p":["iOS","Android"],"u":"Nintendo","g":"Puzzle","r":"July 9","l":"https://en.wikipedia.org/wiki/Dr._Mario_World"},{"t":"Dragon Marked For Death","p":["Nintendo Switch"],"u":"Inti Creates","g":"RPG","r":"January 31","l":"https://en.wikipedia.org/wiki/Inti_Creates"},{"t":"Dragon Quest","p":["Nintendo Switch"],"u":"Square Enix","g":"RPG","r":"September 27","l":"https://en.wikipedia.org/wiki/Dragon_Quest_(video_game)"},{"t":"Dragon Quest Builders 2","p":["Nintendo Switch","PlayStation 4","Windows"],"u":"Square Enix","g":"Action RPG, Sandbox","r":"July 12","l":"https://en.wikipedia.org/wiki/Dragon_Quest_Builders_2"},{"t":"Dragon Quest II","p":["Nintendo Switch"],"u":"Square Enix","g":"RPG","r":"September 27","l":"https://en.wikipedia.org/wiki/Dragon_Quest_II"},{"t":"Dragon Quest III","p":["Nintendo Switch"],"u":"Square Enix","g":"RPG","r":"September 27","l":"https://en.wikipedia.org/wiki/Dragon_Quest_III"},{"t":"Dragon Quest Walk","p":["Android","iOS"],"d":"COLOPL","u":"Square Enix","g":"Geolocation-based game, role-playing game","r":"September 12, 2019","l":"https://en.wikipedia.org/wiki/Dragon_Quest_Walk","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vsk.jpg","s":"Let's go on an adventure with your smartphone!\nEquipped with a life log function \"Aru-kun de W\"! Going out is even more fun!\n\nLife log management with adventure!\n\nIf you walk in the real world and move, the characters will move in tandem.\nEveryday movement is an adventure!\n\nThe life log function \"Aru-kun de W\" can record the results and check the report.\nLet's use it for health management.\n\nIn addition, slime will grow with some results!\nWhat kind of slime you grow up in depends on you!"},{"t":"Dragon Quest XI S","p":["Nintendo Switch"],"u":"Nintendo","g":"RPG","r":"September 27","l":"https://en.wikipedia.org/wiki/Dragon_Quest_XI_S"},{"t":"Dragon Quest XI S: Echoes of an Elusive Age – Definitive Edition","p":["Nintendo Switch"],"d":"Square Enix","u":"Square Enix","g":"Role-playing (RPG), Turn-based strategy (TBS), Adventure","r":"September 27, 2019","l":"https://en.wikipedia.org/wiki/Dragon_Quest_XI","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1x9f.jpg","s":"The Definitive Edition includes all the content from the original release of the acclaimed DRAGON QUEST XI, and adds extra character-specific scenarios, the choice of playing with the original soundtrack or a grand orchestral version of the music, the ability to switch between 2D and 3D graphic modes, a Japanese voice-acting option, and much more."},{"t":"Dragon Snakes","p":["Nintendo Switch"],"g":"Arcade","l":"https://en.wikipedia.org/wiki/Dragon_Snakes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co57ew.jpg","s":"Classic and addictive gameplay reimagined with colorful dragons. Try to beat your high score or play against up to 4 friends on a single screen. Eat as many butterflies as you can and watch your dragon grow!"},{"t":"Dragon's Dogma: Dark Arisen","p":["Nintendo Switch"],"u":"Capcom","g":"Action RPG, Hack and slash","r":"April 23"},{"t":"Draugen","p":["Windows"],"d":"Red Thread Games","u":"Red Thread Games","g":"Adventure","r":"May 29, 2019","l":"https://en.wikipedia.org/wiki/Draugen_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7soc.jpg","s":"Draugen is a first-person psychological horror adventure, set amongst the deep fjords and towering mountains of Norway’s awe-inspiring west coast.\n\nThe game is a dark and disturbing journey into the pitch black heart of Norwegian national romanticism, as seen through the eyes of an American nature photographer, botanist and entomologist."},{"t":"DreamWorks Dragons Dawn of New Riders","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Outright Games","g":"Action-adventure","r":"February 15"},{"t":"Driftland: The Magic Revival","p":["Windows"],"u":"Star Drifters","g":"RTS","r":"April 18"},{"t":"Druidstone","p":["Windows"],"d":"Ctrl Alt Ninja","u":"Ctrl Alt Ninja","g":"Tactical role-playing","r":"May 15, 2019","l":"https://en.wikipedia.org/wiki/Druidstone"},{"t":"Dry Drowning","p":["Windows"],"u":"VLG Publishing","g":"Visual novel","r":"August 2","l":"https://en.wikipedia.org/wiki/Dry_Drowning"},{"t":"Dual Brain Vol. 1: Calculation","p":[],"l":"https://en.wikipedia.org/wiki/Dual_Brain_Vol._1:_Calculation"},{"t":"Dungeon Dinner: Fushigina Meikyuu no Bukimina Ryouri","p":[],"l":"https://en.wikipedia.org/wiki/Dungeon_Dinner:_Fushigina_Meikyuu_no_Bukimina_Ryouri"},{"t":"Dungeon Shooting","p":[],"l":"https://en.wikipedia.org/wiki/Dungeon_Shooting"},{"t":"Dusk Diver","p":["Nintendo Switch","PlayStation 4"],"u":"PQube","g":"Action RPG","r":"October 24","l":"https://en.wikipedia.org/wiki/Dusk_Diver"},{"t":"Dustnet","p":["Windows","macOS","Android","iOS"],"d":"SCRNPRNT","u":"SCRNPRNT","g":"Action","r":"July 16, 2019","l":"https://en.wikipedia.org/wiki/Dustnet","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2q0s.jpg","s":"Dustnet is the last remaining de_dust2 server, join an asymmetrical cross-platform deathmatch as a computer, virtual reality, or augmented reality player."},{"t":"Earth Defense Force 5","p":["Windows"],"u":"D3 Publisher","g":"TPS","r":"July 11","l":"https://en.wikipedia.org/wiki/Earth_Defense_Force_5"},{"t":"Earth Defense Force: Iron Rain","p":["PlayStation 4","Windows"],"u":"D3 Publisher","g":"Action","r":"April 11"},{"t":"East of the Rockies","p":[],"l":"https://en.wikipedia.org/wiki/East_of_the_Rockies"},{"t":"Eastshade","p":["Windows"],"u":"Eastshade Studios","g":"Adventure","r":"February 13","l":"https://en.wikipedia.org/wiki/Eastshade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4b9w.jpg","s":"Eastshade is a first-person, open world exploration game.\n\nYou are a traveling painter, exploring the island of Eastshade. Capture the world on canvas using your artist’s easel. Talk to the inhabitants to learn about their lives. Make friends and help those in need. Discover mysteries and uncover secrets about the land. Surmount natural impasses to reach forgotten places. Experience how your actions impact the world around you."},{"t":"EFootball PES 2020","p":["Windows","PlayStation 4","Xbox One","Android","iOS"],"d":"PES Productions","u":"Konami, NetEase","g":"Sports","r":"September 10, 2019","l":"https://en.wikipedia.org/wiki/EFootball_PES_2020","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m14.jpg","s":"eFootball PES 2020 is a football simulation game developed and published by Konami. Released in September 2019, it is the 19th instalment in the Pro Evolution Soccer series and the first to include the \"eFootball\" branding, reflecting Konami's focus on esports."},{"t":"eFootball Pro Evolution Soccer 2020","p":["Windows","PlayStation 4","Xbox One"],"u":"Konami","g":"Sports","r":"September 10","l":"https://en.wikipedia.org/wiki/EFootball_Pro_Evolution_Soccer_2020"},{"t":"Eliza","p":["Windows","macOS","Linux","Nintendo Switch"],"d":"Zachtronics","u":"Zachtronics","g":"Visual novel","r":"August 12, 2019","l":"https://en.wikipedia.org/wiki/Eliza_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uab.jpg","s":"Eliza is a visual novel about an AI counseling program, the people who develop it, and the people who use it. Follow Evelyn Ishino-Aubrey as she reconnects with people from her past, gets to know the people of Seattle who use Eliza for counseling, and decides the course of her future."},{"t":"Elsinore","p":["Windows","Linux","macOS"],"d":"Golden Glitch","u":"Golden Glitch","g":"Adventure","r":"July 22, 2019","l":"https://en.wikipedia.org/wiki/Elsinore_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2473.jpg","s":"Elsinore is a time-looping adventure game set in the world of Shakespeare's Hamlet. Elsinore combines strong social simulation elements, a dynamic story that reacts immediately to player decisions, and a world full of diverse characters with secrets to uncover. Can Ophelia prevent the tragedy that lies before her?"},{"t":"Erica","p":["PlayStation 4"],"d":"Flavourworks, London Studio","u":"Sony Interactive Entertainment, Flavourworks","g":"Interactive film","r":"August 19, 2019","l":"https://en.wikipedia.org/wiki/Erica_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p7n.jpg","s":"Immerse yourself in an interactive live-action thriller which puts you at the heart of the mystery.\n\nDelve into Erica’s past as you piece together the shocking truth behind her father’s death. Face the consequences of your actions as you influence how the narrative unfolds and arrive at multiple alternative endings.\n\nReach into the world by interacting with clues using your DualShock 4 wireless controller or the Erica app for iOS and Android."},{"t":"Escape from the Universe","p":["Nintendo Switch"],"g":"Shooter, Arcade","l":"https://en.wikipedia.org/wiki/Escape_from_the_Universe","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co57mq.jpg","s":"It’s year 104 of Universal Galactic Calendar; after the destruction of the Earth, human survivors are scattered all over the universe, trying to persevere in the hostile environment of the war-torn outer space."},{"t":"Escaped Chasm","p":["Windows","macOS"],"d":"Temmie Chang","g":"Adventure","r":"April 2, 2019","l":"https://en.wikipedia.org/wiki/Escaped_Chasm","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2igg.jpg","s":"A small RPG Maker game about a lonely girl with a connection to another world that she sees in her dreams."},{"t":"Etherborn","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Altered Matter","g":"Puzzle","r":"July 18"},{"t":"Etrian Odyssey Nexus","p":["Nintendo 3DS"],"u":"Atlus","g":"RPG, Dungeon crawl","r":"February 5","l":"https://en.wikipedia.org/wiki/Etrian_Odyssey_Nexus"},{"t":"EverQuest II: Blood of Luclin","p":[],"l":"https://en.wikipedia.org/wiki/EverQuest_II:_Blood_of_Luclin"},{"t":"EverQuest: Torment of Velious","p":["Windows"],"u":"Daybreak Games","g":"MMO, RPG","r":"December 18"},{"t":"Everybody, Hearts!","p":["Nintendo Switch"],"g":"Card & Board Game","l":"https://en.wikipedia.org/wiki/Everybody,_Hearts!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4jas.jpg","s":"'Everybody, Hearts!' is a Nintendo Switch exclusive card game that is now available to download. Experience playing the AI via SINGLEPLAYER mode, have a maximum of 5 players in the online MULTIPLAYER mode, or enjoy LOCAL NETWORK PLAY, accomodating up to 4 players. OPTIONS allow changes to 8 game settings, including Card Passing, Breaking Hearts, or the elusive \"Shooting The Moon\". Whether by yourself, with friends or online, you may now enjoy Hearts! to your hearts content!"},{"t":"Exception","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Traxmaster Software","u":"Traxmaster Software","g":"Platform","r":"August 13, 2019","l":"https://en.wikipedia.org/wiki/Exception_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m8z.jpg","s":"When an old woman's computer system is taken over by a fascist virus bent on total annihilation, you assume control of an ordinary software program transformed into an elite combat machine. Retake the system and build your character into a formidable instrument of retribution."},{"t":"F-Zero","p":["Nintendo Switch"],"g":"Racing","r":"September 5","l":"https://en.wikipedia.org/wiki/F-Zero_(video_game)"},{"t":"F1 2019","p":["Windows","PlayStation 4","Xbox One"],"u":"Codemasters","g":"Racing","r":"June 28","l":"https://en.wikipedia.org/wiki/F1_2019_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n7i.jpg","s":"Working in partnership with F1, for the first time ever, players will be able to get behind the wheel of a 2019 regulation car specifically designed in collaboration with F1’s technical team, headed up by Ross Brawn and Pat Symonds. The car, which will be available in Multiplayer, adheres to the 2019 regulations and comes with a range of livery designs offering players a new level of personalization. The 2019 F1 Team liveries will also feature on the car in early marketing materials, but will be replaced by the final Team cars ahead of the game's release."},{"t":"F1 Clash","p":["iOS","Android"],"d":"Hutch","u":"Hutch","g":"Motor racing management","r":"May 7, 2019","l":"https://en.wikipedia.org/wiki/F1_Clash","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3byh.jpg","s":"F1 Clash is a racing management/strategy video game developed and published by Hutch. The game was initially released with the name F1 Manager for both iOS and Android on May 7, 2019. In May 2021 the game was rebranded to F1 Clash and it currently features all the official circuits, teams and drivers from the 2021 Formula One World Championship."},{"t":"Fade to Silence","p":["Windows","PlayStation 4","Xbox One"],"d":"Black Forest Games","u":"THQ Nordic","g":"Action-adventure, survival","r":"April 30, 2019","l":"https://en.wikipedia.org/wiki/Fade_to_Silence","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27q9.jpg","s":"As the player you take the role of Ash, a natural but tormented leader. In that role you explore a post-apocalyptic, frozen wasteland to gather the resources necessary to establish a refuge for survival. With dwindling resources, simple tasks like upgrading equipment and collecting materials quickly require an expedition to scavenge the necessary items. In the search for survival materials, players must navigate a vast territory, in which they will encounter Eldritch monsters and an even greater foe: the unrelenting winter. While freezing temperatures constantly take their toll on the player Ash, the deadliest event is that of a blizzard. If caught by surprise, it takes every ounce of skill, determination and luck to survive.\n\nIn order to survive and overcome all challenges, the player needs to attract followers, bringing them into thei refuge. Each individual skillset and character traits grants access to higher tier resources and gear. Without such advances, the player character can scavenge only the barest necessities, crafting makeshift tools and weapons.\n\n“You’re glad to have found wood; for once, you’ll have a roaring fire in the camp. As your sled wolves race home, you pay no attention to the strange lights in the forest. You’ve done enough for today.\nThe wind suddenly picks up - a blizzard is moving in fast. The voice in your head dares you to keep going,”Come on! You have plenty of time to make it back.” You doubt it, but stopping now means you need to build a shelter—out of that precious wood. The snow begins to fall; you have only a moment to decide. Should you risk it and keep going, or do you play it safe but lose your firewood?”\n\nFade to Silence introduces the many dynamics of a harsh winter climate to a complex, character-driven, group survival experience. The dynamic weather system adds to the immersion of survival in a cold, corrupted world. Survival depends on how well the players read weather patterns, and if they come to the right conclusion - look for shelter or press home. The dynamic snow displacement leaves a realistic path by both player character and NPC. This telltale sign will tell you regions where it is good to hunt and regions where monsters are roaming."},{"t":"Falcon Age","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Outerloop Games","g":"Adventure","r":"April 9","l":"https://en.wikipedia.org/wiki/Falcon_Age"},{"t":"Famicom Wars","p":["Nintendo Switch"],"g":"Strategy, TBT","r":"December 12","l":"https://en.wikipedia.org/wiki/Famicom_Wars"},{"t":"Fantasy Strike","p":["Linux","macOS","Windows","Nintendo Switch","PlayStation 4"],"d":"Sirlin Games","u":"Sirlin Games","g":"Fighting","r":"July 25, 2019","l":"https://en.wikipedia.org/wiki/Fantasy_Strike"},{"t":"Far Cry New Dawn","p":["Windows","PlayStation 4","Xbox One"],"u":"Ubisoft","g":"FPS","r":"February 15","l":"https://en.wikipedia.org/wiki/Far_Cry_New_Dawn","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vpg.jpg","s":"Dive into a transformed vibrant post-apocalyptic Hope County, Montana, 17 years after a global nuclear catastrophe. Lead the fight against the Highwaymen, as they seek to take over the last remaining resources."},{"t":"FAR: Lone Sails","p":["PlayStation 4","Xbox One","Nintendo Switch"],"u":"Mixtvision","g":"Adventure","r":"April 2"},{"t":"Farming Simulator 19","p":["Stadia"],"u":"Focus Home Interactive","g":"Simulation","r":"November 19","l":"https://en.wikipedia.org/wiki/Farming_Simulator#Farming_Simulator_19"},{"t":"Fate/Extella Link","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Xseed Games","g":"Action-adventure","r":"March 19","l":"https://en.wikipedia.org/wiki/Fate/Extella_Link"},{"t":"Fault Milestone One","p":["Nintendo Switch"],"u":"Sekai Project","g":"Visual novel","r":"October 3","l":"https://en.wikipedia.org/wiki/Fault_Milestone_One"},{"t":"Felix the Reaper","p":["macOS","Nintendo Switch","PlayStation 4","Windows","Xbox One"],"d":"Kong Orange","u":"Daedalic Entertainment","g":"Puzzle","r":"October 17, 2019","l":"https://en.wikipedia.org/wiki/Felix_the_Reaper","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wlt.jpg","s":"Felix The Reaper - A romantic comedy game about the life of death.\n\nFelix The Reaper is a romantic comedy about the life of Death. It's brought to you on PC as a 3D shadow manipulation puzzle adventure game of dance, dying people and dangerous love.\n\nFelix has set out to conquer the heart of Betty The Maiden. He's fallen in love watching her from the train window commuting to work everyday for ages. He works at The Ministry of Death, she works at The Ministry of Life. Hence they don't meet.\n\nHe's taught himself to dance, because he's convinced, that will win Betty over. And he's gotten really good at it too.\n\nFinally Felix has come to realise, that it's not enough, that he can dance, if they never meet. And one day he decides to become a Field Reaper and go to work in the human world. That's where life and death collides. Hence he might finally get to ask Betty out for a dance.\n\nExcel at making sure people die, the way they are destined to, because that's what Field Reapers do, and Felix might finally get to meet Betty here in the human world.\n\nFelix The Reaper is produced by Kong Orange with support from The Danish Film Institute and The West Danish Film Fund, and the production has been invested in by CapNova."},{"t":"Fell Seal: Arbiter's Mark","p":["Linux","macOS","PlayStation 4","Windows","Xbox One","Nintendo Switch"],"d":"6 Eyes Studio","u":"1C Entertainment","g":"Tactical role-playing","r":"April 30, 2019","l":"https://en.wikipedia.org/wiki/Fell_Seal:_Arbiter's_Mark","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1k9m.jpg","s":"Fell Seal: Arbiter's Mark is a story-driven, turn-based tactical RPG set in a fantasy world with a touch of steampunk. Take control of the Arbiter Kyrie, an agent of the Immortal Council tasked with preserving stability and order throughout the land, and lead your troops through difficult encounters.\n\nExperience an epic and mature story, unfolding through over 40 story encounters and topped with challenging end-game content.\n\nClassic tactical combat battles, with rugged terrain and elevation, taking place on beautiful hand-drawn environments.\n\nA deep and complex class system with over 30 classes and 300 abilities lets you truly customize every one of your characters through the selection of their class, sub-class and passives. Carefully craft the character you envision, be it a versatile generalist, a dedicated spell-caster or a mighty foe-crushing specialist!\n\nCustomize your troops' appearance your way, by selecting their portrait, outfit, colors and overall visuals from a wide selection.\n\nEquip your army with over 240 pieces of equipment, either purchased, gathered from fallen enemies or created from crafting."},{"t":"Feudal Alloy","p":["Windows","macOS","Android","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Attu Games","u":"Attu Games","g":"Platform role-playing","r":"January 17, 2019","l":"https://en.wikipedia.org/wiki/Feudal_Alloy","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1idk.jpg","s":"It's a metroidvania-style action RPG with fishbowl-powered medieval robots!\nExplore a huge medieval world, improve your combat skills by smashing a lot of mechanic creatures and talk to other robots using unique animated dialogues."},{"t":"FIFA 20","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"EA Sports","g":"Sports","r":"September 27","l":"https://en.wikipedia.org/wiki/FIFA_20","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co206p.jpg","s":"Powered by Frostbite, EA SPORTS FIFA 20 for PC brings two sides of The World’s Game to life - the prestige of the professional stage and an all-new, authentic street football experience in EA SPORTS VOLTA. FIFA 20 innovates across the game, FOOTBALL INTELLIGENCE unlocks an unprecedented platform for gameplay realism, FIFA Ultimate Team offers more ways to build your dream squad and EA SPORTS VOLTA returns the game to the street with an authentic form of small-sided football."},{"t":"Filthbreed","p":["Windows"],"d":"Borja Zorozo","g":"Shooter","r":"February 5, 2019","l":"https://en.wikipedia.org/wiki/Filthbreed","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co62jz.jpg","s":"Filth comes crawling out of the cracks..."},{"t":"Final Fantasy IX","p":["Nintendo Switch","Xbox One"],"u":"Square Enix","g":"RPG","r":"February 13","l":"https://en.wikipedia.org/wiki/Final_Fantasy_IX"},{"t":"Final Fantasy VII","p":["Nintendo Switch","Xbox One"],"u":"Square Enix","g":"RPG","r":"March 26","l":"https://en.wikipedia.org/wiki/Final_Fantasy_VII"},{"t":"Final Fantasy VIII Remastered","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Square Enix","g":"RPG","r":"September 3","l":"https://en.wikipedia.org/wiki/Final_Fantasy_VIII_Remastered","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobktf.jpg","s":"Final Fantasy VIII Remastered features upgraded character models, enhanced Guardian Forces and improved visual effects while preserving the original game’s story and pre-rendered backgrounds. It includes modern features such as achievements, controller support, and optional battle enhancements like 3x speed, no encounters and max stats."},{"t":"Final Fantasy X/X-2 HD Remaster","p":["Nintendo Switch","Xbox One"],"u":"Square Enix","g":"RPG","r":"April 16","l":"https://en.wikipedia.org/wiki/Final_Fantasy_X/X-2_HD_Remaster"},{"t":"Final Fantasy XII: The Zodiac Age","p":["Nintendo Switch","Xbox One"],"u":"Square Enix","g":"RPG","r":"April 30","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XII"},{"t":"Final Fantasy XIV: Shadowbringers","p":["PlayStation 4","Windows"],"d":"Square Enix","u":"Square Enix","g":"MMO, RPG","r":"July 2, 2019","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XIV_(2010_video_game)"},{"t":"Final Fantasy XV","p":["Stadia"],"u":"Square Enix","g":"Action RPG","r":"November 19","l":"https://en.wikipedia.org/wiki/Final_Fantasy_XV"},{"t":"Fire Emblem: Shadow Dragon and the Blade of Light","p":["Nintendo Switch"],"g":"Tactical RPG","r":"March 13"},{"t":"Fire Emblem: Three Houses","p":["Nintendo Switch"],"u":"Nintendo","g":"Tactical RPG","r":"July 26","l":"https://www.igdb.com/games/fire-emblem-three-houses","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n8t.jpg","s":"Fire Emblem: Three Houses is a tactical role-playing game developed by Intelligent Systems and Koei Tecmo for the Nintendo Switch. Players take the role of a professor at Garreg Mach Monastery, where they teach and guide one of three student houses. Gameplay combines turn-based battles, character development, exploration, and relationship-building."},{"t":"Fishing Star World Tour","p":[],"l":"https://en.wikipedia.org/wiki/Fishing_Star_World_Tour"},{"t":"Fishing Universe Simulator","p":["Nintendo Switch"],"g":"Simulator, Sport","l":"https://en.wikipedia.org/wiki/Fishing_Universe_Simulator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co57no.jpg","s":"Fishing Universe Simulator is a comprehensive fishing simulator which allows using various techniques, in different places around the world!\n\nIf you are bored of waiting for fish to take and falling asleep in front of the console, this means that you have played a bad game! In the Fishing Universe Simulator this will never happen. Select the appropriate equipment and bait, cast your line and wait for a bite. Success is guaranteed!\n\nEverybody likes to use diverse equipment, which you will find in our game. An enormous quantity of rods, reels, baits, and lines are waiting for you to discover.\n\nEvery fisherman likes to admire his trophies. Some release their fish, other stuff and hang them on their walls. In Fishing Universe Simulator you can exactly do the same! Decide yourself what you want to do with the fish you catch. Sell? Release? Stuff? The choice is yours!"},{"t":"Fitness Boxing","p":["Nintendo Switch"],"u":"Nintendo","g":"Fitness , Rhythm","r":"January 4","l":"https://en.wikipedia.org/wiki/Fitness_Boxing"},{"t":"Five Nights at Freddy's: Help Wanted","p":["PlayStation 4","Windows"],"d":"Scott Cawthon, Steel Wool Studios","u":"Scott Cawthon","g":"Survival horror","r":"May 28, 2019","l":"https://en.wikipedia.org/wiki/Five_Nights_at_Freddy's:_Help_Wanted","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co62bd.jpg","s":"Five Nights at Freddy’s: Help Wanted is a collection of classic and original mini-games set in the Five Nights universe. Survive terrifying encounters with your favorite killer animatronics in a collection of new and classic Five Nights at Freddy's experiences. “Where fantasy and fun come to life!”"},{"t":"Flowers: Les Quatre Saisons","p":["PlayStation 4"],"u":"Prototype","g":"Visual novel","r":"March 7"},{"t":"Focus on You","p":["PlayStation 4","Windows"],"d":"Smilegate Entertainment","u":"Smilegate Entertainment","g":"Adventure","r":"July 5, 2019","l":"https://en.wikipedia.org/wiki/Focus_on_You","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2kbj.jpg","s":"The love at first sight, came like a sunny summer day. Meet YUA and make your own sparkling moments."},{"t":"Football Manager 2020","p":["Windows","iOS","Android","Stadia"],"u":"Sega","g":"Sports management","r":"November 19","l":"https://en.wikipedia.org/wiki/Football_Manager_2020","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20ui.jpg","s":"Put your opinions to good use and do things your way at your club this season. Every decision counts in FM20 with new features and polished game mechanics adding fresh and authentic dimensions, empowering managers to take greater accountability for both their own and their team’s destiny."},{"t":"Forager","p":["Windows","PlayStation 4","Nintendo Switch"],"d":"HopFrog","u":"Humble Bundle","g":"Open world, adventure","r":"April 18, 2019","l":"https://en.wikipedia.org/wiki/Forager_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co86yq.jpg","s":"Forager is the popular crafting, exploration and base building game that can best be defined as “the idle game that you want to actively keep playing”.\n\nA quirky mix between old school 2D Zelda experiences and modern Minecraft or Terraria-like crafting games that places players into a small piece of land with just a pickaxe and a desire for expansion and exploration.\n\nPlayers can buy procedurally generated lands to uncover secrets, solve puzzles, find dungeons, treasure and forgotten relics and to expand their sprawling bases. Nearly impossible to put down, there is always something to manage or work towards!"},{"t":"Frane: Dragons' Odyssey","p":["Xbox One"],"u":"Kemco","g":"Action RPG","r":"April 4"},{"t":"Freddy in Space 2","p":["Windows"],"g":"Shooter, Platform","l":"https://en.wikipedia.org/wiki/Freddy_in_Space_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3hdh.jpg","s":"Freddy is back... in space! Every good horror series inevitably goes to space, but how many of them go back for a second round?\n\nWhen Freddy leaves the lunar base on a deep-space mission, the central computer system is hijacked by the newly installed high-tech computer assistant: L.ogarithmic O.nline LAN-compatible Z.ero-error H.ydraulic A.uxiliary X.ylophone(?), otherwise known as L.O.L.Z.H.A.X.\n\nLolzHax has brainwashed the other resident space warriors, Bonnie, Chica, Foxy, and that weird gangly space puppet, and has locked Freddy's son outside the station with limited air remaining. Can Freddy rescue his friends, defeat LolzHax, and save his son in time?\n\nThis game was originally designed for the December 3rd, 2019 fundraiser for St. Jude hosted by Game Theory. The live-stream is over now and was a big success. Thank you to everyone who watched and contributed!"},{"t":"Freedom Finger","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Wide Right Interactive","g":"Shoot 'em up","r":"September 27","l":"https://en.wikipedia.org/wiki/Freedom_Finger"},{"t":"Friday the 13th: The Game","p":["Nintendo Switch"],"u":"Gun Media","g":"Survival horror","r":"August 13"},{"t":"Frog Detective 2: The Case of the Invisible Wizard","p":["Windows","macOS"],"d":"Grace Bruxner, Thomas Bowker","g":"Adventure, Comedy","r":"December 9, 2019","l":"https://en.wikipedia.org/wiki/Frog_Detective_2:_The_Case_of_the_Invisible_Wizard","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1umw.jpg","s":"The famed Frog Detective returns in the most thrilling mystery yet! A town’s welcoming celebration for a mysterious Invisible Wizard has been ripped to shreds by an unknown culprit. The Detective must find out “whodunnit”! The Case of the Invisible Wizard is the second game in the Frog Detective series, following The Haunted Island, which was loved by all.*\n\n*(Except for one user on Steam who called it “a middle finger and a waste of $5”, but we can’t win em all.)"},{"t":"Frogger in Toy Town","p":["iOS","macOS","tvOS"],"d":"Q-Games","u":"Konami","g":"Action","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Frogger_in_Toy_Town","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2o2r.jpg","s":"Toppling blocks, falling books...\nThings that seem unimportant to humans can pose great danger in the frog world...\n\nFrogger is back! The classic frog-action game returns on Apple Arcade with an all-new look and the same simple gameplay. Guide the iconic amphibian forward as you evade the numerous obstacles in your path!\n\n- Simple tap and swipe controls!\n- Playable in both landscape and portrait screen modes!\n- Over 400 pieces of furniture and other items ensure that stages are never dull!\n- Customize Frogger with over 20 different costumes!\n- Various missions give stages added replay value!\n- Play together with friends in the co-op mode!"},{"t":"Frostpunk","p":["PlayStation 4","Xbox One"],"u":"11 Bit Studios","g":"City builder","r":"October 11","l":"https://en.wikipedia.org/wiki/Frostpunk"},{"t":"Fun! Fun! Animal Park","p":["Nintendo Switch"],"u":"Aksys Games","g":"Party","r":"March 28"},{"t":"Game of Thrones: Winter is Coming","p":["Browser","Windows","iOS","Android"],"d":"Yoozoo Games","u":"Yoozoo Games","g":"Massively multiplayer online real-time strategy","r":"March 15, 2019","l":"https://en.wikipedia.org/wiki/Game_of_Thrones:_Winter_is_Coming","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1kuo.jpg","s":"Game of Thrones Winter is Coming picks up right after the death of Lord Eddard Stark. You’ll play the part of an ambitious Westerosi lord determined to stop the endless fighting between the Seven Kingdoms and save people from endless war, which doesn’t sound like many Westerosi lords we know. Along the way, you’ll come into contact with characters from the show and get a chance to recruit them to your cause."},{"t":"Gato Roboto","p":["Nintendo Switch","Windows"],"d":"Doinksoft","u":"Devolver Digital","g":"Action-adventure, metroidvania","r":"May 30, 2019","l":"https://en.wikipedia.org/wiki/Gato_Roboto","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ugu.jpg","s":"Pounce inside of your cozy armored mech and set off on a dangerous trek through an alien underworld full of irritable creatures and treacherous obstacles in a valiant effort to save your stranded captain and his crashed spaceship.\n\nTiptoe outside the friendly confines of your technological marvel and follow your feline instincts through tight tunnels and mysterious waterways to scavenge for new weapons and gear. Adventure awaits the most curious of cats in Gato Roboto!"},{"t":"Gears 5","p":["Windows","Xbox One"],"u":"Xbox Game Studios","g":"TPS","r":"September 10","l":"https://en.wikipedia.org/wiki/Gears_5","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2oz5.jpg","s":"From one of gaming’s most acclaimed sagas, Gears is bigger than ever, with five thrilling modes and the deepest campaign yet. With all-out war descending, Kait Diaz breaks away to uncover her connection to the enemy and discovers the true danger to Sera – herself."},{"t":"Gears Pop!","p":["Windows","Android","iOS"],"d":"Mediatonic, The Coalition","u":"Xbox Game Studios","g":"Real-time strategy","r":"August 22, 2019","l":"https://en.wikipedia.org/wiki/Gears_Pop!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1pbz.jpg","s":"Gears POP! is a real-time multiplayer mobile game featuring fan-favorite Gears of War characters in a Funko art style. Collect charming characters, fight real-time explosive arena battles, and mix and match powerful units and support items to build the strongest squad."},{"t":"Generation Zero","p":["Windows","PlayStation 4","Xbox One"],"u":"Avalanche Studios","g":"Action-adventure, FPS","r":"March 26","l":"https://en.wikipedia.org/wiki/Generation_Zero_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co66ky.jpg","s":"Generation Zero is a stealth-action shooter where you wage guerilla warfare against lethal mechanical enemies. Explore a vast open world map inspired by the Swedish Cold War era, take part in the resistance alone or with up to three friends in seamless co-op."},{"t":"Genesis Alpha One","p":["Windows","PlayStation 4","Xbox One"],"d":"Radiation Blue","u":"Team17","g":"Roguelike, simulation","r":"January 29, 2019","l":"https://en.wikipedia.org/wiki/Genesis_Alpha_One","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1i2h.jpg","s":"Explore a vast universe in this roguelike, ship building, FPS\n\nGenesis Alpha One mixes thrilling roguelike mechanics with a deep ship builder and fast first-person action, putting you in the role of an interstellar pioneer.\n\nAs the Captain of a Genesis starship, you journey into uncharted space on the ultimate mission. Build and manage a space vessel, farm resources, deal with terrifying alien infestations, clone creatures and explore a vast, randomly generated universe.\n\nYour goal: Find new homes for humanity’s DNA and save the species from extinction."},{"t":"Gensou SkyDrift","p":["Windows","Nintendo Switch"],"u":"Unties","g":"Racing","r":"December 12","l":"https://en.wikipedia.org/wiki/Gensou_SkyDrift"},{"t":"Ghost Giant","p":["PlayStation 4","PlayStation VR"],"d":"Zoink","u":"Zoink","g":"Puzzle, adventure","r":"April 19, 2019","l":"https://en.wikipedia.org/wiki/Ghost_Giant","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3m95.jpg","s":"A friend in need is a friend indeed, and friendship can come in the most unusual forms. Like in that of a giant ghost.\n\nIn Ghost Giant, you meet young Louis. He lives in an out-of-the-way part of town, where he tends to the family sunflower farm together with his mother. Life isn’t always that easy though, and Louis is incredibly lonely. That is, until you enter his life.\nAs the player you take on the role of the Ghost Giant. And a giant you are indeed! Use your see-through hands to lift furniture, vehicles and trees. You can even rotate and open entire buildings to reveal the stories going on inside. The picturesque town of Sancourt becomes your own little dollhouse sandbox."},{"t":"Ghost Parade","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Aksys Games","g":"Adventure","r":"October 31"},{"t":"Ghostbusters: The Video Game Remastered","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Mad Dog Games","g":"TPS","r":"October 4"},{"t":"Gibbous - A Cthulhu Adventure","p":["Windows","macOS","Linux"],"d":"Stuck In Attic","u":"Stuck In Attic","g":"Point-and-click adventure game","r":"August 7, 2019","l":"https://en.wikipedia.org/wiki/Gibbous_-_A_Cthulhu_Adventure"},{"t":"Global Soccer Manager 2019","p":["Windows"],"u":"Forever Young Games","g":"Sports","r":"May 31"},{"t":"Gnosia","p":["PlayStation Vita"],"d":"Petit Depotto","u":"Mebius, Petit Depotto, Playism","g":"Visual novel, role-playing, social deduction","r":"June 20, 2019","l":"https://en.wikipedia.org/wiki/Gnosia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9458.jpg","s":"Gnosia is a Sci-Fi Social Deduction RPG in which you will engage in discussion with a variety of unique characters, with the aim of identifying the Gnosia among the group. Players will have to use what information they can gather during the discussions to ascertain whom they think is Gnosia and then vote to put them into cold sleep. As you progress, your abilities will improve - but so will those of the crew.\n\nAs the numbers of crew members, Gnosia, and various “roles” increase, it will become increasingly difficult to determine who is telling the truth. Work in collaboration with or against other crew members to ensure your survival until the end."},{"t":"God Eater 3","p":["Windows","PlayStation 4","Nintendo Switch"],"u":"Bandai Namco Entertainment","g":"Action RPG","r":"February 8","l":"https://en.wikipedia.org/wiki/God_Eater_3"},{"t":"Golem","p":["PlayStation 4"],"u":"Perp Games","g":"Adventure","r":"November 15","l":"https://en.wikipedia.org/wiki/Golem_(2019_video_game)"},{"t":"Gorn","p":["Windows"],"d":"Free Lives","u":"Devolver Digital","g":"Beat 'em up","r":"July 18, 2019","l":"https://en.wikipedia.org/wiki/Gorn_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co27pd.jpg","s":"GORN is a ludicrously violent VR gladiator simulator, made by Free Lives, the developers of Broforce and Genital Jousting.\n\nFeaturing a unique, fully physics driven combat engine, GORN combatants will be able to creatively execute their most violent gladiatorial fantasies in virtual reality. Savagely strike down an infinite supply of poorly-animated opponents with all manner of weapons – from swords, maces, and bows to nunchuks, throwing knives, massive two-handed warhammers or even your blood-soaked bare hands. The only limits to the carnage are your imagination and decency, in the most brutal and savage VR face-smashing game ever produced by man."},{"t":"Grandia HD Collection","p":["Nintendo Switch"],"u":"GungHo Online Entertainment","g":"RPG","r":"August 16","l":"https://en.wikipedia.org/wiki/Grandia_HD_Collection"},{"t":"Grandia HD Remaster","p":["Windows"],"u":"GungHo Online Entertainment","g":"RPG","r":"October 15","l":"https://en.wikipedia.org/wiki/Grandia"},{"t":"GreedFall","p":["Windows","PlayStation 4","Xbox One"],"u":"Focus Home Interactive","g":"Action RPG","r":"September 10","l":"https://en.wikipedia.org/wiki/GreedFall","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsi1.jpg","s":"GreedFall is a single-player action RPG set in a fictional world inspired by 17th-century Baroque Europe. Players take the role of a diplomat arriving on a remote island inhabited by natives with supernatural abilities, now contested by colonial factions from various nations. The game emphasizes player choice, offering combat, diplomacy, and stealth approaches to quests, with decisions affecting relationships between the island's competing factions. A prequel, GreedFall 2: The Dying World, was released in 2026."},{"t":"Green Hell","p":["Windows"],"d":"Creepy Jar","u":"Creepy Jar","g":"Survival","r":"September 5, 2019","l":"https://en.wikipedia.org/wiki/Green_Hell_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9d3h.jpg","s":"Green Hell is a sweltering struggle for survival in the Amazonian rainforest. Clinging to life, the player is set on a journey of durability as the effects of solitude wear heavy not only on the body but also the mind. How long can you survive against the dangers of the unknown?"},{"t":"Grid","p":["Windows","PlayStation 4","Xbox One","Stadia"],"u":"Codemasters","g":"Racing","r":"October 11","l":"https://en.wikipedia.org/wiki/Grid_(2019_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsvq.jpg","s":"Grid is a racing experience like no other. Offering unrivalled moment-to-moment racing, Grid returns with an all-new experience where every race is the chance to choose your own path, create your own story and conquer the world of motorsport."},{"t":"Grimm's Hollow","p":["Windows"],"d":"Ghosthunter","u":"Ghosthunter","g":"Adventure, role-playing","r":"October 31, 2019","l":"https://en.wikipedia.org/wiki/Grimm's_Hollow","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2j8j.jpg","s":"A spooky, freeware RPG where you search the afterlife for your brother. Reap ghosts with your scythe, explore haunted caves, and eat ghostly treats on your journey through death."},{"t":"Grindstone","p":["iOS","macOS","tvOS"],"d":"Capybara Games","u":"Capybara Games","g":"puzzle","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Grindstone_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2f2q.jpg","s":"A puzzle battle adventure. Help Jorj climb Grindstone Mountain and defeat many creeps that try to stop him."},{"t":"Groove Coaster Wai Wai Party","p":[],"l":"https://en.wikipedia.org/wiki/Groove_Coaster_Wai_Wai_Party"},{"t":"Groundhog Day: Like Father Like Son","p":["Oculus Rift","SteamVR","PlayStation VR"],"g":"Puzzle, Adventure","l":"https://en.wikipedia.org/wiki/Groundhog_Day:_Like_Father_Like_Son","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wkh.jpg","s":"In Groundhog Day: Like Father Like Son players assume the role of Phil Connors Jr., the son of Phil Connors from the iconic film, who returns to Punxsutawney, Pennsylvania only to become trapped in a time loop just as his father once was. Players will solve puzzles and explore the world introduced by the film as they try to break out of this time loop."},{"t":"Guildlings","p":["iOS","macOS","tvOS"],"u":"Sirvo Studios","g":"Adventure, RPG","r":"November 8","l":"https://en.wikipedia.org/wiki/Guildlings"},{"t":"Gunvolt Chronicles: Luminous Avenger iX","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Inti Creates","g":"Action, Platformer","r":"September 26"},{"t":"Gylt","p":["Stadia"],"u":"Tequila Works","g":"Action-adventure, Puzzle","r":"November 19","l":"https://en.wikipedia.org/wiki/Gylt","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qad.jpg","s":"Enter the new creation from Tequila Works, a journey where you face your worst fears and are confronted with the emotional impact of your actions. Set in a creepy and melancholic world, GYLT is an eerie story mixing fantasy and reality in a surrealist place where your nightmares become reality. Hide from terrible creatures or confront them as you find your way through the challenges of this wicked world."},{"t":"Halo: The Master Chief Collection","p":["Windows"],"u":"Xbox Game Studios","g":"FPS","r":"December 3"},{"t":"Hana Awase","p":[],"l":"https://en.wikipedia.org/wiki/Hana_Awase"},{"t":"Hardcore Mecha","p":["Windows","PlayStation 4"],"u":"Arc System Works","g":"Action, Vehicle sim (mech)","r":"June 26"},{"t":"Harry Potter: Wizards Unite","p":["iOS","Android"],"u":"Niantic","g":"Adventure","r":"June 20"},{"t":"Harvest Moon: Mad Dash","p":["Nintendo Switch","PlayStation 4"],"u":"Natsume Inc.","g":"Puzzle","r":"October 29"},{"t":"Heart of the Woods","p":["Linux","macOS","Windows","Xbox One","Xbox Series X/S"],"d":"Studio Élan","u":"Studio Élan","g":"Visual novel","r":"February 15, 2019","l":"https://en.wikipedia.org/wiki/Heart_of_the_Woods","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ujc.jpg","s":"A fantasy yuri visual novel filled with magic, fairies, and a ghost girl. When Maddie and her best friend, Tara, journey to a remote forest village to investigate rumors of the supernatural, they find a whole lot more than they bargained for."},{"t":"Hearts and Hari","p":[],"l":"https://en.wikipedia.org/wiki/Hearts_and_Hari"},{"t":"Heave Ho","p":["Windows","macOS","Nintendo Switch"],"d":"Le Cartel Studio","u":"Devolver Digital","g":"Party, platform","r":"August 29, 2019","l":"https://en.wikipedia.org/wiki/Heave_Ho","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co45wx.jpg","s":"Heave Ho tasks up to four players with a simple goal – don’t fall to your death! Players will use their own two hands and the outstretched grip of their friends to grapple across each level on their way to victory. Grab one another’s hands, climb across dangling bodies, and swing your pals to safety in a wobbly, dangly mass of limbs. Customize your character with all manner of stylish accessories and zany accouterment in a vain attempt to remember who you are and which of your hands is the only thing between you and the plummet of doom."},{"t":"Heaven's Vault","p":["Windows","PlayStation 4"],"d":"Inkle","u":"Inkle","g":"Adventure game","r":"April 16, 2019","l":"https://en.wikipedia.org/wiki/Heaven's_Vault","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2t94.jpg","s":"Explore the lost ruins of the Nebula, read ancient inscriptions, and uncover a forgotten past in this narrative archaeological science-fiction adventure game from the creators of 80 Days."},{"t":"Heavy Rain","p":["Windows"],"u":"Sony Interactive Entertainment","g":"Interactive drama","r":"June 24","l":"https://en.wikipedia.org/wiki/Heavy_Rain"},{"t":"Hell Let Loose","p":["Windows"],"d":"Expression Games","u":"Team17","g":"Shooter, Simulator, Strategy, Indie","r":"June 6, 2019","l":"https://www.igdb.com/games/hell-let-loose","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc4gc.jpg","s":"Fight in the most iconic battles of the Second World War, including El Alamein, Stalingrad, Omaha Beach, and Foy! This is combat at a whole new scale.. with lumbering tanks dominating the battlefield, and crucial supply chains fuelling the frontlines, you are a cog in the machine of colossal combined arms warfare. Hell Let Loose puts you in the chaos of war, complete with deep player-controlled vehicles, a dynamically evolving front line, and crucial unit-focused gameplay that commands the tide of battle."},{"t":"Hellblade: Senua's Sacrifice","p":["Nintendo Switch"],"u":"Ninja Theory","g":"Action-adventure","r":"April 11"},{"t":"Hellion","p":["Windows"],"d":"Zero Gravity Games","g":"Survival","r":"October 21, 2019","l":"https://en.wikipedia.org/wiki/Hellion_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/nsjcrsfwxphgb91tttd0.jpg","s":"Hellion is a first person multiplayer space survival game.\n\nIt is a fusion of survival and space simulation genres that pits players against the deadly environment and one another. Survive in the harsh conditions of space and scavenge for air, fuel and other items necessary for survival. But keep in mind, you are not the only one out there. There are others, but will they help, or will they throw you to the void without a second thought? Remember, no matter how brutal space may seem, it cannot hold a candle to man."},{"t":"Hitman HD Enhanced Collection","p":["PlayStation 4","Xbox One"],"u":"Warner Bros. Interactive Entertainment","g":"Stealth","r":"January 11","l":"https://en.wikipedia.org/wiki/Hitman_(franchise)#Collections"},{"t":"Horace","p":["Windows"],"u":"505 Games","g":"Metroidvania, Platformer","r":"July 19","l":"https://en.wikipedia.org/wiki/Horace_(video_game)"},{"t":"Hot Lava","p":["iOS","macOS","tvOS","Windows"],"d":"Klei Entertainment","u":"Klei Entertainment","g":"platform","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Hot_Lava","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2o37.jpg","s":"Hot Lava transports you back to your childhood imagination. Relive those moments of excitement, joy and chaos. Traverse distinct worlds, from school hallways to the memories of your darkest fears. You will have to use all your skills to complete the treacherous obstacles that await."},{"t":"Human: Fall Flat","p":["iOS","Android"],"u":"505 Games","g":"Puzzle-platformer","r":"June 26"},{"t":"Hunt: Showdown","p":["Windows"],"u":"Crytek","g":"FPS, Survival horror","r":"August 27"},{"t":"Hunt: Showdown 1896","p":["Windows","Xbox One"],"d":"Crytek Frankfurt","u":"Crytek","g":"Shooter, Simulator","r":"August 27, 2019","l":"https://www.igdb.com/games/hunt-showdown-1896","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocuvs.jpg","s":"Hunt the corrupted in backwaters lost to history. Fight back against a timeless evil that pits you against twisted monsters and other desperate Hunters – solo or in a group – in a high-stakes, tactical, PvPvE, first person shooter. There are no heroes here. Risk everything as Hunt consumes you."},{"t":"Hyper Light Drifter","p":["iOS"],"u":"Abylight Studios","g":"Action RPG","r":"July 25","l":"https://en.wikipedia.org/wiki/Hyper_Light_Drifter"},{"t":"HyperParasite","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Troglobytes Games","u":"Troglobytes Games, Hound Picked Games","g":"Multidirectional shooter, bullet hell","l":"https://en.wikipedia.org/wiki/HyperParasite","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20bs.jpg","s":"A rogue-lite twin-stick shooter/brawler that never plays the same twice. Collect and control 60 different characters as the body-snatching alien Parasite with a grudge against humanity. Fight to the top of the food chain: possess the President, push the Big Red Button, and one-up the human race.\n\nIt's the 80's all over again.\nOnly this time, the human race has more than an obnoxious pop culture to contend with. With World War III nearing its demise, Earth only just begins to catch its breath when it is threatened by yet another menace. Unlike the preposterous mullets of its inhabitants, however, this one's invisible – a parasitic organism capable of making hosts of unsuspecting human beings, consuming what's left of their souls and wreaking unfathomable havoc. And it's spreading. With a vengeance. Martial laws have been declared to make way for a global hunt, battle-hardened law enforcers have made allies of the most degenerate of criminals, while the rest of the world is paralyzed with paranoia; yet who can be trusted? Who can see it, let alone destroy it? That's for them to worry about.\nFor you are the enemy. You are the organism with a mission. You are... HyperParasite."},{"t":"Hypnospace Outlaw","p":["Windows"],"u":"Tendershoot","g":"Adventure","r":"March 12","l":"https://en.wikipedia.org/wiki/Hypnospace_Outlaw","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2f5i.jpg","s":"Hypnospace Outlaw is a '90s internet simulator in which players act as Enforcers, volunteer moderators who scour Hypnospace's surreal network of weird and wonderful websites to hunt down wrongdoers while also keeping an eye on their inbox, avoiding viruses and adware, and downloading a plethora of apps that may or may not be useful."},{"t":"I Love You, Colonel Sanders!","p":["Windows","macOS"],"d":"Psyop","u":"KFC","g":"Dating sim, visual novel, advergame","r":"September 24, 2019","l":"https://en.wikipedia.org/wiki/I_Love_You,_Colonel_Sanders!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qen.jpg","s":"From the same people who brought you the bucket of chicken, comes the world’s first Colonel Sanders dating simulator.\n\nI Love You, Colonel Sanders! A Finger Lickin’ Good Dating Simulator follows you, a promising culinary student, as you try to date your classmate, Colonel Sanders. Throughout your journey, you’ll be faced with life-changing decisions that will affect your chances of friendship and love. But be careful! Your choices have real consequences with real animated characters’ feelings at stake.\n\nDo you have what it takes to survive culinary school? Will Colonel Sanders choose you to be his business partner? Or maybe even so much more? Find out in the most finger lickin’ good dating simulator ever created—a game that KFC actually made.\n\nFeatures:\n- 9 lovable characters\n- Multiple hours of play-through\n- Dateable Colonel Sanders\n- A secret ending! Shh!\n- Secret recipes! Double Shh!\n- Cooking battles\n- Battle battles\n- Earn a degree from a fictional culinary school\n- 11 Herbs and Spices\n- Cute miniature food\n- Officially created by KFC. No, really"},{"t":"Ice Age: Scrat's Nutty Adventure","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Outright Games","g":"Platformer","r":"October 18"},{"t":"Icewind Dale: Enhanced Edition","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Skybound Games","g":"RPG","r":"September 24"},{"t":"Iconary","p":[],"l":"https://en.wikipedia.org/wiki/Iconary"},{"t":"Idle Coffee Corp","p":["iOS","Android"],"u":"BoomBit","g":"Incremental","r":"May 14"},{"t":"Ikemen Vampire","p":[],"l":"https://en.wikipedia.org/wiki/Ikemen_Vampire"},{"t":"Illusion of L'Phalcia","p":["PlayStation 4"],"u":"Kemco","g":"RPG","r":"August 6","l":"https://en.wikipedia.org/wiki/Illusion_of_L%27Phalcia"},{"t":"Imperator: Rome","p":["Windows"],"u":"Paradox Interactive","g":"Grand strategy","r":"April 25"},{"t":"Imperial SaGa Eclipse","p":[],"l":"https://en.wikipedia.org/wiki/Imperial_SaGa_Eclipse"},{"t":"Indian Air Force: A Cut Above","p":["Android","iOS"],"d":"Threye Interactice Pvt Ltd","u":"Indian Air Force","g":"Combat flight simulator","r":"July 31, 2019","l":"https://en.wikipedia.org/wiki/Indian_Air_Force:_A_Cut_Above"},{"t":"Indivisible","p":["Windows","PlayStation 4","Xbox One"],"u":"505 Games","g":"Action RPG","r":"October 8","l":"https://en.wikipedia.org/wiki/Indivisible_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4n93.jpg","s":"Indivisible is a side-scrolling RPG in the vein of Valkyrie Profile, spanning a huge fantasy world inspired by our own world’s various cultures and mythologies.\n\nPlayers will navigate beautiful environments using a variety of different traversal abilities, and engage monsters in fast-paced combat."},{"t":"Inmost","p":["iOS"],"d":"Hidden Layer Games","u":"Chucklefish","g":"Platform game","r":"October 11, 2019","l":"https://en.wikipedia.org/wiki/Inmost","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2hvk.jpg","s":"\"Inmost is an atmospheric, story-driven puzzle platformer, following three playable characters within one dark, interconnecting story. In an old abandoned castle, you’ll need to explore every nook and cranny, avoid detection, slice your way through enemies and spring deadly traps in order to escape the evil that lurks within…\""},{"t":"Interrogation","p":["Windows","macOS","Linux"],"u":"Mixtvision","g":"Action-adventure, RPG","r":"December 5"},{"t":"Ion Fury","p":["Windows","macOS","Linux"],"u":"3D Realms","g":"FPS","r":"August 15","l":"https://en.wikipedia.org/wiki/Ion_Fury","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9iq1.jpg","s":"Shelly “Bombshell” Harrison takes on a quest to slay evil transhumanist mastermind Dr. Jadus Heskel in the streets of Neo DC. She leaves a trail of carnage throughout huge, multi-path levels filled with gigantic explosions, more secret areas than we can count, and inhuman foes behind every corner. There’s no regenerating health here; stop taking cover and start running and gunning.\n\nShelly’s crusade to take down Heskel’s army will see her leave destruction in her wake with a wide arsenal of weapons, complete with alternate fire modes and different ammo types.\n\nIon Fury laughs at the idea of mandatory checkpoints and straight paths through shooting galleries. But, just because this is a true old-school first-person shooter doesn’t mean we've ignored all the good new stuff the last two decades have brought. Headshots? Hell yeah. More physics and interactivity? You betcha. 3DRealms, Voidpoint and 1C Entertainment have taken the best of both worlds and cooked it all into a bloody stew."},{"t":"Islanders","p":["Windows","macOS","Linux"],"u":"Grizzly Games","g":"Casual , City builder","r":"April 4","l":"https://en.wikipedia.org/wiki/Islanders_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1s93.jpg","s":"Islanders is a minimalist strategy game about building cities on colorful islands. Explore an infinite number of ever-changing new lands, expand your settlements from sprawling villages to vast cities and enjoy the relaxing atmosphere."},{"t":"Jaws.io","p":["iOS","Android"],"d":"SRG Studios","u":"Universal Studios Interactive Entertainment LLC","g":"Action","r":"February 14, 2019","l":"https://en.wikipedia.org/wiki/Jaws.io","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1jce.jpg","s":"Jaws is now causing chaos on mobile in this fun and fast-paced multiplayer hyper-casual io game. Submerge yourself in the waters of Amity Island and rack up the points by avoiding being eaten, saving swimmers and finishing the round with the top score as Jaws!"},{"t":"Jenny LeClue","p":["iOS","Windows","macOS","Linux","PlayStation 4"],"d":"Mografi","u":"Mografi","g":"Adventure","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Jenny_LeClue","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qq3.jpg","s":"Jenny LeClue is a story focused exploration adventure game with memorable characters, a unique aesthetic, and an epic tangled mystery.\n\nJenny is a brilliant young detective, but nothing exciting happens in her small town of Arthurton, and she longs for real adventure. She gets more than she bargains for, when her mother is accused of murder. Jenny takes on the case of a lifetime and begins an unexpected, dangerous journey to uncover the truth. It’s also a coming-of-age meta-narrative about the blurred lines between right and wrong."},{"t":"Joe & Mac 2: Lost in the Tropics","p":["Nintendo Switch"],"g":"Action, Platformer","r":"September 5"},{"t":"John Wick Hex","p":["Windows","macOS"],"u":"Good Shepherd Entertainment","g":"Action, Strategy","r":"October 8","l":"https://en.wikipedia.org/wiki/John_Wick_Hex"},{"t":"JoJo's Bizarre Adventure: Last Survivor","p":["Arcade"],"g":"Hack and slash/Beat 'em up","l":"https://en.wikipedia.org/wiki/JoJo's_Bizarre_Adventure:_Last_Survivor","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8guu.jpg","s":"JoJo's Bizarre Adventure: Last Survivor is a 20 player battle royale game set in Morioh Town, released for arcades in Japan."},{"t":"Journey","p":["Windows"],"u":"Annapurna Interactive","g":"Adventure, Art","r":"June 6","l":"https://en.wikipedia.org/wiki/Journey_(2012_video_game)"},{"t":"Journey to Silius","p":["Nintendo Switch"],"g":"Run and gun","r":"December 12","l":"https://en.wikipedia.org/wiki/Journey_to_Silius"},{"t":"Joy Mech Fight","p":["Nintendo Switch"],"g":"Fighting","r":"January 16","l":"https://en.wikipedia.org/wiki/Joy_Mech_Fight"},{"t":"Judgment","p":["PlayStation 4"],"u":"Sega","g":"Action-adventure","r":"June 25","l":"https://en.wikipedia.org/wiki/Judgment_(video_game)"},{"t":"Jump Force","p":["Windows","PlayStation 4","Xbox One"],"u":"Bandai Namco Entertainment","g":"Fighting","r":"February 15","l":"https://en.wikipedia.org/wiki/Jump_Force","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qgv.jpg","s":"For the first time ever, the most famous Manga heroes are thrown into a whole new battleground: our world. Uniting to fight the most dangerous threat, the Jump Force will bear the fate of the entire human kind."},{"t":"Jump King","p":["Windows"],"u":"Nexile","g":"Platformer","r":"May 3","l":"https://en.wikipedia.org/wiki/Jump_King","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6gf6.jpg","s":"Jump King is a platforming challenge about struggling upwards in search of the legendary smoking hot babe! This lonely adventure to reach the top will demand full mastery of the technique of jumping. Just try to remember, with each fall there is a lesson to be learned."},{"t":"Just Dance 2020","p":["Wii","Nintendo Switch","PlayStation 4","Xbox One","Stadia"],"u":"Ubisoft","g":"Rhythm","r":"November 5","l":"https://en.wikipedia.org/wiki/Just_Dance_2020"},{"t":"Katana Zero","p":["Windows","Nintendo Switch"],"u":"Devolver Digital","g":"Hack and slash, Platformer","r":"April 18","l":"https://en.wikipedia.org/wiki/Katana_Zero","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1isp.jpg","s":"Katana Zero is a fast paced neo-noir action platformer, focusing on tight, instant-death acrobatic combat, and a dark 80's neon aesthetic. Aided with your trusty katana, the time manipulation drug Chronos and the rest of your assassin's arsenal, fight your way through a fractured city, and take back what's rightfully yours."},{"t":"Kid Icarus","p":["Nintendo Switch"],"g":"Action, Platformer","r":"March 13","l":"https://en.wikipedia.org/wiki/Kid_Icarus"},{"t":"Kill la Kill: If","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Arc System Works","g":"Action, Fighting","r":"July 26","l":"https://www.igdb.com/games/kill-la-kill-if","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1sb8.jpg","s":"You control Satsuki Kiryuin as the main protagonist of this game and proceed along with the story while battling against various characters. All scenarios are completely new and fully supervised under the watchful eyes of the original scenario-writer, Kazuki Nakashima. You will be experiencing the story unfold from the perspective of Satsuki Kiryuin, the rival of the original series' protagonist Ryuko."},{"t":"Killer Queen Black","p":["Windows","Nintendo Switch"],"u":"BumbleBear Games","g":"RTS","r":"October 11","l":"https://en.wikipedia.org/wiki/Killer_Queen_(video_game)"},{"t":"Kind Words","p":["Linux","macOS","Windows"],"g":"Casual","r":"July 6, 2019","l":"https://en.wikipedia.org/wiki/Kind_Words_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q4r.jpg","s":"A game about writing nice letters to real people. Write and receive encouraging letters in a cozy room. Trade stickers and listen to chill music. We're all in this together. Sometimes all you need are a few kind words."},{"t":"Kingdom Hearts III","p":["PlayStation 4","Xbox One"],"u":"Square Enix","g":"Action RPG","r":"January 29","l":"https://en.wikipedia.org/wiki/Kingdom_Hearts_III","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tpy.jpg","s":"Kingdom Hearts III is the third main installment in the Kingdom Hearts series developed and published by Square Enix. It was initially released January 2019 for the PlayStation 4 and the Xbox One. An expansion, Kingdom Hearts III Re Mind was released in January 2020.\n\nThe story takes place after the events of Kingdom Hearts 3D: Dream Drop Distance. It features an older Sora as the main protagonist, who sets forth on a new adventure to search for seven guardians of light in an attempt to stop Xehanort from bringing about a second Keyblade War. Sora is joined by Donald Duck, Goofy, Mickey Mouse, Riku, Kairi, and others. Along the way, Sora travels to many worlds from Disney and Pixar intellectual properties, and cross paths with the real Organization XIII.\n\nKingdom Hearts III features hack and slash combat reminiscent of Kingdom Hearts II, with elements from later handheld entries, allowing the player to control Sora in a party with Donald, Goofy, and up to two other Disney characters from the various worlds he visits. A major addition compared is the Formchange mechanic, which allows his currently equipped Keyblade to grant him special abilities and change shape. Sora can equip up to three Keyblades at a time, and cycle between them to use his abilities. Another addition is the Attractions mechanic, which occasionally allows Sora to summon and pilot a vehicle inspired by Disney theme park attractions. At certain points throughout the game, the player will be able to control other characters."},{"t":"Kingdom Under Fire II","p":["Windows"],"d":"Blueside, Phantagram","u":"Gameforge","g":"Real-time strategy, role-playing","r":"November 14, 2019","l":"https://en.wikipedia.org/wiki/Kingdom_Under_Fire_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e21.jpg","s":"Kingdom Under Fire II merges real-time strategy (RTS), role-playing game (RPG) and massively multiplayer online game (MMO) genres - the game is to have a single player, and online multiplayer mode. The game follows on chronologically from Kingdom Under Fire: Circle of Doom, and is the first RTS game set in the Kingdom Under Fire universe to be released since the 2005 Kingdom Under Fire: Heroes.\n\nThe game was announced in January 2008, and has been subject to delay and changes to release platforms; A closed beta-test began in December 2011 in South Korea.\n\nIn November 2013, the developers announced that a version for the PlayStation 4 was in development."},{"t":"Kirby Super Star","p":["Nintendo Switch"],"g":"Platformer","r":"December 12","l":"https://en.wikipedia.org/wiki/Kirby_Super_Star"},{"t":"Kirby's Adventure","p":["Nintendo Switch"],"g":"Platformer","r":"February 13","l":"https://en.wikipedia.org/wiki/Kirby%27s_Adventure"},{"t":"Kirby's Dream Course","p":["Nintendo Switch"],"g":"Sports (Mini golf)","r":"September 5","l":"https://en.wikipedia.org/wiki/Kirby%27s_Dream_Course"},{"t":"Kirby's Dream Land 3","p":["Nintendo Switch"],"g":"Platformer","r":"September 5","l":"https://en.wikipedia.org/wiki/Kirby%27s_Dream_Land_3"},{"t":"Kirby's Extra Epic Yarn","p":["Nintendo 3DS"],"u":"Nintendo","g":"Platformer","r":"March 8","l":"https://en.wikipedia.org/wiki/Kirby%27s_Extra_Epic_Yarn"},{"t":"Knights and Bikes","p":["Windows","PlayStation 4"],"u":"Double Fine","g":"Action-adventure","r":"August 27","l":"https://en.wikipedia.org/wiki/Knights_and_Bikes"},{"t":"Konami Arcade Classics","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Konami","g":"Platformer, Shoot 'em up","r":"April 13","l":"https://en.wikipedia.org/wiki/Konami_Arcade_Classics"},{"t":"Kotodama: The 7 Mysteries of Fujisawa","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"PQube","g":"Visual novel","r":"June 4"},{"t":"Kung-Fu Heroes","p":["Nintendo Switch"],"g":"Brawler","r":"August 21","l":"https://en.wikipedia.org/wiki/Kung-Fu_Heroes"},{"t":"Last Labyrinth","p":["Windows","PlayStation 4"],"u":"AMATA K.K.","g":"Adventure","r":"November 13"},{"t":"Last Oasis","p":["Windows"],"u":"Donkey Crew","g":"Survival","r":"September 3"},{"t":"Later Alligator","p":["Windows","macOS","Linux"],"d":"Pillow Fight","g":"Adventure game","r":"September 18, 2019","l":"https://en.wikipedia.org/wiki/Later_Alligator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ovn.jpg","s":"Pat the alligator, a (mostly) harmless and (probably) innocent reptile is at the center of a conspiracy that could bring down the biggest, scariest family in Alligator New York City: his own! Explore the city, meet the Family, and try to save Pat before the clock runs out."},{"t":"Layers of Fear 2","p":["Windows","PlayStation 4","Xbox One"],"u":"Gun Media","g":"Adventure, Horror","r":"May 28","l":"https://en.wikipedia.org/wiki/Layers_of_Fear_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2j3p.jpg","s":"Layers of Fear 2 is a first-person psychological horror game with an emphasis on exploration and story. Players control a Hollywood actor who heeds the call of an enigmatic director to take on the lead role in a film shot aboard an ocean liner. Beware, for all may not truly be what it seems."},{"t":"Layton's Mystery Journey: Katrielle and the Millionaire's Conspiracy – Deluxe Edition","p":["Nintendo Switch"],"u":"Level-5","g":"Puzzle, Adventure","r":"November 8"},{"t":"Left Alive","p":["Windows","PlayStation 4"],"u":"Square Enix","g":"Action-adventure","r":"March 5","l":"https://en.wikipedia.org/wiki/Left_Alive"},{"t":"Lego Brawls","p":["iOS","macOS","tvOS"],"d":"Red Games Co.","u":"Lego Games","g":"Fighting","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Lego_Brawls","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4uj8.jpg","s":"Build your way to the top in this lighthearted, team action brawler where anything can happen."},{"t":"Lego Builder's Journey","p":["iOS","macOS","tvOS"],"d":"Light Brick Studio","u":"Lego Games","g":"Puzzle","r":"December 19, 2019","l":"https://en.wikipedia.org/wiki/Lego_Builder's_Journey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co84pn.jpg","s":"A story about play, connections and adventure.\n\nStep through levels brick by brick with puzzles that ask us to sometimes follow the instructions… and sometimes to be creative and break the rules.\n\nBuilder’s Journey is a poetic puzzle that takes place in a LEGO brick world, brought to life with the most accurately rendered LEGO elements yet to feature on screens. Be taken through a breathtaking world filled with brick-by-brick effects, accompanied by a beautiful soundtrack.\n\nThroughout the narrative, there will be ups and downs, challenges and celebrations. Take the time to experiment, and most importantly, to play as figuring out who we are and what we become is the Builder’s Journey."},{"t":"Lego Jurassic World","p":["Nintendo Switch"],"u":"Warner Bros. Interactive Entertainment","g":"Action-adventure","r":"September 17","l":"https://en.wikipedia.org/wiki/Lego_Jurassic_World"},{"t":"Lego Star Wars Battles","p":["Android","iOS","macOS","tvOS"],"d":"TT Games Odyssey, Playdemic","u":"Warner Bros. Games, Lucasfilm Games","g":"Deck-building, real-time strategy","r":"September 3, 2019","l":"https://en.wikipedia.org/wiki/Lego_Star_Wars_Battles"},{"t":"Lego Tower","p":["iOS","Android"],"d":"NimbleBit","u":"NimbleBit","g":"Simulation, incremental","r":"July 1, 2019","l":"https://en.wikipedia.org/wiki/Lego_Tower","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co91wi.jpg","s":"Build and operate your own LEGO Tower! Construct a wide range of apartments and businesses for your Minifigure residents to live, work and play in. Visit your friends’ towers and trade items to help them build. Collect hundreds of unique Minifigure pieces and discover hidden characters. Build your dream LEGO Tower to new heights, the sky's the limit!"},{"t":"Let's Hunt Monsters","p":["iOS","Android"],"d":"TiMi Studio Group","u":"Tencent Games","g":"Location-based game","r":"April 11, 2019","l":"https://en.wikipedia.org/wiki/Let's_Hunt_Monsters"},{"t":"Letter Boxed","p":["Browser"],"d":"Sam Ezersky","u":"New York Times Company","g":"Word game","l":"https://en.wikipedia.org/wiki/Letter_Boxed","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co81kl.jpg","s":"Letter Boxed is an online word puzzle video game from The New York Times Games. Players are given a square with three letters per side (12 letters in total). Starting anywhere, they must connect the letters to make words of at least three letters. The goal is to use all of the letters at least once, in as few words as possible – equal to or below the target number set by the game (usually within 4, 5, or 6 words). The first letter of each new word must be the last letter of the previous word. Consecutive use of letters from the same side is not permitted (which precludes the use of double letter words such as \"Brilliantly\", \"Formatted\", and \"Dazzle\"). Proper nouns, profanities, and certain offensive terms are also excluded."},{"t":"Liberate Hong Kong","p":["Windows","macOS"],"d":"Hong Kong Protesters 2019","g":"Simulation","r":"November 20, 2019","l":"https://en.wikipedia.org/wiki/Liberate_Hong_Kong_(video_game)"},{"t":"Life Is Strange 2 – Episode 2: Rules","p":["Windows","PlayStation 4","Xbox One"],"u":"Square Enix","g":"Graphic adventure","r":"January 24","l":"https://en.wikipedia.org/wiki/Life_Is_Strange_2"},{"t":"Life Is Strange 2 – Episode 3: Wastelands","p":["Windows","PlayStation 4","Xbox One"],"u":"Square Enix","g":"Graphic adventure","r":"May 9","l":"https://en.wikipedia.org/wiki/Life_Is_Strange_2"},{"t":"Life Is Strange 2 – Episode 4: Faith","p":["Windows","PlayStation 4","Xbox One"],"u":"Square Enix","g":"Graphic adventure","r":"August 22","l":"https://en.wikipedia.org/wiki/Life_Is_Strange_2"},{"t":"Life Is Strange 2 – Episode 5: Wolves","p":["Windows","PlayStation 4","Xbox One"],"u":"Square Enix","g":"Graphic adventure","r":"December 3","l":"https://en.wikipedia.org/wiki/Life_Is_Strange_2"},{"t":"Little Big Workshop","p":["Windows","macOS","tvOS"],"d":"Mirage Game Studios","u":"HandyGames","g":"Construction and management simulation","r":"October 17, 2019","l":"https://en.wikipedia.org/wiki/Little_Big_Workshop","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20u4.jpg","s":"Imagine a magical factory, appearing right in your living room. A carefully planned masterpiece, where diligent workers throw together anything customers want. Rubber ducks and dressers, drones and electric guitars, scooters and other wonderful goods can be created from many different materials and sold for hard cash – cash you invest right back into your factory to get more machines, more workers and grow your business. In Little Big Workshop you become a factory tycoon!"},{"t":"Little Friends: Dogs & Cats","p":["Nintendo Switch"],"u":"Imagineer","g":"Simulation","r":"May 27"},{"t":"Little Misfortune","p":["Linux","macOS","Windows"],"d":"Killmonday Games","u":"Killmonday Games","g":"Adventure, Horror","r":"September 18, 2019","l":"https://en.wikipedia.org/wiki/Little_Misfortune","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1kw9.jpg","s":"Little Misfortune is an interactive story, focused on exploration and characters, both sweet and dark, where your choices have consequences."},{"t":"Little Town Hero","p":["Nintendo Switch"],"u":"Game Freak","g":"RPG","r":"October 16","l":"https://en.wikipedia.org/wiki/Little_Town_Hero"},{"t":"Lonely Mountains: Downhill","p":["PlayStation 4","Windows","Xbox One"],"d":"Megagon Industries","u":"Thunderful","g":"Sports","r":"October 23, 2019","l":"https://en.wikipedia.org/wiki/Lonely_Mountains:_Downhill","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2m9a.jpg","s":"Just you and your bike - take it on a thrilling ride down an unspoiled mountain landscape. Make your way through thick forests, narrow trails and wild rivers. Race, jump, slide and try not to crash - all the way from the peak to the valley!"},{"t":"Lost Ark","p":["Windows"],"d":"Tripod Studio, Smilegate","u":"Amazon Games, Smilegate","g":"MMORPG, action role-playing","r":"October 27, 2019","l":"https://en.wikipedia.org/wiki/Lost_Ark_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4w4j.jpg","s":"Embark on an odyssey for the Lost Ark in a vast, vibrant world: explore new lands, seek out lost treasures, and test yourself in thrilling action combat. Define your fighting style with your class and advanced class, and customize your skills, weapons, and gear to bring your might to bear as you fight against hordes of enemies, colossal bosses, and dark forces seeking the power of the Ark in this action-packed free-to-play RPG."},{"t":"Lost Ember","p":["Windows","PlayStation 4","Xbox One"],"d":"Mooneye Studios","u":"Mooneye Studios","g":"Adventure game","r":"November 22, 2019","l":"https://en.wikipedia.org/wiki/Lost_Ember","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2g2a.jpg","s":"Explore the remains of a fallen world from fascinating perspectives! Slip into the role of different animals to uncover the fate of an ancient world. Dive into deep waters, fly at lofty heights, dig underground as a mole or even climb steep cliffs with a mountain goat, there are lots of ways of getting around."},{"t":"Love Live! School Idol Festival All Stars","p":["iOS","Android"],"g":"Music, Role-playing (RPG), Adventure","l":"https://en.wikipedia.org/wiki/Love_Live!_School_Idol_Festival_All_Stars","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ii4.jpg","s":"Join the 27 school idols in creating unforgettable Live Shows!\n\nYou and the All Stars cast will write a new story together!\n\nTake on the role of a student at Nijigasaki High School which, located in the Odaiba area of Tokyo, offers students the freedom and opportunity to explore and specialize in a variety of subjects. While out in the city one day, your world is changed after seeing μ's and Aqours perform together.\n\nYou set out to become the closest ally and supporter to these brilliant school idols on their path to perform at the prominent School Idol Festival.\n\nThe journey to realize your and the school idols' dreams begins here!"},{"t":"Lovecraft's Untold Stories","p":["macOS","Windows","Nintendo Switch","PlayStation 4","Xbox One","iOS","Android","Xbox"],"d":"Blini Games","u":"Fulqrum Publishing, BadLand Publishing, Blini Games","g":"Action role-playing","r":"January 31, 2019","l":"https://en.wikipedia.org/wiki/Lovecraft's_Untold_Stories","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1l5m.jpg","s":"Lovecraft’s Untold Stories is an action RPG with rogue-like elements. Explore, improve your skills and gear, and fight cultists and creatures from the Mythos to stop the Old Ones’ plans in randomly generated levels based on Lovecraft stories. Madness and death await you—but maybe you can delay the inevitable…"},{"t":"Lovely Planet 2: April Skies","p":["Windows","macOS","Linux"],"d":"Quicktequila","u":"tinyBuild","g":"First-person shooter, platform","r":"June 18, 2019","l":"https://en.wikipedia.org/wiki/Lovely_Planet_2:_April_Skies","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5nt1.jpg","s":"Sequel to the most adorable First Person Shooter Gun Ballet. Feel the speed once again as you jump and shoot your way through the familiar cutesy abstract world filled with clever traps and angry baddies fuming with rage. Pick out targets with precision accuracy and dodge an infinite barrage of bullets carefully jumping between floating islands all while racing the clock for a better score."},{"t":"Lovers of Aether","p":["Windows"],"u":"Dan Fornace","g":"Dating sim","r":"April 1","l":"https://en.wikipedia.org/wiki/Lovers_of_Aether"},{"t":"Luigi's Mansion 3","p":["Nintendo Switch"],"u":"Nintendo","g":"Action-adventure","r":"October 31","l":"https://en.wikipedia.org/wiki/Luigi%27s_Mansion_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22a9.jpg","s":"Luigi embarks on a dream vacation with Mario and friends upon receiving an invitation to a luxurious hotel. However, his dream quickly becomes a nightmare when King Boo reveals everything had been a ploy to capture Mario and friends. With the assistance of Professor E. Gadd once again, the reluctant and cowardly hero Luigi traverses up and down treacherous floors of the now-ominous hotel on a quest to save them."},{"t":"Lurkers","p":["Browser"],"d":"Bergice Productions","u":"Bergice Productions","g":"Shooter, Platform, Role-playing (RPG), Simulator, Hack and slash/Beat 'em up, Adventure, Indie","r":"April 19, 2019","l":"https://www.igdb.com/games/lurkers--2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9hgu.jpg","s":"Lurkers is a chaotic 2D multiplayer sandbox where you can build, battle, and survive! Fight zombies, conquer game modes like Bedwars, and unleash your creativity in a world that’s yours to shape and destroy."},{"t":"M.A.S.S. Builder","p":["Windows"],"d":"Vermillion Digital","u":"Sekai Project","g":"Fighting RPG","r":"September 13, 2019","l":"https://en.wikipedia.org/wiki/M.A.S.S._Builder"},{"t":"Madden NFL 20","p":["Windows","PlayStation 4","Xbox One"],"u":"EA Sports","g":"Sports","r":"August 2","l":"https://en.wikipedia.org/wiki/Madden_NFL_20","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1nh7.jpg","s":"Feel like an NFL Superstar in Madden NFL 20. Be the Face of an NFL franchise where the decisions you make matter in your journey to become an NFL Superstar in ‘FACE OF THE FRANCHISE: QB1’. Feel the emotion, personality, and power of NFL Superstars with ‘SUPERSTAR X-FACTOR’, an all-new abilities progression system that reveals special abilities for today’s most exciting NFL Superstars heightening the level strategy and excitement in every game."},{"t":"Magatsu Wahrheit","p":[],"l":"https://en.wikipedia.org/wiki/Magatsu_Wahrheit"},{"t":"Mage's Initiation: Reign of the Elements","p":["Windows","Linux","macOS"],"d":"Himalaya Studios","u":"Himalaya Studios","g":"Adventure","r":"January 30, 2019","l":"https://en.wikipedia.org/wiki/Mage's_Initiation:_Reign_of_the_Elements","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co62ng.jpg","s":"D'arc is a sixteen-year-old Mage to be. A sinister plot threatens his initiation and risks plunging the land of Iginor into conflict and chaos. Choose from four classes and train in the Elemental arts. Master a unique range of spells to solve puzzles, battle monsters, and confront the ultimate evil."},{"t":"Magic: The Gathering Arena","p":["Windows"],"d":"Wizards Digital Games Studio","u":"Wizards of the Coast","g":"Digital collectible card game","r":"September 26, 2019","l":"https://en.wikipedia.org/wiki/Magic:_The_Gathering_Arena","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1l8n.jpg","s":"Magic: The Gathering - Arena is a free to play digital, collectible card game by Wizards of the Coast that places the players in the shoes of a powerful magic-user that can cast spells, summon creatures, and attack opposing players.\n\nArena adds entire sets from the physical card game and features several modes/formats to play, including constructed, limited, and draft formats all of which also have their own season long rankings."},{"t":"Mario & Luigi: Bowser's Inside Story + Bowser Jr.'s Journey","p":["Nintendo 3DS"],"u":"Nintendo","g":"RPG","r":"January 11"},{"t":"Mario & Sonic at the Olympic Games Tokyo 2020","p":["Nintendo Switch"],"u":"Sega","g":"Sports","r":"November 5","l":"https://en.wikipedia.org/wiki/Mario_%26_Sonic_at_the_Olympic_Games_Tokyo_2020"},{"t":"Mario Kart Tour","p":["iOS","Android"],"u":"Nintendo","g":"Racing (kart)","r":"September 25","l":"https://en.wikipedia.org/wiki/Mario_Kart_Tour","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coafir.jpg","s":"Mario Kart takes a world tour!\n- Mario and friends go global in this new Mario Kart as they race around courses inspired by real-world cities in addition to classic Mario Kart courses! These destinations will be featured in tours that rotate every two weeks! In addition to courses based on iconic locales, some of your favorite Mario Kart characters will get variations that incorporate the local flavor of cities featured in the game!\n\nEndless Mario Kart fun at your fingertips!\n- The Mario Kart series known and loved by many is ready to take the world by storm – one smart device at a time! With just one finger, you can steer and drift with ease and sling devastating items as you go for the gold in cups filled with new and classic Mario Kart courses.\n\nNab 1st place with items and Frenzy mode!\n- In Mario Kart Tour you have access to an arsenal of powerful items that can mix things up on the racetrack! Turn up the heat by activating the new Frenzy mode, which gives an unlimited supply of a certain item and makes you invincible! Make the most of the ensuing chaos, as Frenzy mode only lasts a short time!\n\nCollect drivers, karts, badges, and more!\n- Earn Grand Stars by racing or fire off the featured pipe to receive more drivers, karts, and gliders! You can also proudly display badges, earned by completing certain challenges, next to your in-game name!\n\nBonus challenge courses put a twist on traditional races!\n- In certain races, 1st place isn't always the goal. With names like \"Vs. Mega Bowser\" and \"Goomba Takedown,\" these bonus challenge courses demand a different approach to gameplay and strategy!\n\nRace to increase your online rank!\n- Boost with the best of 'em! Your high scores will determine how you compare to other players all over the world. Keep practicing and trying out different combinations of drivers, karts, and gliders to increase your score and rise to the top!"},{"t":"Mario Royale","p":["Browser"],"d":"InfernoPlus","u":"InfernoPlus","g":"Battle royale, platformer","r":"June 15, 2019","l":"https://en.wikipedia.org/wiki/Mario_Royale","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co22j2.jpg","s":"Fan-made, free-to-play online game which it drops 75 players into either world 1, 2, or 3 from Super Mario Bros. for the NES. In order to win, you have to be one of the first three players to reach the castle at the end of the world.\n\nWhile you can't directly impede the progress of other players (who are represented by a \"ghost\" effect) just by running into them or around them, it is possible to utilize power-ups like stars to knock out the competition."},{"t":"Marvel Super War","p":["Android","iOS"],"d":"NetEase Games","u":"NetEase Games","g":"Multiplayer online battle arena","r":"December 19, 2019","l":"https://en.wikipedia.org/wiki/Marvel_Super_War","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1loz.jpg","s":"Marvel Super War is a free-to-play 3D, third-person multiplayer online battle arena (MOBA) game by NetEase and Marvel Entertainment. It is in beta both on Android and iOS and is available to download only in selected countries"},{"t":"Marvel Ultimate Alliance 3: The Black Order","p":["Nintendo Switch"],"u":"Nintendo","g":"Action RPG","r":"July 19","l":"https://www.igdb.com/games/marvel-ultimate-alliance-3-the-black-order","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1r88.jpg","s":"Assemble your ultimate team of Marvel Super Heroes from a huge cast including the Avengers, the Guardians of the Galaxy, the X-Men, and more! Team up with friends to prevent galactic devastation at the hands of the mad cosmic tyrant Thanos and his ruthless warmasters, The Black Order."},{"t":"Maximum Football 2019","p":["PlayStation 4","Xbox One"],"d":"Canuck Play Inc","u":"Spear Interactive Inc / Maximum Games","g":"Sports","r":"September 27, 2019","l":"https://en.wikipedia.org/wiki/Maximum_Football_2019","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1y90.jpg","s":"Select your league format (130 US teams or 27 Canadian teams) and create your own College Football universe by customizing every team, player, uniform and logo. Recruit the next College superstar, dominate the rankings and earn your way into a Bowl or Playoff game.\n\nRecreate Flutie magic! Play as Hall of Fame Quarterback Doug Flutie in Play Now or Season Mode."},{"t":"MechWarrior 5: Mercenaries","p":["Windows"],"u":"Piranha Games","g":"Vehicular combat, Action","r":"December 10"},{"t":"MediEvil","p":["PlayStation 4"],"u":"Sony Interactive Entertainment","g":"Action-adventure, Hack and slash","r":"October 25","l":"https://en.wikipedia.org/wiki/MediEvil_(2019_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tjg.jpg","s":"MediEvil is a modern reimagining of the 1998 action-adventure game MediEvil. Developed by Other Ocean Emeryville and published by Sony Interactive Entertainment, it was released exclusively for the PlayStation 4 on October 25, 2019.\n\nThe game retains the original’s story, following Sir Daniel Fortesque, a skeletal knight resurrected to defeat the evil sorcerer Zarok and save the kingdom of Gallowmere. The remake features completely overhauled graphics, updated controls, and re-recorded audio, while maintaining the classic gameplay elements, humor, and gothic aesthetic that defined the original."},{"t":"Memorrha","p":["Windows","macOS","Nintendo Switch","PlayStation 4","Xbox One"],"u":"StickyStoneStudio","g":"Puzzle, Adventure","r":"September 27"},{"t":"Merge Magic!","p":["iOS","Android"],"u":"Gram Games","g":"Puzzle, Adventure","r":"September 18","l":"https://en.wikipedia.org/wiki/Merge_Magic"},{"t":"Metal Wolf Chaos XD","p":["Windows","PlayStation 4","Xbox One"],"u":"Devolver Digital","g":"TPS","r":"August 6","l":"https://en.wikipedia.org/wiki/Metal_Wolf_Chaos_XD"},{"t":"Metro Exodus","p":["Windows","PlayStation 4","Xbox One","Stadia"],"u":"Deep Silver","g":"FPS","r":"February 15","l":"https://en.wikipedia.org/wiki/Metro_Exodus","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaroh.jpg","s":"Metro Exodus is an epic, story-driven first person shooter from 4A Games that blends deadly combat and stealth with exploration and survival horror in one of the most immersive game worlds ever created. Explore the Russian wilderness across vast, non-linear levels and follow a thrilling story-line that spans an entire year through spring, summer and autumn to the depths of nuclear winter. Inspired by the novels of Dmitry Glukhovsky, Metro Exodus continues Artyom’s story in the greatest Metro adventure yet."},{"t":"Micro Mages","p":["Nintendo Entertainment System"],"d":"Morphcat Games","u":"Morphcat Games","g":"Platform","r":"April 30, 2019","l":"https://en.wikipedia.org/wiki/Micro_Mages","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wsw.jpg","s":"Enter the Demon Fortress. Built to torture pesky adventurers, this place is home to great treasure and ghastly creatures alike. But don't worry, you can count on allies like Fairies and Magical Seagulls to come to your help!\n\nMicro Mages is an homage to NES-era platformers. Being a homebrew NES game itself, it was made completely from scratch. We carefully distilled the spirit of the best games in the system's library, all the while drawing inspiration from the modern and putting our own spin on things, creating an experience like no other on the NES."},{"t":"Minecraft Earth","p":["iOS","Android"],"u":"Xbox Game Studios","g":"AR","r":"December 11","l":"https://en.wikipedia.org/wiki/Minecraft_Earth"},{"t":"Mini Motorways","p":["iOS","tvOS"],"d":"Dinosaur Polo Club","u":"Dinosaur Polo Club","g":"Puzzle, strategy","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Mini_Motorways","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2p9v.jpg","s":"Mini Motorways is a strategy simulation game about designing the road map for a growing city. Build a traffic network, one road at a time, to create a bustling metropolis. Redesign your roads and place your motorways to get everyone where they need to go. How long can you keep the city moving?"},{"t":"Minit","p":["iOS","Android"],"u":"Devolver Digital","g":"Adventure","r":"June 27","l":"https://en.wikipedia.org/wiki/Minit_(video_game)"},{"t":"Minoria","p":["Windows","Nintendo Switch"],"u":"Dangen Entertainment","g":"Metroidvania","r":"August 27","l":"https://en.wikipedia.org/wiki/Minoria"},{"t":"Missed Messages","p":["Windows","macOS","Linux","Browser"],"d":"Angela He","u":"Angela He","g":"Visual novel","r":"May 1, 2019","l":"https://en.wikipedia.org/wiki/Missed_Messages","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co28l8.jpg","s":"‘goth gf’s iPhone’ airdrops you - accept or decline?\nA romance/horror story about life, death, and memes.\nA shift in perspective can change everything."},{"t":"Mistover","p":["Windows","Nintendo Switch","PlayStation 4"],"d":"Krafton","u":"Krafton","g":"Roguelike, role-playing","r":"October 10, 2019","l":"https://en.wikipedia.org/wiki/Mistover","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fa6.jpg","s":"''MIST-ical' RPG with expeditions for finding the key to survival. Choose your next step wisely and keep in mind that your every move will change the future."},{"t":"MLB The Show 19","p":["PlayStation 4"],"u":"Sony Interactive Entertainment","g":"Sports","r":"March 26","l":"https://en.wikipedia.org/wiki/MLB_The_Show_19"},{"t":"Mobile Suit Gundam: Battle Operation 2","p":["PlayStation 4"],"u":"Bandai Namco Entertainment","g":"Action","r":"October 1"},{"t":"Monkey Barrels","p":["Nintendo Switch"],"d":"Good-Feel","u":"Justdan International, Nicalis","g":"Shooter, Adventure, Indie","r":"November 7, 2019","l":"https://en.wikipedia.org/wiki/Monkey_Barrels","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1sew.jpg","s":"It's monkeys vs. machines in this zany action-packed shooter!\n\nIn addition to a 22-stage story mode, there's also an online competitive mode!\nFeatures 3D pixel art that puts a fresh spin on old-school graphics!\nTons of fun and challenging stages await you!"},{"t":"Monkey King: Hero is Back","p":["Windows","PlayStation 4"],"u":"THQ Nordic","g":"Action-adventure","r":"October 17"},{"t":"Monolisk","p":["Android","iOS"],"d":"Trickster Arts","u":"Trickster Arts","g":"Action role-playing game","r":"October 15, 2019","l":"https://en.wikipedia.org/wiki/Monolisk"},{"t":"Monster Boy and the Cursed Kingdom","p":["Windows"],"u":"FDG Entertainment","g":"Platformer","r":"July 25","l":"https://en.wikipedia.org/wiki/Monster_Boy_and_the_Cursed_Kingdom"},{"t":"Monster Energy Supercross – The Official Videogame 2","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Milestone srl","g":"Racing","r":"February 8"},{"t":"Monster Hunter: World – Iceborne","p":["Xbox One","PlayStation 4"],"d":"Capcom","u":"Capcom","g":"Action-adventure","r":"September 6, 2019"},{"t":"Moon: Remix RPG Adventure","p":["Nintendo Switch"],"u":"Onion Games","g":"RPG","r":"October 10"},{"t":"Mordhau","p":["Windows"],"d":"Triternion","u":"Triternion","g":"Fighting, hack 'n' slash","r":"April 29, 2019","l":"https://en.wikipedia.org/wiki/Mordhau_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qrx.jpg","s":"Mordhau is a multiplayer medieval slasher. Create your mercenary and fight in brutal battles where you will experience fast paced combat, castle sieges, cavalry charges, and more."},{"t":"Mortal Kombat 11","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One","Stadia"],"u":"Warner Bros. Interactive Entertainment","g":"Fighting","r":"April 23","l":"https://en.wikipedia.org/wiki/Mortal_Kombat_11","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20mh.jpg","s":"Mortal Kombat is back and better than ever in the next evolution of the iconic franchise. The all new Custom Character Variations give you unprecedented control of your fighters to make them your own. The new graphics engine showcases every skull-shattering, eye-popping moment, bringing you so close to the fight you can feel it. Featuring a roster of new and returning Klassic Fighters, Mortal Kombat's best-in-class cinematic story mode continues the epic saga over 25 years in the making."},{"t":"Mosaic","p":["iOS","tvOS","Linux","Windows"],"d":"Krillbite Studio","u":"Raw Fury","g":"Adventure, art","r":"November 1, 2019","l":"https://en.wikipedia.org/wiki/Mosaic_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cod5ka.jpg","s":"Mosaic is a mysterious narrative game, where you follow the repetitive and lonely life of an average commuter.... Until one day, when strange things start happening."},{"t":"MotoGP 19","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"u":"Milestone srl","g":"Racing","r":"June 6","l":"https://en.wikipedia.org/wiki/MotoGP_19"},{"t":"Murder on the Island","p":["Windows"],"u":"Forever Young Games","g":"Visual novel","r":"October 10"},{"t":"Mutant Year Zero: Road to Eden : Deluxe Edition","p":["Nintendo Switch"],"u":"Funcom","g":"TBS","r":"July 30"},{"t":"Mutazione","p":["Linux","macOS","iOS","Windows","PlayStation 4"],"d":"Die Gute Fabrik","u":"Akupara Games, Die Gute Fabrik","g":"Adventure","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Mutazione","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uxn.jpg","s":"Mutazione is a adventure exploration video game set on an island where the player tends to the local gardens and learns more about the town's people. The game takes place over different days, each with unique events. While gardening the player can grow different types of plants, from bushes to trees. Seeds can be found all over the island from other plants. The player needs to give the plant the required space in order for it to grow and different ones require other types of soil. Each plant also creates different sounds, which when combined with other greenery can create music."},{"t":"MXGP 2019","p":["Windows","PlayStation 4","Xbox One"],"u":"Milestone srl","g":"Racing","r":"August 27","l":"https://en.wikipedia.org/wiki/MXGP_The_Official_Motocross_Videogame"},{"t":"My Friend Pedro","p":["Windows","Nintendo Switch"],"u":"Devolver Digital","g":"Shoot 'em up","r":"June 20","l":"https://en.wikipedia.org/wiki/My_Friend_Pedro","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa4j0.jpg","s":"My Friend Pedro is a violent ballet about friendship, imagination, and one man’s struggle to obliterate anyone in his path at the behest of a sentient banana."},{"t":"My Memory of Us","p":["Nintendo Switch"],"u":"Crunching Koalas","g":"Graphic adventure, Platformer","r":"January 24"},{"t":"My Time at Portia","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Team17","g":"Sandbox","r":"April 16","l":"https://en.wikipedia.org/wiki/My_Time_at_Portia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coctbs.jpg","s":"Start a new life in the enchanting town of Portia! Restore your Pa's neglected workshop to its former glory by fulfilling commissions, growing crops, raising animals, and befriending the quirky inhabitants of this charming post-apocalyptic land!"},{"t":"Mystery Dungeon: Shiren the Wanderer","p":["iOS","Android"],"u":"Spike Chunsoft","g":"Roguelike","r":"March 12"},{"t":"Nancy Drew: Midnight in Salem","p":["macOS","Windows"],"g":"Point-and-click, Adventure","l":"https://en.wikipedia.org/wiki/Nancy_Drew:_Midnight_in_Salem","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1skw.jpg","s":"Are the ghosts real? Has Salem’s dark history come to life, or is there someone else to blame? Time is short, and Nancy must find the answers before the clock strikes midnight."},{"t":"NASCAR Heat 4","p":["Windows","PlayStation 4","Xbox One"],"d":"Monster Games","u":"704Games","g":"Racing","r":"September 13, 2019","l":"https://en.wikipedia.org/wiki/NASCAR_Heat_4","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24ce.jpg","s":"NASCAR Heat 4 is the official video game of NASCAR, featuring the 2019 Monster Energy NASCAR Cup Series, NASCAR Xfinity Series, NASCAR Gander Outdoors Truck Series and fan-favorite, the Xtreme Dirt Tour. Career mode enhancements, updated visuals, and new engine audio immerses players in the race. The new track map and unlockable paint schemes, combined with new AI controls, drafting features, and updated user interface gives players a more authentic feel for the action. Compete across 38 tracks against the 150+ official NASCAR teams and drivers as you race for the championship!"},{"t":"NBA 2K20","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One","Stadia"],"u":"2K Sports","g":"Sports","r":"September 6","l":"https://en.wikipedia.org/wiki/NBA_2K20","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1wmv.jpg","s":"NBA 2K has evolved into much more than a basketball simulation. The game is featuring best in class graphics & gameplay, ground breaking game modes, and unparalleled player control and customization. Plus, with its immersive open-world neighborhood, NBA 2K20 is a platform for gamers and ballers to come together and create what’s next in basketball culture."},{"t":"Need for Speed Heat","p":["Windows","PlayStation 4","Xbox One"],"u":"Electronic Arts","g":"Racing","r":"November 8","l":"https://en.wikipedia.org/wiki/Need_for_Speed_Heat","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coar0x.jpg","s":"Hustle by day and risk it all at night in Need for Speed Heat, a white-knuckle street racer, where the lines of the law fade as the sun starts to set. By day, Palm City hosts the Speedhunter Showdown, a sanctioned competition where you earn Bank to customize and upgrade your high-performance cars. At night, ramp up the intensity in illicit street races that build your reputation, getting you access to bigger races and better parts. But stay ready – cops are waiting and not all of them play fair."},{"t":"Nelke & the Legendary Alchemists: Ateliers of the New World","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Koei Tecmo","g":"RPG","r":"March 26"},{"t":"Neo Cab","p":["Windows","macOS","Nintendo Switch","iOS","tvOS"],"d":"Chance Agency","u":"Fellow Traveller","g":"Visual novel","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Neo_Cab","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3ekh.jpg","s":"Neo Cab is an emotional survival game about staying human in a world disrupted by automation.\n\nYou play as Lina, the last human driver on the neon-drenched streets of Los Ojos. When your friend and only lifeline mysteriously vanishes, you'll need to use wits and empathy to survive. Choose your passengers— and your words— wisely. If you can balance your cash, star rating and emotional health, you might just keep your job long enough to find her."},{"t":"Never Give Up","p":["Windows","macOS","Linux","Nintendo Switch"],"d":"Massive Monster, Tasselfoot","u":"Armor Games","g":"Platform","r":"August 13, 2019","l":"https://en.wikipedia.org/wiki/Never_Give_Up_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocsva.jpg","s":"When the going gets tough, the tough don't quit! From the creators of the brutal and beloved Flash series enjoyed by millions of players worldwide comes the latest installment of hardcore, twitch-based platforming."},{"t":"Neverwinter Nights: Enhanced Edition","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Skybound Games","g":"RPG","r":"December 3"},{"t":"New Super Lucky's Tale","p":["Nintendo Switch"],"u":"Playful Corp.","g":"Platformer","r":"November 8","l":"https://en.wikipedia.org/wiki/New_Super_Lucky%27s_Tale"},{"t":"New Super Mario Bros. U Deluxe","p":["Nintendo Switch"],"u":"Nintendo","g":"Platformer","r":"January 11","l":"https://en.wikipedia.org/wiki/New_Super_Mario_Bros._U_Deluxe","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uhl.jpg","s":"Join Mario, Luigi, and pals for single-player or multiplayer fun anytime, anywhere! Take on two family-friendly, side-scrolling adventures with up to three friends* as you try to save the Mushroom Kingdom. Includes the New Super Mario Bros. U and harder, faster New Super Luigi U games—both of which include Nabbit and Toadette as playable characters!"},{"t":"NHL 20","p":["PlayStation 4","Xbox One"],"u":"EA Sports","g":"Sports","r":"September 13","l":"https://en.wikipedia.org/wiki/NHL_20"},{"t":"Ni no Kuni: Wrath of the White Witch","p":["Nintendo Switch"],"u":"Bandai Namco Entertainment","g":"RPG","r":"September 20"},{"t":"Ni no Kuni: Wrath of the White Witch Remastered","p":["Windows","PlayStation 4"],"u":"Bandai Namco Entertainment","g":"RPG","r":"September 20","l":"https://www.igdb.com/games/ni-no-kuni-wrath-of-the-white-witch-remastered","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob235.jpg","s":"Ni no Kuni: Wrath of the White Witch Remastered on PlayStation 4 and PC features brilliant new visual enhancements, letting PlayStation 4 players enjoy the game at 1080p resolution and with a super-smooth frame rate of 60 frames per second (fps). PlayStation 4 Pro users can also opt for true 4K resolution at 30 fps, or 1440p at 60fps.\n\nThe game retains its original dynamic fight system, combining real-time action and turn-based tactical elements, as well as the dozens of locations and hundreds of creatures that comprise the vast universe of Ni no Kuni.\n\nOriginally developed by LEVEL-5, Ni no Kuni: Wrath of the White Witch’s story unfolds through animation storyboarded and created by the legendary Studio Ghibli, with music composed by award-winning musician Joe Hisaishi. Ni no Kuni: Wrath of the White Witch tells the charming yet tragic story of Oliver, a young boy who embarks on a journey to another world in the hope of bringing back his mother following a tragic incident. With a copy of the Wizard’s Companion in hand and his pal Drippy by his side, Oliver must traverse exotic lands to tame familiars, take on malevolent foes, and overcome the countless challenges that stand between him and his mother’s salvation."},{"t":"Nier: Automata – Game of the Yorha Edition","p":["PlayStation 4"],"d":"PlatinumGames","u":"Square Enix","r":"February 26, 2019"},{"t":"Night Call","p":["macOS","Windows"],"d":"MonkeyMoon, Black Muffin","u":"Raw Fury","g":"Simulator, Adventure, Indie, Visual Novel","r":"July 17, 2019","l":"https://en.wikipedia.org/wiki/Night_Call_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qsr.jpg","s":"\"Night Call is a new kind of non linear narrative and noire game taking place in Paris, France.\n\nUsing the real city map (~105 km² or ~40.5 mi²) and the intimacy a taxi can offer, players will meet numerous and unique passengers to talk with. Some of them know things about the killer, others pretend to know things, and some just need to talk to someone.\n\nMore than just telling a story, Night Call also aims to show the city of Paris like it is in reality. A bit far from the usual cliché of the city of love. A gigantic city, always in movement, and full of very different people. Every one of them has a story to share. Put together, all these bits of stories will create a unique experience on the way to find the killer's identity.\""},{"t":"Ninja Tag Team: Slash n' Dash","p":["Android"],"d":"Gortyn Code","u":"Gortyn Code","g":"Endless runner","r":"May 12, 2019","l":"https://en.wikipedia.org/wiki/Ninja_Tag_Team:_Slash_n'_Dash"},{"t":"Nintendo Labo Toy-Con 04: VR Kit","p":["Nintendo Switch"],"u":"Nintendo","g":"— N/a","r":"April 12","l":"https://en.wikipedia.org/wiki/Nintendo_Labo"},{"t":"No Players Online","p":["Windows","Linux"],"d":"Adam Pype, Tibau Van den Broeck","g":"Indie game, short horror game","r":"November 2019","l":"https://en.wikipedia.org/wiki/No_Players_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2jyc.jpg","s":"A horror game taking place in the dead servers of a multiplayer first-person shooter."},{"t":"Nowhere Prophet","p":["Windows","macOS","Linux"],"d":"Sharkbomb Studios","u":"No More Robots","g":"Roguelike deck-building","r":"July 19, 2019","l":"https://en.wikipedia.org/wiki/Nowhere_Prophet","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2egp.jpg","s":"Prepare your decks and go on a pilgrimage through the wasteland! Nowhere Prophet is a unique single-player card game. Travel across randomly generated maps and lead your followers in deep tactical combat. Discover new cards and build your deck as you explore this strange, broken world."},{"t":"Observation","p":["Windows","PlayStation 4"],"u":"Devolver Digital","g":"Adventure, Puzzle","r":"May 21","l":"https://en.wikipedia.org/wiki/Observation_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26c0.jpg","s":"Observation is a sci-fi thriller uncovering what happened to Dr. Emma Fisher, and the crew of her mission, through the lens of the station’s artificial intelligence S.A.M."},{"t":"Oceanhorn 2: Knights of the Lost Realm","p":["iOS","macOS"],"d":"Cornfox & Bros.","u":"Cornfox & Bros., FDG Entertainment","g":"Action-adventure, action role-playing","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Oceanhorn_2:_Knights_of_the_Lost_Realm","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa67x.jpg","s":"Oceanhorn 2: Knights of the Lost Realm, set a thousand years before the events of the first chapter, takes the player on a magical journey across the vast world of Gaia, brimming with mythology and lore. A young Knight faces an impossible challenge, as Warlock Mesmeroth has returned with a formidable Dark Army. Will the hero be able to unite the Owrus, Gillfolk, and men in a fight for the fate of the world?"},{"t":"Octopath Traveler","p":["Windows"],"u":"Square Enix","g":"RPG","r":"June 7","l":"https://en.wikipedia.org/wiki/Octopath_Traveler"},{"t":"OhShape","p":["Windows","Meta Quest","PlayStation VR"],"d":"Odders Lab","u":"Odders Lab","g":"Rhythm","r":"December 13, 2019","l":"https://en.wikipedia.org/wiki/OhShape","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1t4q.jpg","s":"OhShape is a rhythm VR game where players have to move their full body to go through, punch or dodge walls following the beat of the music. It's an immersive game for all type of players inspired by the Japanese TV show Hole in the Wall."},{"t":"Olympic Games Tokyo 2020 - The Official Video Game","p":["Nintendo Switch","PlayStation 4"],"d":"Sega","u":"Sega","g":"Sports","r":"July 24, 2019","l":"https://en.wikipedia.org/wiki/Olympic_Games_Tokyo_2020_-_The_Official_Video_Game"},{"t":"Omega Labyrinth Life","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"D3Publisher","g":"RPG, Dungeon crawl","r":"August 1","l":"https://en.wikipedia.org/wiki/Omega_Labyrinth_Life"},{"t":"Omensight","p":["Xbox One"],"u":"Spearhead Games","g":"Action RPG","r":"June 7","l":"https://en.wikipedia.org/wiki/Omensight"},{"t":"One Night Stand","p":["PlayStation 4","Xbox One","Nintendo Switch"],"u":"Ratalaika Games","g":"Visual novel","r":"October 2","l":"https://en.wikipedia.org/wiki/One_Night_Stand_(video_game)"},{"t":"One Piece: World Seeker","p":["Windows","PlayStation 4","Xbox One"],"u":"Bandai Namco Entertainment","g":"Action-adventure","r":"March 15"},{"t":"Onimusha: Warlords","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Capcom","g":"Action-adventure, Hack and slash","r":"January 15","l":"https://www.igdb.com/games/onimusha-warlords--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4r13.jpg","s":"This enhanced HD version of Onimusha: Warlords now supports 16:9 wide screen resolution as well as the old 4:3 ratio. Improved controls now allow players to move and fight with analog-stick precision. The Japanese voices have been re-recorded for this remaster, and the brand new soundtrack promises to be even more spectacular than the original."},{"t":"Oninaki","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Square Enix","g":"RPG","r":"August 22","l":"https://en.wikipedia.org/wiki/Oninaki"},{"t":"Operencia: The Stolen Sun","p":["Windows","Xbox One"],"u":"Zen Studios","g":"RPG","r":"March 29"},{"t":"Orange County","p":["Windows"],"d":"Nicholas Brancaccio, Rachel Hwang, Nick Grayson","g":"Indie","r":"July 31, 2019","l":"https://en.wikipedia.org/wiki/Orange_County_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co939x.jpg","s":"The ever-circling specter of Elon’s children. The beige. Middle-class housing clustered like teeth in a robotic maw. The beige. The ever present hum of the sprinklers. The beige. Sometimes your skateboard feels like the only real thing in this place. With the help of your board, escape the horrors of procedurally-generated Orange County. Or try to. It’s only a matter of time."},{"t":"Ori and the Blind Forest","p":["Nintendo Switch"],"u":"Microsoft Studios","g":"Platformer","r":"September 27","l":"https://en.wikipedia.org/wiki/Ori_and_the_Blind_Forest"},{"t":"Ori and the Blind Forest: Definitive Edition","p":["Nintendo Switch"],"d":"Moon Studios","u":"Microsoft Studios","r":"September 27, 2019","l":"https://en.wikipedia.org/wiki/Ori_and_the_Blind_Forest"},{"t":"Outer Wilds","p":["Windows","Xbox One"],"u":"Annapurna Interactive","g":"Adventure","r":"May 30","l":"https://en.wikipedia.org/wiki/Outer_Wilds","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co65ac.jpg","s":"Outer Wilds is a critically-acclaimed and award-winning open world mystery about a solar system trapped in an endless time loop. The newest member of the space program in a small village on the planet Timber Hearth, the player navigates a space shuttle and travels across their solar system to get to the bottom of its mysteries by exploring the cosmos and gathering the knowledge hidden within each of the system's planets, left behind by another civilization in the distant past."},{"t":"Outlanders","p":["iOS","macOS","tvOS"],"d":"Pomelo Games","u":"Pomelo Games","g":"City-building","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Outlanders_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5r9d.jpg","s":"Outlanders is a charming town-builder simulation game that lets you play as the leader of a group of regular people building a town together. Some want to survive, while others want to build amazing things. It’s up to you to guide them towards their goal.\n\nTake control of the will of a town leader and balance your resources carefully to lead the town to prosperity. Every choice you make directly affects the progress of your town and has an impact on the happiness of your followers."},{"t":"Outward","p":["Windows","PlayStation 4","Xbox One"],"u":"Deep Silver","g":"Action RPG","r":"March 26","l":"https://en.wikipedia.org/wiki/Outward","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1iui.jpg","s":"Outward is an open world RPG that you play alone or with friends, either online or in splitscreen. It's more than just an open world RPG you can play coop though: it is an adventurer life simulator. You live the life of an adventurer, from his or her humble beginnings up until retirement. Your life isn't only about killing monsters and looting: you need to eat, drink and sleep; preparing accordingly before jumping into danger. Everything is meant to feel more real and consequential, while still taking place in a high fantasy universe with magic and exotic creatures."},{"t":"Overland","p":["iOS","Linux","macOS","Nintendo Switch","PlayStation 4","Windows","Xbox One"],"d":"Finji","u":"Finji","g":"Strategy","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Overland_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ru2.jpg","s":"Take care of a group of travelers on a post-apocalyptic road-trip across the United States in this turn-based survival game. Fight scary creatures, rescue stranded survivors, and scavenge for supplies like fuel, first aid kits, and weapons. Decide where to go next, whether it's upgrading this wrecked car, or rescuing that dog. Just remember, there are consequences for every action. Get ready for close calls, dramatic escapes, hard choices, arguing about whether or not that dog gets rescued, and the end of the world."},{"t":"Overload","p":["Xbox One"],"u":"Revival Productions","g":"FPS, Shoot 'em up","r":"March 6","l":"https://en.wikipedia.org/wiki/Overload_(video_game)"},{"t":"Overwatch: Legendary Edition","p":["Nintendo Switch"],"u":"Blizzard Entertainment","g":"FPS","r":"October 15","l":"https://en.wikipedia.org/wiki/Overwatch_(2016_video_game)"},{"t":"Oxygen Not Included","p":["Windows","macOS","Linux"],"u":"Klei Entertainment","g":"Survival, Simulation","r":"July 30","l":"https://en.wikipedia.org/wiki/Oxygen_Not_Included","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ugt.jpg","s":"Oxygen Not Included is a space-colony simulation game. Deep inside an alien space rock your industrious crew will need to master science, overcome strange new lifeforms, and harness incredible space tech to survive, and possibly, thrive."},{"t":"Pacify","p":["macOS","Windows"],"d":"Shawn Hitchcock, SKH Apps","u":"SKH Apps","g":"Simulator, Strategy, Adventure, Indie","r":"February 22, 2019","l":"https://www.igdb.com/games/pacify","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1j07.jpg","s":"An indie, multiplayer, horror game with fast paced game play for up to 4 players. Teams will need to explore an eerie mansion with a rumored past of funeral services including contacting deceased loved ones. A scary girl roams the house, and players need to keep her pacified to survive."},{"t":"Pagan: Autogeny","p":["Windows"],"d":"Oleander Garden","g":"Role-playing (RPG), Adventure, Indie","r":"August 14, 2019","l":"https://en.wikipedia.org/wiki/Pagan:_Autogeny","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co781t.jpg","s":"A thousand worlds surround our own, composed of bits and bytes. When they die, where do they go; what secrets do they hide? Stumble ye, wayfarer, through the wreckage of a dead MMO."},{"t":"Path of the Warrior","p":["Windows"],"u":"Oculus Studios","g":"Brawler","r":"December 12","l":"https://en.wikipedia.org/wiki/Path_of_the_Warrior_(video_game)"},{"t":"Pathway","p":["Linux","macOS","Windows","Nintendo Switch"],"d":"Robotality","u":"Chucklefish","g":"Tactical role-playing","r":"April 11, 2019","l":"https://en.wikipedia.org/wiki/Pathway_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qv1.jpg","s":"Adventure into the strange unknown with Pathway, a strategy RPG set in the 1930s great desert wilderness. Outwit your enemies in daring turn-based combat, raid occult tombs and make tough choices in a procedurally generated grand pulp expedition!"},{"t":"PC Building Simulator","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Claudiu Kiss, The Irregular Corporation","u":"The Irregular Corporation","g":"Business simulation","r":"January 29, 2019","l":"https://en.wikipedia.org/wiki/PC_Building_Simulator","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1p77.jpg","s":"PC Building Simulator lets players get to grips and experiment with building their very own gaming PC, without the associated risks and costs. With tutorials to help master the basics and an array of accurate and lifelike components that function exactly as they would in real life."},{"t":"Penguin Wars","p":["PlayStation 4"],"u":"Dispatch Games","g":"Action","r":"January 29","l":"https://en.wikipedia.org/wiki/Penguin_Wars"},{"t":"People Playground","p":["Windows"],"d":"mestiez","u":"Studio Minus","g":"Simulator, Indie","r":"July 23, 2019","l":"https://www.igdb.com/games/people-playground","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co47je.jpg","s":"Shoot, stab, burn, poison, tear, vaporise, or crush ragdolls in a large open space."},{"t":"Perchang","p":["Nintendo Switch"],"u":"Perchang Games","g":"Puzzle, Strategy","r":"June 4","l":"https://en.wikipedia.org/wiki/Perchang"},{"t":"Persona Q2: New Cinema Labyrinth","p":["Nintendo 3DS"],"u":"Atlus","g":"Dungeon crawl, RPG","r":"June 4"},{"t":"Phoenix Point","p":["Windows","macOS"],"u":"Snapshot Games","g":"Strategy, TBT","r":"December 3","l":"https://en.wikipedia.org/wiki/Phoenix_Point"},{"t":"Phoenix Wright: Ace Attorney Trilogy","p":["Nintendo Switch","PlayStation 4","Xbox One","Windows"],"u":"Capcom","g":"Adventure, Visual novel","r":"February 21"},{"t":"Photographs","p":["Windows","macOS","Linux","iOS","Android"],"d":"EightyEightGames","u":"EightyEightGames","g":"Puzzle game","r":"April 3, 2019","l":"https://en.wikipedia.org/wiki/Photographs_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1jr6.jpg","s":"\"Photograph's big secret is that it's not a puzzle game. It's five puzzle games. \nThe game is divided into five distinct stories, set in five different times and locations, A player will learn how to solve progressively difficult puzzles in one story, and then move to the next story which has completely different gameplay. \n \nThat's important because Photograph's other big secret is that it's not a puzzle game, it's a narrative game. The dioramas, the photographs, the sound, the voices, and the puzzles, come together to create a cohesive narrative experience that tells that specific story. \n \nMaybe.\""},{"t":"Pico Park","p":["Windows","Nintendo Switch"],"d":"TECOPARK","g":"Action, Casual, Indie","r":"June 8, 2019","l":"https://en.wikipedia.org/wiki/Pico_Park","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8yks.jpg","s":"Pico Park is a cooperative local/online multiplay action puzzle game for 2-8 players.\nThe rule is quite simple: \"Get all the keys and get to the goal and clear\", but all 48 levels have special gimmicks designed specifically for multiplayer. At most levels, different gimmicks will appear as you move forward, and you will need to consult with your peers and think about new ways to cooperate."},{"t":"Picross S 3","p":["Nintendo Switch"],"u":"Jupiter Corporation","g":"Puzzle","r":"April 25","l":"https://en.wikipedia.org/wiki/Picross_S"},{"t":"Piczle Colors","p":["Nintendo Switch"],"u":"Rainy Frog","g":"Puzzle","r":"January 31"},{"t":"Pikuniku","p":["Windows","Nintendo Switch"],"u":"Devolver Digital","g":"Puzzle-platformer","r":"January 24","l":"https://en.wikipedia.org/wiki/Pikuniku","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa9g1.jpg","s":"Pikuniku is a puzzle and adventure game set in a colorful world. The player controls Piku, a small red creature, guiding him through levels and solving puzzles that mostly involve kicking and pushing objects onto switches to open the way forward. Piku can lasso his legs to swing from hooks and zip lines, curl into a ball to roll, ride minecarts, and travel through pipes to reach new areas. Along the way the player meets villagers to talk with and can spend coins earned in levels on items such as hats. A local co-op mode lets a second player control a similar orange creature named Niku across a set of cooperative levels."},{"t":"Pilgrims","p":["Windows","iOS","Linux","macOS"],"d":"Amanita Design","u":"Amanita Design","g":"Graphic adventure","r":"October 6, 2019","l":"https://en.wikipedia.org/wiki/Pilgrims_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26cn.jpg","s":"Roam the land as you please and make new friends, share a laugh with your fellow travellers and help them complete their little stories, your way. How many different solutions can you find?\n\nIt is most enjoyable if you’re into:\n\n- Playfulness: Don’t beat it - play with it! Solve the various tasks using dozens of items and unique characters without being obliged to follow a single designated path.\n\n- Replayability: Packed with 45 achievements, Pilgrims is a game designed to be played through more than just once. Can you collect them all?\n\n- Hand-crafted appeal: Hundreds of unique animations and custom made sound effects result in countless humorous and unexpected outcomes. Try to discover as many as you can!\n\n- Original music: Floex (Machinarium, Samorost 3) is back at it with his mix of live instruments and organic electronics, joined by guests on guitar or clarinet."},{"t":"Pillars of Eternity: Complete Edition","p":["Nintendo Switch"],"u":"Versus Evil","g":"RPG","r":"August 8","l":"https://en.wikipedia.org/wiki/Pillars_of_Eternity"},{"t":"Pilotwings","p":["Nintendo Switch"],"g":"Vehicle sim (plane)","r":"September 5","l":"https://en.wikipedia.org/wiki/Pilotwings_(video_game)"},{"t":"Pine","p":["Linux","macOS","Windows","Nintendo Switch"],"d":"Twirlbound","u":"Kongregate","g":"Action-Adventure, Open world","r":"October 10, 2019","l":"https://en.wikipedia.org/wiki/Pine_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1i9s.jpg","s":"Pine is an open-world action adventure simulation game. Players are dropped in an ever-evolving world in which AI organisms have lives, goals and quests of their own. Species trade and fight with each other, while the player learns about ways to influence the simulation and shape their story through the different biomes of Albamare. Take the role of Hue, a scared but brave adolescent belonging to one of the last remaining human tribes on the island of Albamare, fighting for the survival of their species. Find your way to a new home to thrive and survive as a species."},{"t":"Pistol Whip","p":["Meta Quest","Windows","PlayStation 4"],"d":"Cloudhead Games","g":"First-person shooter, Rhythm game","r":"November 7, 2019","l":"https://en.wikipedia.org/wiki/Pistol_Whip","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coa0pc.jpg","s":"Pistol Whip is a physical action-rhythm game where film-inspired gunplay and blood-pumping beats collide. Blast, duck and dodge your way through fever dream Scenes, build unique rhythms in a ballet of bullets and claim glory on the leaderboards."},{"t":"PixARK","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Snail Games","g":"Sandbox","r":"May 31","l":"https://en.wikipedia.org/wiki/PixARK"},{"t":"Planescape: Torment: Enhanced Edition","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Skybound Games","g":"RPG","r":"September 24"},{"t":"Planet Nomads","p":["Windows","macOS","Linux"],"d":"Craneballs Studio","g":"Sandbox","r":"May 3, 2019","l":"https://en.wikipedia.org/wiki/Planet_Nomads","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2qys.jpg","s":"A sandbox game of creation and survival.\n\nAfter crash landing on an unexplored planet you are left with nothing but a few tools and your imagination. Make yourself a shelter, secure food and water and start building towards making a spaceship capable of interplanetary travels.\n\nPlanet Nomads is a true sandbox game with procedurally generated planets, total creative freedom to build all kinds of things big or small (100+ building blocks already), and planets ranging from desolate wastelands to delicate forest environments and rocky plains.\n\nYou can try the building part demo of the game already. Download the Editor for free from the game's official website."},{"t":"Planet Zoo","p":["Windows"],"u":"Frontier Developments","g":"CMS","r":"November 5","l":"https://en.wikipedia.org/wiki/Planet_Zoo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8zii.jpg","s":"Build a world for wildlife in Planet Zoo. From the creators of Planet Coaster and Zoo Tycoon comes the ultimate zoo sim. Construct detailed habitats, manage your zoo, and meet authentic living animals who think, feel and explore the world you create around them."},{"t":"Planet Zoo: Arctic Pack","p":["Windows","PlayStation 5","Xbox Series X/S"],"d":"Frontier Developments","u":"Frontier Developments","g":"Construction and management simulation","r":"December 17, 2019","l":"https://en.wikipedia.org/wiki/Planet_Zoo:_Arctic_Pack"},{"t":"Planetarian: The Reverie of a Little Planet","p":["Nintendo Switch"],"u":"Prototype","g":"Visual novel","r":"January 31"},{"t":"PlanetSide Arena","p":["Windows"],"d":"Daybreak Game Company","u":"Daybreak Game Company","g":"Massively multiplayer online first-person shooter","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/PlanetSide_Arena"},{"t":"Plants vs Zombies: Battle for Neighborville","p":["Windows","PlayStation 4","Xbox One"],"u":"Electronic Arts","g":"TPS","r":"October 18","l":"https://www.igdb.com/games/plants-vs-zombies-battle-for-neighborville","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3isd.jpg","s":"Similar to its predecessors, the game is a third-person shooter where players take control of the Plants or the Zombies in either a cooperative or competitive multiplayer environment. The game features 20 customizable gameplay classes, six of which are new to the franchise, and they are classified into three groups: attackers, defenders, or support. Each camp also has a new team play class that allows players of the same class to combine forms when they fight against enemies. Players can compete against each other in various competitive multiplayer modes, including the objective-based Turf War mode and the team deathmatch variant Team Vanquish. The game also features several player-versus-environment open zones which allowed players to explore, find collectibles, and complete quests. Split-screen local multiplayer is also available for all gameplay mode"},{"t":"Pokémon Masters","p":["iOS","Android"],"u":"DeNA","g":"RPG","r":"August 28","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Masters"},{"t":"Pokémon Masters EX","p":["Android","iOS"],"d":"DeNA","u":"DeNA","g":"Role-playing","r":"August 29, 2019","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Masters_EX","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30by.jpg","s":"Pokémon Masters EX (originally named Pokémon Masters) is a free-to-play mobile game for Android and iOS developed and published by DeNA. It is based on the Pokémon media franchise. Set on the artificial island of Pasio, the game allows players to battle and recruit various prominent Pokémon Trainers from the main series games. Originally named Pokémon Masters and released in August 2019, it was renamed Pokémon Masters EX in August 2020 on the 1st anniversary of the game."},{"t":"Pokémon Rumble Rush","p":["Android","iOS"],"u":"The Pokémon Company","g":"Action","r":"May 22","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Rumble_Rush"},{"t":"Pokémon Shield","p":["Nintendo Switch"],"d":"Game Freak","u":"The Pokémon Company, Nintendo","g":"Role-playing (RPG), Turn-based strategy (TBS), Adventure","r":"November 15, 2019","l":"https://www.igdb.com/games/pokemon-shield","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zk1.jpg","s":"Pokémon Shield is a role-playing game set in the Galar region, a fictional land inspired by the United Kingdom. Players control a young Pokémon Trainer who catches and trains creatures called Pokémon, battling other trainers in turn-based combat. The game introduces the Dynamax and Gigantamax mechanics, which temporarily transform Pokémon into giant forms with enhanced abilities. Progression follows the traditional Gym Challenge structure, requiring players to defeat eight Gym Leaders before competing for the League Championship. The game features an open Wild Area with free-roaming Pokémon, cooperative raid battles for up to four players, and camping activities. Pokémon Shield is the companion title to Pokémon Sword, with certain Pokémon and Gym Leaders exclusive to each version."},{"t":"Pokémon Sword","p":["Nintendo Switch"],"d":"Game Freak","u":"Nintendo","g":"Role-playing (RPG), Turn-based strategy (TBS), Adventure","r":"November 15, 2019","l":"https://www.igdb.com/games/pokemon-sword","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zk2.jpg","s":"A turn-based role-playing game set in the Galar region, a fictional land inspired by the United Kingdom. Players catch, train, and battle creatures called Pokémon while traveling across the region to collect eight Gym badges and ultimately challenge the reigning Champion. The game introduces the Dynamax and Gigantamax mechanics, which temporarily transform Pokémon into giant forms with enhanced attacks. A fully explorable open-world Wild Area connects major locations, with weather-dependent Pokémon encounters and cooperative raid battles for up to four players. The first mainline Pokémon entry on the Nintendo Switch, it notably adopted DLC expansions instead of the series' traditional enhanced re-releases."},{"t":"Pokémon Sword and Shield","p":["Nintendo Switch"],"u":"The Pokémon Company , Nintendo","g":"RPG","r":"November 15","l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Sword_and_Shield"},{"t":"Pokémon Trading Card Game Card Dex","p":[],"l":"https://en.wikipedia.org/wiki/Pok%C3%A9mon_Trading_Card_Game_Card_Dex"},{"t":"Police Stories","p":["Linux","macOS","Nintendo Switch","Windows"],"d":"Mighty Morgan","u":"HypeTrain Digital","g":"Top-down shooter","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Police_Stories","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mhm.jpg","s":"Police Stories is a novelty top-down shooter, where advanced AI of enemies, tactical elements and random occurrences create thousands of unique situations in each level. Never before the pixel game was this realistic and fun."},{"t":"Power Rangers: Battle for the Grid","p":["Nintendo Switch","Xbox One","PlayStation 4"],"u":"nWay Games","g":"Fighting","r":"March 26"},{"t":"Pretty Princess Party","p":["Nintendo Switch"],"d":"Nippon Columbia","u":"Nippon Columbia, Aksys Games","g":"Simulation","r":"December 5, 2019","l":"https://en.wikipedia.org/wiki/Pretty_Princess_Party","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6oyi.jpg","s":"Become a Princess of a Magical Castle! Pretty Princess Party on the Nintendo Switch transports you to a magical land to explore a long-abandoned enchanted castle. Learn to be a princess and decorate the castle any way you wish.\n\nBegin by creating a princess character with endless choices of dresses, shoes, accessories, and hairstyles. Then train to be a princess by playing fun mini-games, including cake decorating, horse racing, and dancing. Restore the castle to its former glory and win the prize! Even after completing the entire magical story, you can take on new challenge objectives to update rooms and photographs."},{"t":"Project Lux","p":["PlayStation 4"],"u":"Sekai Project","g":"Adventure","r":"June 20"},{"t":"Project Torque","p":["Windows"],"d":"Invictus Games","u":"Aeria Games & Entertainment, Jogara Ltd.","g":"Racing MMO","r":"December 20, 2019","l":"https://en.wikipedia.org/wiki/Project_Torque"},{"t":"Project Winter","p":["Windows"],"d":"Other Ocean Interactive","u":"Other Ocean Interactive, Boltrend Games","g":"Social deduction, survival","r":"May 23, 2019","l":"https://en.wikipedia.org/wiki/Project_Winter","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2t2u.jpg","s":"Project Winter is an 8 person multiplayer game focusing on social deception and survival. The survivors goal is to work together, gather resources and escape. Unbeknownst to them, traitors are within the group whose only goal is to stop them by any means necessary."},{"t":"Projection: First Light","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch","iOS"],"d":"Shadowplay Studios","u":"Blowfish Studios","g":"Puzzle, platform","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Projection:_First_Light","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1wpm.jpg","s":"Projection: First Light follows Greta on a puzzle-platforming adventure through a mythological shadow puppet world, as she embarks on a journey across cultures meeting legendary heroes."},{"t":"Promise of Wizard","p":["Android","iOS"],"g":"Role-playing (RPG), Simulator","l":"https://en.wikipedia.org/wiki/Promise_of_Wizard","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6o6j.jpg","s":"Promise of Wizard or most widely known as Mahoyaku, is a mobile, otome-styled game with no romance created by Coly. In this game, players are tasked to train the wizards from the different countries in order to defend the world from the mysterious chaos brought by the moon. This game was officially released on November 26th, 2019."},{"t":"Psychedelica of the Ashen Hawk","p":["Windows"],"u":"Intragames, Idea Factory","g":"Visual novel","r":"August 30","l":"https://en.wikipedia.org/wiki/Psychedelica_of_the_Ashen_Hawk"},{"t":"Psyvariar Delta","p":["Nintendo Switch","PlayStation 4"],"u":"Dispatch Games","g":"Shoot 'em up","r":"July 2","l":"https://en.wikipedia.org/wiki/Psyvariar_Delta"},{"t":"Punch-Out!!","p":["Nintendo Switch"],"g":"Sports (boxing)","r":"April 10","l":"https://en.wikipedia.org/wiki/Punch-Out!!_(1987_video_game)"},{"t":"Punishing: Gray Raven","p":["iOS","Android"],"u":"Kuro Games","g":"Action RPG, Hack and slash","r":"December 5"},{"t":"Puyo Puyo Champions","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Sega","g":"Puzzle","r":"May 7","l":"https://en.wikipedia.org/wiki/Puyo_Puyo_Champions"},{"t":"Queen's Wish: The Conqueror","p":["Windows","macOS","iOS"],"d":"Spiderweb Software","g":"Role-playing","r":"September 11, 2019","l":"https://en.wikipedia.org/wiki/Queen's_Wish:_The_Conqueror","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q50.jpg","s":"At last, the Queen has given you power and freedom! The cost? You must rebuild her Empire. Will you? In this epic, indie fantasy adventure, you are free to explore, fight for fame and power, and shape the world as you choose. Escape into an unpredictable open-ended story and cunning tactical combat."},{"t":"R.B.I. Baseball 19","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"MLB Advanced Media","g":"Sports","r":"March 5","l":"https://en.wikipedia.org/wiki/R.B.I._Baseball_19"},{"t":"Rad","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Bandai Namco Entertainment","g":"Roguelike","r":"August 20","l":"https://en.wikipedia.org/wiki/Rad_(video_game)"},{"t":"Rage 2","p":["Windows","PlayStation 4","Xbox One","Stadia"],"u":"Bethesda Softworks","g":"FPS","r":"May 14","l":"https://en.wikipedia.org/wiki/Rage_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rbm.jpg","s":"Dive headfirst into a dystopian world devoid of society, law, and order. Rage 2 brings together a true open world FPS experience where you can go anywhere, shoot anything, and explode everything."},{"t":"Raging Loop","p":["Nintendo Switch","PlayStation 4","Windows"],"u":"PQube","g":"Visual novel","r":"October 22","l":"https://en.wikipedia.org/wiki/Raging_Loop"},{"t":"Raiden V: Director's Cut","p":["Nintendo Switch"],"u":"UFO Interactive Games","g":"Shoot 'em up","r":"July 25","l":"https://en.wikipedia.org/wiki/Raiden_V"},{"t":"Rayman Mini","p":["iOS","macOS","tvOS"],"d":"Ubisoft Montpellier, Pastagames","u":"Ubisoft","g":"Platform","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Rayman_Mini","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ctf.jpg","s":"Developed by Ubisoft Montpellier and Pastagames, Rayman Mini follows Rayman on a legendary journey as he has been reduced to the size of ant! To undo this spell, Rayman will travel through a macro-photographic world, encountering friendly allies and defeating epic bosses along the way."},{"t":"ReadySet Heroes","p":["Windows","PlayStation 4"],"u":"Sony Interactive Entertainment","g":"Action","r":"October 1"},{"t":"Rebel Cops","p":["Nintendo Switch","PlayStation 4","Windows","Xbox One"],"d":"Weappy Studio","u":"THQ Nordic","g":"Turn-based tactics","r":"September 17, 2019","l":"https://en.wikipedia.org/wiki/Rebel_Cops","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24cd.jpg","s":"Rebel Cops is a spin-off game from This Is the Police, which exclusively features the series' turned-based tactical operations. Lead a rag-tag squad of cops in rebellion against their town's new criminal power, and see how long you can hold out when you're constantly short on supplies, and a single shot can cost a cop his life."},{"t":"Rebel Galaxy Outlaw","p":["Windows"],"u":"Double Damage Games","g":"Vehicle sim (spaceship)","r":"August 13","l":"https://en.wikipedia.org/wiki/Rebel_Galaxy_Outlaw"},{"t":"Red Dead Online","p":["PlayStation 4","Xbox One","Windows","Stadia"],"d":"Rockstar Games","u":"Rockstar Games","g":"Action-adventure","r":"May 14, 2019","l":"https://en.wikipedia.org/wiki/Red_Dead_Online","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2l9j.jpg","s":"Step into the vibrant, ever-evolving world of Red Dead Online and experience life in frontier America. Chase down bounties, battle outlaw gangs and other players, hunt, fish and trade, search for exotic treasures, run Moonshine, and much more to discover in a world of astounding depth and detail."},{"t":"Red Dead Redemption 2","p":["Windows","Stadia"],"d":"Rockstar Games","u":"Rockstar Games","g":"Action-adventure","r":"November 5, 2019","l":"https://en.wikipedia.org/wiki/Red_Dead_Redemption_2","i":"images/steam-1174180.jpg","s":"Arthur Morgan and the Van der Linde Gang are outlaws on the run. With federal agents and bounty hunters massing on their heels, the gang must rob, steal, and fight their way across the rugged heartland in order to survive."},{"t":"Red Faction: Guerrilla Re-Mars-tered","p":["Nintendo Switch"],"u":"THQ Nordic","g":"TPS, Action-adventure","r":"July 2"},{"t":"Redout","p":["Nintendo Switch"],"u":"Nicalis","g":"Racing","r":"May 14","l":"https://en.wikipedia.org/wiki/Redout_(video_game)"},{"t":"Reel Fishing: Road Trip Adventure","p":["Nintendo Switch","PlayStation 4"],"u":"Natsume Inc.","g":"Fishing","r":"September 17"},{"t":"Remnant: From the Ashes","p":["Windows","PlayStation 4","Xbox One"],"u":"Perfect World Entertainment","g":"TPS, Action-adventure","r":"August 20","l":"https://www.igdb.com/games/remnant-from-the-ashes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coct8j.jpg","s":"The world is in ruins. Only a remnant of mankind remains, hunted to near extinction by horrors from another world. As one of the few survivors left, you will venture into portals to fantastic realms to gather the resources and firepower needed to fight back and retake what was lost.\n\nRemnant: From the Ashes is a third-person survival-action game set in a post-apocalyptic world overrun by mythical creatures. The game provides players and up to three of their friends with a unique, customizable gameplay experience filled with intense shooting and melee combat, gear and weapon crafting, character progression and dynamically-generated levels that offer an infinite number of ways to explore and take on deadly monsters and epic bosses."},{"t":"Resident Evil","p":["Nintendo Switch"],"u":"Capcom","g":"Survival horror","r":"May 21","l":"https://en.wikipedia.org/wiki/Resident_Evil_(2002_video_game)"},{"t":"Resident Evil 2","p":["Xbox One","PlayStation 4","Windows"],"d":"Capcom","u":"Capcom","g":"Survival horror","r":"January 25, 2019","l":"https://en.wikipedia.org/wiki/Resident_Evil_2_(2019_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ir3.jpg","s":"Resident Evil 2 is a remake of 1998's Resident Evil 2. The game was not developed with the intent of improving the original, but rather a reimagining of the original story with redesigned maps, characters and story elements. Gameplay mechanics are more similar to Resident Evil 7: Biohazard though with the use of an over-the-shoulder camera."},{"t":"Resident Evil 4","p":["Nintendo Switch"],"u":"Capcom","g":"Survival horror, TPS","r":"May 21","l":"https://en.wikipedia.org/wiki/Resident_Evil_4"},{"t":"Resident Evil 5","p":["Nintendo Switch"],"u":"Capcom","g":"Survival horror, TPS","r":"October 29","l":"https://en.wikipedia.org/wiki/Resident_Evil_5"},{"t":"Resident Evil 6","p":["Nintendo Switch"],"u":"Capcom","g":"Survival horror, TPS","r":"October 29","l":"https://en.wikipedia.org/wiki/Resident_Evil_6"},{"t":"Resident Evil Zero","p":["Nintendo Switch"],"u":"Capcom","g":"Survival horror","r":"May 21","l":"https://en.wikipedia.org/wiki/Resident_Evil_Zero"},{"t":"Retro Mystery Club Vol.1: The Ise-Shima Case","p":["Nintendo Switch"],"g":"Adventure","r":"January 24"},{"t":"Return of the Obra Dinn","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"3909","g":"Puzzle","r":"October 18","l":"https://en.wikipedia.org/wiki/Return_of_the_Obra_Dinn"},{"t":"Reventure","p":["Windows","Nintendo Switch","iOS"],"d":"Pixelatto","u":"Pixelatto","g":"Action-adventure game","r":"June 6, 2019","l":"https://en.wikipedia.org/wiki/Reventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2e1x.jpg","s":"Reventure could be described as a \"choose your own adventure\" book in the shape of a 2D platformer.\n\nIt starts out from the classic monomyth premise: \"You are a hero, the princess is in danger, go rescue her!\" but it quickly gets more complicated than that - until it completely diverges into something completely non-standard."},{"t":"Ring Fit Adventure","p":["Nintendo Switch"],"u":"Nintendo","g":"Adventure, Fitness","r":"October 18","l":"https://en.wikipedia.org/wiki/Ring_Fit_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobcnq.jpg","s":"In this fitness-focused title, you'll be moving the ring and a leg strap -- both of which house a Switch Joy-Con -- to move your character through a fantasy world.\n\nAt certain intervals, you'll be thrown into battles. These so-called \"fit battles\" play out like a traditional turn-based RPG. All of your attacks are triggered by completing a specific pose or stretch, with four attack types that target different parts of your body\n\nThe world will be broken up into courses that, upon completion, reward you with experience points. Levelling up will increase your character's base stats and slowly unlock new skills that can be utilised in battle."},{"t":"RIOT: Civil Unrest","p":["Windows"],"u":"Leonard Menchiari","g":"RTS","r":"February 12"},{"t":"Rise of Industry","p":["Windows","macOS","Linux"],"u":"Kasedo Games","g":"Business sim","r":"May 2","l":"https://en.wikipedia.org/wiki/Rise_of_Industry"},{"t":"Rise of the Tomb Raider","p":["Stadia"],"u":"Square Enix","g":"Action-adventure","r":"November 19","l":"https://en.wikipedia.org/wiki/Rise_of_the_Tomb_Raider"},{"t":"Rise to Ruins","p":["Windows","macOS","Linux"],"d":"Raymond Doerr","u":"SixtyGig Games","g":"City-building, strategy","r":"October 14, 2019","l":"https://en.wikipedia.org/wiki/Rise_to_Ruins"},{"t":"River City Girls","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Arc System Works","g":"Brawler","r":"September 5","l":"https://en.wikipedia.org/wiki/River_City_Girls","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cob20p.jpg","s":"River City Girls stars Kyoko and Misako, two street-tough high-schoolers who must fight their way through the six regions of River City to rescue their kidnapped boyfriends, series mainstays Kunio and Riki. Along the way, they'll utilize an arsenal of combos, counters, throws, and special attacks; battle an assortment of enemies; accept numerous side quests; level up with experience points; interact with NPCs (including guest stars from past River City games); and shop for a variety of items, food, and gear to boost stats and unlock new abilities. The girls can even wield weapons and recruit defeated foes to join them in combat!"},{"t":"River City Melee Mach!!","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Arc System Works","g":"Action","r":"October 10","l":"https://en.wikipedia.org/wiki/River_City_Melee_Mach!!"},{"t":"Robotics;Notes DaSH","p":["Nintendo Switch","PlayStation 4"],"u":"Spike Chunsoft","g":"Visual novel","r":"January 31","l":"https://en.wikipedia.org/wiki/Robotics;Notes_DaSH"},{"t":"Robotics;Notes Elite HD","p":["Nintendo Switch","PlayStation 4"],"u":"Spike Chunsoft","g":"Visual novel","r":"January 31","l":"https://en.wikipedia.org/wiki/Robotics;Notes_Elite_HD"},{"t":"Romancing SaGa 3","p":["Windows","Nintendo Switch","PlayStation 4","PlayStation Vita","Xbox One","iOS","Android"],"u":"Square Enix","g":"RPG","r":"November 11","l":"https://en.wikipedia.org/wiki/Romancing_SaGa_3"},{"t":"Root Letter: Last Answer","p":["Nintendo Switch","PlayStation 4"],"u":"PQube","g":"Visual novel","r":"September 3","l":"https://en.wikipedia.org/wiki/Root_Letter"},{"t":"Route-16 Turbo","p":["Nintendo Switch"],"g":"Maze, Racing","r":"December 12","l":"https://en.wikipedia.org/wiki/Route-16"},{"t":"SaGa: Scarlet Grace – Ambitions","p":["Windows","Nintendo Switch","PlayStation 4","iOS","Android"],"u":"Square Enix","g":"RPG","r":"December 3"},{"t":"Saints Row: The Third – The Full Package","p":["Nintendo Switch"],"u":"Deep Silver","g":"Action-adventure, TPS","r":"May 10"},{"t":"Sakura Wars","p":["PlayStation 4"],"u":"Sega","g":"Action RPG, Dating sim , Visual novel","r":"December 12","l":"https://en.wikipedia.org/wiki/Sakura_Wars_(2019_video_game)"},{"t":"Samurai Shodown","p":["PlayStation 4","Xbox One"],"u":"Athlon Games","g":"Fighting","r":"June 25","l":"https://en.wikipedia.org/wiki/Samurai_Shodown_(2019_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m9a.jpg","s":"\"A brand new title from SNK! A new Samurai Shodown is on the horizon!\n\nSince its birth in 1993, the Samurai Shodown series has been known as the premier weapon based versus fighting games, and was essential in cultivating the weapon based fighting game genre. As the first new release in the series in more than 10 years, Samurai Shodown is aiming to yet again push boundaries and deliver some serious samurai action!\n\nDeveloped using Unreal Engine 4 and utilizing a unique brushstroke graphical style to match the Japanese roots of the series, Haohmaru, Nakoruru, Galford and a whole cast of other popular characters will battle once again for victory!\""},{"t":"Samurai Warriors 4 DX","p":["Nintendo Switch","PlayStation 4"],"u":"Koei Tecmo","g":"Hack and slash","r":"March 14","l":"https://en.wikipedia.org/wiki/Samurai_Warriors_4"},{"t":"Sayonara Wild Hearts","p":["Nintendo Switch","PlayStation 4"],"u":"Annapurna Interactive","g":"Music","r":"September 19","l":"https://en.wikipedia.org/wiki/Sayonara_Wild_Hearts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gx1.jpg","s":"Sayonara Wild Hearts is a euphoric music video dream about being awesome, riding motorcycles, skateboarding, dance battling, shooting lasers, wielding swords, and breaking hearts at 200 mph."},{"t":"SD Gundam G Generation Cross Rays","p":["Windows"],"u":"Bandai Namco Entertainment","g":"Tactical RPG","r":"November 27","l":"https://en.wikipedia.org/wiki/SD_Gundam_G_Generation_Cross_Rays"},{"t":"Sea of Solitude","p":["Windows","PlayStation 4","Xbox One"],"u":"Electronic Arts","g":"Adventure","r":"July 5","l":"https://en.wikipedia.org/wiki/Sea_of_Solitude","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1m4m.jpg","s":"When humans get too lonely, they turn into monsters…\n\nSea of Solitude takes you on a personal journey of a young woman’s loneliness. Set sail across a beautiful and evolving world where nothing is quite what it seems. Meet fantastical creatures and monsters, learn their stories, and solve challenges. Explore a flooded city by boat, on foot, or by swimming through the water itself. Dare to look what lies beneath the surface, in a haunting struggle of darkness and light, and discover what it truly means to be human."},{"t":"Sekiro: Shadows Die Twice","p":["Xbox One","PlayStation 4","Windows"],"d":"FromSoftware","u":"Activision","g":"Action-adventure","r":"March 22, 2019","l":"https://www.igdb.com/games/sekiro-shadows-die-twice","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2a23.jpg","s":"Sekiro: Shadows Die Twice is an action-adventure game set in a reimagined late 1500s Sengoku-era Japan.\n\nPlayers control Wolf, a shinobi on a mission to rescue his kidnapped lord and seek revenge on his enemies. The game emphasizes precise sword combat, stealth, and mobility, replacing traditional RPG elements with a posture-based dueling system."},{"t":"Senran Kagura Burst Re:Newal","p":["Windows","PlayStation 4"],"u":"Xseed Games","g":"Action","r":"January 22"},{"t":"Senran Kagura: Peach Ball","p":["Nintendo Switch"],"u":"Xseed Games","g":"Pinball","r":"July 9"},{"t":"Sephirothic Stories","p":["Xbox One"],"u":"Kemco","g":"RPG, Puzzle","r":"March 15","l":"https://en.wikipedia.org/wiki/Sephirothic_Stories"},{"t":"Shachibato! President, It's Time for Battle!","p":[],"l":"https://en.wikipedia.org/wiki/Shachibato!_President,_It's_Time_for_Battle!"},{"t":"Shadow of the Tomb Raider","p":["Stadia"],"u":"Square Enix","g":"Action-adventure","r":"November 19","l":"https://en.wikipedia.org/wiki/Shadow_of_the_Tomb_Raider"},{"t":"Shakedown: Hawaii","p":["Windows","Nintendo Switch","PlayStation 4","PlayStation Vita","Nintendo 3DS"],"u":"Vblank Entertainment","g":"Action-adventure","r":"May 7"},{"t":"Shantae and the Seven Sirens","p":["iOS","macOS"],"u":"WayForward","g":"Platformer","r":"September 19","l":"https://en.wikipedia.org/wiki/Shantae_and_the_Seven_Sirens"},{"t":"She Sees Red","p":["macOS","Windows"],"d":"Rhinotales","u":"Rhinotales","g":"Interactive thriller","r":"July 11, 2019","l":"https://en.wikipedia.org/wiki/She_Sees_Red","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co233q.jpg","s":"She Sees Red is an interactive live-action thriller full of drama, violence, and your responsibility. A detective is doing her best to catch an elusive criminal who murdered several people in a night club. Make different choices to affect the plot line and reveal all pieces of the puzzle."},{"t":"ShellShock Live","p":["Xbox One","PlayStation 4"],"d":"kChamp Games","u":"kChamp Games","g":"Shooter, Strategy, Turn-based strategy (TBS), Indie","r":"March 7, 2019","l":"https://www.igdb.com/games/shellshock-live","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1u4u.jpg","s":"ShellShock Live is a strategic online multiplayer artillery game currently in active development by kChamp Games.Fight Alongside your Friends (Or blow them up... we won't judge!) Take part in action-packed 8-Player team and free-for all battles. Tactical gameplay is essential to victory, while numerous distinct tanks, weapons, items, maps, and play styles make every match unique."},{"t":"Shenmue III","p":["Windows","PlayStation 4"],"u":"Deep Silver","g":"Action-adventure","r":"November 19","l":"https://en.wikipedia.org/wiki/Shenmue_III","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ftj.jpg","s":"Shenmue III is an action-adventure video game and the sequel to the 2001 game Shenmue II. It follows teenage martial artist Ryo Hazuki in his quest to find his father's killer in 1980s China. In 2015, Suzuki launched a Kickstarter crowdfunding campaign to help fund Shenmue III and the campaign met its initial target of $2 million USD in under eight hours. The campaign ended in July having raised over $6 million, becoming the most funded video game in Kickstarter history."},{"t":"Shovel Knight: King of Cards","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Yacht Club Games","g":"Platformer","r":"December 10","l":"https://en.wikipedia.org/wiki/Shovel_Knight"},{"t":"Shovel Knight: Showdown","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Yacht Club Games","g":"Fighting","r":"December 10","l":"https://en.wikipedia.org/wiki/Shovel_Knight"},{"t":"Siege of Centauri","p":["Windows"],"d":"Stardock Entertainment","u":"Stardock Entertainment","g":"Tower defense","r":"September 12, 2019","l":"https://en.wikipedia.org/wiki/Siege_of_Centauri","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ko8.jpg","s":"Thousands of alien machines are descending on Earth's first interstellar colony in this massive-scale new tower defense game from the publisher of Ashes of the Singularity and Sins of a Solar Empire: Rebellion."},{"t":"Sigil","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One","Android","iOS"],"u":"Romero Games, Bethesda Softworks","g":"First-person shooter","r":"May 31, 2019","l":"https://en.wikipedia.org/wiki/Sigil_(video_game_mod)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3gyo.jpg","s":"The Sigil Megawad is free download created by John Romero for the original 1993 Doom. It contains nine single-player and nine deathmatch levels. The free megawad will be released in mid- May 2019 and requires players own the original 1993 registered version of Doom in order to play. The SIGIL Megawad is the spiritual successor to the fourth episode of Doom, and picks up where the original left off."},{"t":"Skullgirls 2nd Encore","p":["Nintendo Switch"],"u":"Skybound Games","g":"Fighting","r":"October 22","l":"https://en.wikipedia.org/wiki/Skullgirls_2nd_Encore"},{"t":"Sky Racket","p":["macOS","Linux","Windows"],"d":"Double Dash Studios","u":"Double Dash Studios","g":"Indie game, Shoot 'em up, Block breaker","r":"October 22, 2019","l":"https://en.wikipedia.org/wiki/Sky_Racket_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1t0i.jpg","s":"The universe is in peril! Two kids are chosen to hold the powerful artifact \"Sky Racket\" and put a stop to an evil tyrant. Play as Racket Boy or Racket Girl, and with the help of cute and strong buddies, save this nonsense dystopian pixel art universe."},{"t":"Sky: Children of the Light","p":["iOS"],"u":"Thatgamecompany","g":"Adventure","r":"July 18","l":"https://www.igdb.com/games/sky-children-of-the-light","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocxvo.jpg","s":"\"Embark on an unforgettable social adventure and an ever-expanding world.\n\nSky: Children of the Light is a heartwarming and beautifully animated social adventure experience designed to be played together by you and your loved ones.\n\nSet in a wonderland above the clouds, Sky invites you and your friends to fly up to explore the buried mysteries together and rebuild a fallen kingdom for its ancient inhabitants. Using your courage and compassion, players must connect as a community to share and build on their flame to spread light back into the world.\""},{"t":"Slay the Spire","p":["Windows","macOS","Linux","PlayStation 4","Nintendo Switch"],"u":"Humble Bundle","g":"Roguelike","r":"January 23","l":"https://en.wikipedia.org/wiki/Slay_the_Spire","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1iyf.jpg","s":"Slay the Spire is a single-player roguelike deck-building game. Players choose from four characters, each with a unique set of cards, and attempt to climb a procedurally generated spire consisting of multiple floors of increasingly difficult enemies and bosses. Combat uses a card-based system where players build and refine their deck on the fly from rewards earned through encounters. Between battles, players collect relics that provide permanent buffs and make strategic choices about which paths to take, which cards to add or remove, and how to spend limited resources. The game is widely credited with popularizing the roguelike deck-building genre."},{"t":"Sneaky Sasquatch","p":["iOS","macOS","tvOS"],"d":"RAC7","u":"RAC7","g":"Adventure","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Sneaky_Sasquatch","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co50e4.jpg","s":"Live the life of a Sasquatch and do regular, everyday Sasquatch stuff like:\n\n- Sneak around campsites\n\n- Disguise yourself in human clothing\n\n- Eat food from unguarded coolers and picnic baskets\n\n- Play a quick 9 holes at the golf course\n\n- Go fishing at the lake\n\n- Cook sausages on an engine block\n\n- Get chased around by the park ranger\n\n- Dig up buried treasure\n\n- Take a driving test and get your driver’s license\n\n- Shred some powder at the ski hill\n\n- Buy, upgrade, and race vehicles at the racetrack\n\n- And more!"},{"t":"Sniper Elite V2 Remastered","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Rebellion Developments","g":"TPS","r":"May 14","l":"https://en.wikipedia.org/wiki/Sniper_Elite_V2_Remastered"},{"t":"Sniper Ghost Warrior Contracts","p":["Windows","PlayStation 4","Xbox One"],"u":"CI Games","g":"FPS","r":"November 22","l":"https://en.wikipedia.org/wiki/Sniper_Ghost_Warrior_Contracts","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ts7.jpg","s":"Experience the ultimate sniper gameplay, set against the rough terrain of the Siberian wilderness and featuring a brand new contracts system that encourages strategic thinking across engaging, replayable missions."},{"t":"Snooker 19","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Lab42","u":"Ripstone Games","g":"Sports","r":"April 17, 2019","l":"https://en.wikipedia.org/wiki/Snooker_19","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wkb.jpg","s":"This is the most authentic simulation of the sport ever created, with TV-style presentation and commentary, true-to-life physics and advanced artificial intelligence."},{"t":"Snow","p":["Windows","PlayStation 4"],"d":"Poppermost Productions","u":"Poppermost Productions, Sony Interactive Entertainment","g":"Sports","r":"February 14, 2019","l":"https://en.wikipedia.org/wiki/Snow_(2019_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4rfn.jpg","s":"SNOW - The Ultimate Edition is the only open world, winter sports game. Explore a massive mountain, customize your character with clothing and equipment, compete in events to be the best. Access to all mountains, tracks, events as well including all cosmetics, ski, snowboard, drone, and snowmobile."},{"t":"Song of Bloom","p":["iOS","Android"],"d":"Kamibox","g":"Puzzle","r":"December 28, 2019","l":"https://en.wikipedia.org/wiki/Song_of_Bloom","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2okp.jpg","s":"Song of Bloom\nis an intense tale about everything,\npacked into a short, handcrafted experience.\n\nPlayfully explore a story,\ntold in rapidly changing art styles,\nfind out how to control it,\nand uncover what happened."},{"t":"Song of Horror: Complete Edition","p":["Windows"],"u":"Raiser Games","g":"Survival horror","r":"October 31","l":"https://en.wikipedia.org/wiki/Song_of_Horror"},{"t":"Sonic Racing","p":["iOS"],"u":"Sega","g":"Racing","r":"September 19","l":"https://en.wikipedia.org/wiki/Sonic_Racing"},{"t":"Sorare","p":["Android","iOS","Browser"],"d":"Nicolas Julia and Adrien Montfort","u":"Sorare","g":"Sports management game","l":"https://en.wikipedia.org/wiki/Sorare"},{"t":"Space Engineers","p":["Windows"],"u":"Keen Software House","g":"Simulation","r":"February 9","l":"https://en.wikipedia.org/wiki/Space_Engineers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaaw8.jpg","s":"Space Engineers is a sandbox game about engineering, construction and maintenance of space works. Players build space ships and space stations of various sizes and utilization (civil and military), pilot ships and perform asteroid mining.\n\nSpace Engineers utilizes a realistic volumetric-based physics engine: all objects can be assembled, disassembled, damaged and destroyed."},{"t":"Spark the Electric Jester 2","p":["Windows"],"d":"Feperd Games","u":"Feperd Games","g":"Platform","r":"May 16, 2019","l":"https://en.wikipedia.org/wiki/Spark_the_Electric_Jester_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1zfb.jpg","s":"Following right after the ending of the original Spark the Electric Jester, you'll take control of Fark, now in the third dimension, in his quest to find out his true identity! Speed through several fast paced platforming stages, action packed bosses and fully animated cutscenes."},{"t":"Sparklite","p":["Windows","PlayStation 4","Nintendo Switch","Xbox One"],"d":"Red Blue Games","u":"Merge Games, Playdigious","g":"Action-adventure, roguelite","r":"November 14, 2019","l":"https://en.wikipedia.org/wiki/Sparklite","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1z3y.jpg","s":"Sparklite is an action-adventure set in the whimsical and ever-changing land of Geodia. Battle foes in top-down action using an arsenal of gadgets, guns, and gear. Explore dangerous corners of the procedurally generated world, take down titans of the mining industry, and harness the power of Sparklite!\n\nKey Features\n\n• Stunning visuals - Intricate pixel art aesthetic inspired by retro classics\n\n• Original soundtrack - GameCube inspired soundtrack by composer Dale North (Wizard of Legend)\n\n• Explore the world of Sparklite - Five beautiful, procedurally generated biomes\n\n• Invent your arsenal - Invent gadgets to solve puzzles and defeat enemies\n\n• Battle bosses - Take on the Baron Mining Corp and its formidable gremlin Titans\n\n• Meet the locals - Befriend the people of Geodia and help build The Refuge\n\n• Hunt collectibles - Discover collectibles scattered throughout the world\n\n• Buddy up! - Rescue Ada’s robotic sidekick to play local assistive co-op with a friend"},{"t":"SpellForce 3: Soul Harvest","p":["Windows"],"d":"Grimlore Games","u":"THQ Nordic","g":"Real-time strategy, role-playing","r":"May 28, 2019","l":"https://en.wikipedia.org/wiki/SpellForce_3:_Soul_Harvest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co30mr.jpg","s":"Three years after the Purity Wars, Nortander is on the cusp of a new era.\n\nHowever, things aren’t as peaceful as they seem – when the Queen calls you, a disgraced General, back to your homeland, you’re plunged in a war on many fronts: While a hatemonger threatens to tear apart the Dwarven realm, an enigmatic cult of Dark Elves harvests the souls of people for reasons unknown.\n\nGather your allies and prevent a catastrophe!"},{"t":"Sphinx and the Cursed Mummy","p":["Nintendo Switch"],"u":"THQ Nordic","g":"Action-adventure","r":"January 29","l":"https://en.wikipedia.org/wiki/Sphinx_and_the_Cursed_Mummy"},{"t":"Spice and Wolf VR","p":["Meta Quest","Windows","PlayStation VR","Nintendo Switch","Oculus VR","SteamVR"],"g":"Simulator, Adventure, Indie","l":"https://en.wikipedia.org/wiki/Spice_and_Wolf_VR","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9ujz.jpg","s":"In order to achieve our dreams of entering the 2nd dimension, we will be making the popular light novel Spice and Wolf into a VR animation! Anime will evolve from something that is “seen” to something that is “experienced”..."},{"t":"Spirit Hunter: Death Mark","p":["Windows"],"u":"Aksys Games","g":"Adventure, Visual novel","r":"April 4"},{"t":"Spirit Hunter: NG","p":["PlayStation 4","Windows","Nintendo Switch","PlayStation Vita"],"u":"Experience","g":"Adventure, Visual novel","r":"February 21"},{"t":"Spirit of the North","p":["PlayStation 4"],"u":"Infuse Studio","g":"Adventure","r":"November 1","l":"https://en.wikipedia.org/wiki/Spirit_of_the_North","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7ewy.jpg","s":"\"Spirit of the North is a single player, 3rd-person adventure game inspired by the breathtaking and mysterious landscapes of Iceland. The story takes root from various pieces of Nordic folklore. The game is unique in that it purposefully has no dialog or narrative. Players must breathe in their surroundings to solve various puzzles and speculate the meaning of a lost ancient civilization. Play as an ordinary red fox who’s story becomes entwined with the guardian of the Northern Lights, a female spirit fox. As you journey over the mountains and under red stained skies you’ll discover more about your companion and a land left in ruin.\""},{"t":"Splitgate","p":["Linux","Windows"],"d":"1047 Games","u":"1047 Games","g":"Shooter","r":"May 22, 2019","l":"https://www.igdb.com/games/splitgate","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coctqy.jpg","s":"Splitgate is a free-to-play, fast-paced multiplayer shooter that features player-controlled portals. This sci-fi shooter takes the FPS genre to a new dimension with its portal mechanics, delivering high-flying, multi-dimensional combat. Evoking memories of the most revered shooters of the past two decades, Splitgate embraces the classic and familiar feel of close-quarters combat while adding a unique twist."},{"t":"Spyro Reignited Trilogy","p":["Windows","Nintendo Switch"],"u":"Activision","g":"Platformer","r":"September 3","l":"https://en.wikipedia.org/wiki/Spyro_Reignited_Trilogy"},{"t":"Star Fox","p":["Nintendo Switch"],"g":"Rail Shooter","r":"September 5","l":"https://en.wikipedia.org/wiki/Star_Fox_(1993_video_game)"},{"t":"Star Fox 2","p":["Nintendo Switch"],"g":"Shoot 'em up (rail)","r":"December 12","l":"https://en.wikipedia.org/wiki/Star_Fox_2"},{"t":"Star Ocean: First Departure R","p":["Nintendo Switch","PlayStation 4"],"u":"Square Enix","g":"RPG","r":"December 5"},{"t":"Star Soldier","p":["Nintendo Switch"],"g":"Scrolling shooter","r":"April 10","l":"https://en.wikipedia.org/wiki/Star_Soldier_(video_game)"},{"t":"Star Wars Jedi: Fallen Order","p":["Windows","PlayStation 4","Xbox One"],"u":"Electronic Arts","g":"Action-adventure","r":"November 15","l":"https://www.igdb.com/games/star-wars-jedi-fallen-order","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rbi.jpg","s":"Star Wars Jedi: Fallen Order is a narratively driven, single-player game puts you in the role of a Jedi Padawan who narrowly escaped the purge of Order 66 following the events of Episode III: Revenge of the Sith. On a quest to rebuild the Jedi Order, you must pick up the pieces of your shattered past to complete your training, develop new powerful Force abilities and master the art of the iconic lightsaber - all while staying one step ahead of the Empire and its deadly Inquisitors."},{"t":"Starpoint Gemini 3","p":["Windows"],"d":"Little Green Men Games","u":"Little Green Men Games","g":"Space trading and combat simulator, Role playing video game","l":"https://en.wikipedia.org/wiki/Starpoint_Gemini_3","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co421o.jpg","s":"\"Get ready for an open-world space action single-player RPG. Enter the cockpit of wisecracking, hero Captain Jonathan Bold as he travels the vast universe of Starpoint Gemini 3.\n\nEngage in action-packed space battles, visit amazing worlds and encounter interesting characters to find the answers you seek. For the first time in the franchise, Starpoint Gemini 3 brings animated 3D, NPCs that you can interact with, and this time your path leads beyond Gemini as you get to explore two new planetary systems.\n\nYou are not alone on your journey. You have ADAH, a digital consciousness that runs your ship's computer and can download itself onto your drone, which you can then control in ADAH’s role to accomplish off-ship tasks you could never do alone.\n\nBuckle your seatbelts and prepare to immerse yourself in a world of space adventurer. Visit various venues, from pubs with shady clientele, to high-tech facilities and glitzy, noisy nightclubs, pick your targets and choose your allies. Your journey is about to begin.\""},{"t":"StarTropics","p":["Nintendo Switch"],"g":"Action-adventure","r":"March 13","l":"https://en.wikipedia.org/wiki/StarTropics"},{"t":"SteamWorld Quest","p":["Nintendo Switch","Windows","macOS","Linux"],"d":"Image & Form","u":"Thunderful Publishing","g":"Role-playing, deck-building","r":"April 25, 2019","l":"https://en.wikipedia.org/wiki/SteamWorld_Quest","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1quz.jpg","s":"SteamWorld Quest is the roleplaying card game you’ve been waiting for! Lead a party of aspiring heroes through a hand-drawn world and build, craft and upgrade your party’s decks in order to stop an ancient menace…"},{"t":"SteamWorld Quest: Hand of Gilgamech","p":["Nintendo Switch"],"g":"RPG","r":"April 25","l":"https://www.igdb.com/games/steamworld-quest-hand-of-gilgamech","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1quz.jpg","s":"SteamWorld Quest is the roleplaying card game you’ve been waiting for! Lead a party of aspiring heroes through a hand-drawn world and build, craft and upgrade your party’s decks in order to stop an ancient menace…"},{"t":"Steel Division 2","p":["Windows"],"d":"Eugen Systems","u":"Eugen Systems","g":"Real-time strategy, Turn-based strategy","r":"June 20, 2019","l":"https://en.wikipedia.org/wiki/Steel_Division_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rfl.jpg","s":"Steel Division 2 is a historically-accurate WW2 real-time strategy game set on the Eastern Front. Features 1:1-scale turn-based army management and real-time tactical battles with thousands of men at your order."},{"t":"Steins;Gate 0","p":["Nintendo Switch"],"u":"Spike Chunsoft","g":"Visual novel","r":"December 10","l":"https://en.wikipedia.org/wiki/Steins;Gate_0"},{"t":"Steins;Gate Elite","p":["Windows","Nintendo Switch","PlayStation 4","iOS"],"u":"Spike Chunsoft","g":"Visual novel","r":"February 19","l":"https://en.wikipedia.org/wiki/Steins;Gate_Elite"},{"t":"Steins;Gate: Linear Bounded Phenogram","p":["Windows","PlayStation 4"],"u":"Spike Chunsoft","g":"Visual novel","r":"February 19"},{"t":"Steins;Gate: My Darling's Embrace","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Spike Chunsoft","g":"Visual novel","r":"December 10"},{"t":"Stela","p":["iOS","Xbox One"],"d":"SkyBox Labs","u":"SkyBox Labs","g":"Adventure, puzzle","r":"October 17, 2019","l":"https://en.wikipedia.org/wiki/Stela_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co210u.jpg","s":"Stela is a cinematic, atmospheric platformer about a young woman witnessing the final days of a mysterious ancient world."},{"t":"Stellaris: Console Edition","p":["PlayStation 4","Xbox One"],"u":"Paradox Interactive","g":"Grand strategy","r":"February 26","l":"https://en.wikipedia.org/wiki/Stellaris_(video_game)"},{"t":"Steven Universe: Unleash the Light","p":["iOS"],"d":"Grumpyface Studios","u":"Cartoon Network Games","g":"Role-playing","r":"November 27, 2019","l":"https://en.wikipedia.org/wiki/Steven_Universe:_Unleash_the_Light","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4vo5.jpg","s":"The Crystal Gems are back for the third game in the Light Trilogy! When two powerful Gem rulers threaten the newfound peace of Era 3, Steven and his friends must embark on a new RPG quest to stop them! It’s time to Unleash the Light!"},{"t":"Still There","p":["Windows","macOS","Nintendo Switch"],"d":"GhostShark Games","u":"Iceberg Interactive","g":"Point-and-click adventure","r":"November 20, 2019","l":"https://en.wikipedia.org/wiki/Still_There","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tn1.jpg","s":"A sci-fi adventure into space station management, mysterious radio messages, motherfucking AIs, sociopathic people in charge, and finding one's true self in a galaxy way too far, far away.\n\nHow far is far enough?"},{"t":"Stone Story RPG","p":[],"l":"https://en.wikipedia.org/wiki/Stone_Story_RPG"},{"t":"Stormland","p":["Windows"],"d":"Insomniac Games","u":"Oculus Studios","g":"Action-adventure","r":"November 14, 2019","l":"https://en.wikipedia.org/wiki/Stormland_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wk9.jpg","s":"The Tempest shattered your android body. Now you must journey through an ever-changing cloudscape to augment yourself and save your friends. Explore an expansive world with complete freedom — bound up cliffs, glide across chasms, and fly through the slipstream with velocity. Detonate explosives, harness electricity, and wield makeshift weapons to overcome titanium sentries and monolithic guardians. Play single-player, or explore forgotten ruins together. It’s time to reclaim your world."},{"t":"Stranded Sails: Explorers of the Cursed Islands","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"rokaplay, Merge Games","g":"Adventure","r":"October 17"},{"t":"Stranger Things 3: The Game","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Netflix","g":"Brawler","r":"July 4"},{"t":"Streets of Rogue","p":["Linux","macOS","Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Matt Dabrowski","u":"tinyBuild","g":"Roguelike","r":"July 12, 2019","l":"https://en.wikipedia.org/wiki/Streets_of_Rogue","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rbv.jpg","s":"Streets of Rogue is a top-down rogue-lite with an emphasis on player agency and freedom. It combines shooting, stealth, and role-playing elements in a procedurally generated city.\n\nRather than taking place in a dungeon, the game is set in a functioning, procedurally generated city, where complex AI informs denizens from all walks of life, who are just trying to get by in their daily activities. In order to progress, the player will need to accomplish specific mission goals in any way they see fit through use of their special character traits, items, and the environment."},{"t":"Stunt Race FX","p":["Nintendo Switch"],"g":"Racing","r":"September 5","l":"https://en.wikipedia.org/wiki/Stunt_Race_FX"},{"t":"Stygian: Reign of the Old Ones","p":["Linux","macOS","Windows"],"d":"Cultic Games","u":"1C Entertainment","g":"Tactical role-playing","r":"September 26, 2019","l":"https://en.wikipedia.org/wiki/Stygian:_Reign_of_the_Old_Ones","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rgn.jpg","s":"\"Stygian: Reign of the Old Ones\" is a supernatural horror roleplaying video game which takes place in the strange worlds of Howard Phillips Lovecraft. Stygian will draw the player into a bleak journey from a ruined Arkham to the very depths of the Abyss.\n\nThe gameplay experience promises a mix of rich role-playing and turn based tactical combat in an authentic illustrative 2D graphical style.\n\nIn Stygian, you'll be able to create your character from scratch with a robust selection of archetypal backgrounds with different origin stories, attributes, skills, traits and lastly belief systems which determine how your character replenishes lost sanity, also presenting unique dialog choices.\n\nThe narrative of the game is strongly connected to the works of H. P. Lovecraft. In your quest, you'll use the haunted violin of Erich Zann to lure a fiendish deity and convince the poor wretched protagonist of \"The Outsider\" to join your party among many others.\n\nThe heavy burden of fighting a desperate battle with forces beyond recognition will haunt you to the end of the game. Physical combat will be scarce and difficult, spellcasting will have deep and dangerous consequences, sanity loss will leave its marks on characters as mental illnesses and sometimes the best solution will be running away from the terrors that lurk in the night.\n\nStygian embraces the original themes of pulp and weird fiction, incorporating them into the computer roleplaying genre, promising a fresh (or putrid from another perspective) breath of air for roleplaying fans."},{"t":"Sunless Skies","p":["Windows","macOS","Linux"],"u":"Failbetter Games","g":"RPG","r":"January 31","l":"https://en.wikipedia.org/wiki/Sunless_Skies"},{"t":"Super Blood Hockey","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"Loren Lemcke","u":"Loren Lemcke","g":"Sports game","r":"April 26, 2019","l":"https://en.wikipedia.org/wiki/Super_Blood_Hockey"},{"t":"Super Dragon Ball Heroes: World Mission","p":["Windows","Nintendo Switch"],"u":"Bandai Namco Entertainment","g":"DCCG","r":"April 5"},{"t":"Super E.D.F. Earth Defense Force","p":["Nintendo Switch"],"g":"Scrolling shooter","r":"September 5","l":"https://en.wikipedia.org/wiki/Earth_Defense_Force_(video_game)"},{"t":"Super Family Tennis","p":["Nintendo Switch"],"g":"Sports (Tennis)","r":"September 5","l":"https://en.wikipedia.org/wiki/Smash_Tennis"},{"t":"Super Ghouls 'n Ghosts","p":["Nintendo Switch"],"g":"Platformer","r":"September 5","l":"https://en.wikipedia.org/wiki/Super_Ghouls_%27n_Ghosts"},{"t":"Super Kirby Clash","p":["Nintendo Switch"],"u":"Nintendo","g":"Action","r":"September 4","l":"https://en.wikipedia.org/wiki/Super_Kirby_Clash"},{"t":"Super Mario Bros. 2","p":["Nintendo Switch"],"g":"Platformer","r":"February 13","l":"https://en.wikipedia.org/wiki/Super_Mario_Bros._2"},{"t":"Super Mario Bros.: The Lost Levels","p":["Nintendo Switch"],"g":"Platformer","r":"April 10"},{"t":"Super Mario Kart","p":["Nintendo Switch"],"g":"Racing (kart)","r":"September 5","l":"https://en.wikipedia.org/wiki/Super_Mario_Kart"},{"t":"Super Mario Maker 2","p":["Nintendo Switch"],"u":"Nintendo","g":"Level editor , Platformer","r":"June 28","l":"https://en.wikipedia.org/wiki/Super_Mario_Maker_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21vy.jpg","s":"A side-scrolling Mario adventure that unleashes the creative potential of Super Mario Maker 2 awaits in Story Mode, which contains over 100 built-in courses. And in Course Maker, a wide range of parts, tools, and more are available so you can construct your own courses. Want coin-shooting cannons? Bowser riding on a giant Goomba? Cat Mario sliding down slopes to take out an army of baddies? Go for it! You call the shots. Pass a Joy-Con controller to a partner to build co-operatively on a single system!"},{"t":"Super Mario World","p":["Nintendo Switch"],"g":"Platformer","r":"September 5","l":"https://en.wikipedia.org/wiki/Super_Mario_World"},{"t":"Super Mario World 2: Yoshi's Island","p":["Nintendo Switch"],"g":"Platformer","r":"September 5","l":"https://en.wikipedia.org/wiki/Yoshi%27s_Island"},{"t":"Super Metroid","p":["Nintendo Switch"],"g":"Action-adventure","r":"September 5","l":"https://en.wikipedia.org/wiki/Super_Metroid"},{"t":"Super Monkey Ball: Banana Blitz HD","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Sega","g":"Platformer","r":"October 29"},{"t":"Super Neptunia RPG","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Idea Factory","g":"RPG","r":"June 20","l":"https://en.wikipedia.org/wiki/Super_Neptunia_RPG"},{"t":"Super Punch-Out!!","p":["Nintendo Switch"],"g":"Sports (Boxing)","r":"December 12","l":"https://en.wikipedia.org/wiki/Super_Punch-Out!!"},{"t":"Super Puyo Puyo 2","p":["Nintendo Switch"],"g":"Puzzle","r":"September 5","l":"https://en.wikipedia.org/wiki/Puyo_Puyo_2"},{"t":"Super Robot Wars T","p":["Nintendo Switch","PlayStation 4"],"u":"Bandai Namco Entertainment","g":"Tactical RPG","r":"March 20","l":"https://en.wikipedia.org/wiki/Super_Robot_Wars_T"},{"t":"Super Soccer","p":["Nintendo Switch"],"g":"Sports (Soccer)","r":"September 5","l":"https://en.wikipedia.org/wiki/Super_Soccer"},{"t":"Super Tennis","p":["Nintendo Switch"],"g":"Sports (Tennis)","r":"September 5","l":"https://en.wikipedia.org/wiki/Super_Tennis"},{"t":"Supraland","p":["Windows"],"d":"Supra Games","u":"Supra Games, Humble Games","g":"Metroidvania, puzzle video game","r":"April 5, 2019","l":"https://en.wikipedia.org/wiki/Supraland","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2yys.jpg","s":"Supraland is a first-person metroidvania puzzle game. Explore, solve puzzles, beat up monsters, find secret upgrades and new abilities that help you reach new places."},{"t":"Sword Art Online: Fatal Bullet Complete Edition","p":["Nintendo Switch"],"u":"Bandai Namco Entertainment","g":"Action RPG","r":"August 9"},{"t":"Swords and Soldiers 2 Shawarmageddon","p":["Nintendo Switch"],"u":"Ronimo Games","g":"Strategy","r":"March 1","l":"https://en.wikipedia.org/wiki/Swords_%26_Soldiers_II"},{"t":"Synth Riders","p":["SteamVR","Oculus Rift","Meta Quest","PlayStation 4","PlayStation 5","PlayStation VR","Windows","Android"],"d":"Kluge Interactive","u":"Kluge Interactive","g":"Rhythm","r":"May 21, 2019","l":"https://en.wikipedia.org/wiki/Synth_Riders","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8umj.jpg","s":"An action-dance VR rhythm game with custom song support and a thriving multiplayer community."},{"t":"Table of Tales: The Crooked Crown","p":["PlayStation VR"],"u":"Tin Man Games","g":"Digital tabletop , RPG","r":"April 16"},{"t":"Tactical Nexus","p":["Windows"],"u":"Team-Tactical Nexus","g":"Puzzle","r":"November 11"},{"t":"Tales of the Neon Sea","p":["Windows","iOS","Android","Nintendo Switch","Xbox One","Xbox Series X/S","PlayStation 4"],"d":"Palm Pioneer, YiTi Games","u":"Zodiac Interactive, Boke Technology Co., Ltd, Thermite Games","g":"Adventure, Puzzle","r":"April 30, 2019","l":"https://en.wikipedia.org/wiki/Tales_of_the_Neon_Sea","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/w4uuihbcbwfjmmfb10na.jpg","s":"Welcome to a world of intrigue and suspicion. Where humans and robots contend with escalating tensions and mutual distrust. And where gangster felines scheme their way to the top of the food chain. Welcome to the Tales of the Neon Sea!"},{"t":"Tales of Vesperia: Definitive Edition","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Bandai Namco Entertainment","g":"RPG","r":"January 11","l":"https://en.wikipedia.org/wiki/Tales_of_Vesperia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5gb5.jpg","s":"Tales of Vesperia: Definitive Edition is a remaster of the expanded Playstation 3 port of the original game, which was exclusive to Japan.\n\nDive into the definitive version of this game with updated full-HD graphics, brand-new music tracks, exciting mini-games, bosses and more!\n\nTwo more playable characters join the fray!\n- Patty Fleur, a cheerful and tough young pirate girl in search of treasure, adventure… and her forgotten memories.\n- Flynn Scifo, Yuri’s best friend and an Imperial Knight, now joins the rest on their journey!\n\nA power struggle begins in a civilization dependent on an ancient technology, the blastia, and the Empire that controls it. The fates of two friends traveling separate paths intertwine in an epic adventure that threatens the existence of all."},{"t":"Tangle Tower","p":["macOS","Windows","Nintendo Switch"],"d":"SFB Games","u":"SFB Games","g":"Adventure game","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Tangle_Tower","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6i1n.jpg","s":"Unravel a thrilling mystery by exploring a strange and twisted mansion, discovering curious clues, interrogating peculiar suspects and solving unique puzzles.\n\nFreya Fellow has been murdered. The lead suspect? A shadowy figure found looming over her body, wielding a knife. The problem? That suspect... is just a painting.\n\nInvestigate the entirety of Tangle Tower, from the bizarre and eerie gardens, to the cold and ominous crime scene at the very top.\n\nWill you be able to uncover the secrets of Tangle Tower?"},{"t":"Team Sonic Racing","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Sega","g":"Racing (kart)","r":"May 21","l":"https://en.wikipedia.org/wiki/Team_Sonic_Racing","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1upm.jpg","s":"Team Sonic Racing combines the best elements of arcade and fast-paced competitive style racing as you face-off with friends in intense multiplayer racing."},{"t":"Teppen","p":["iOS","Android"],"u":"GungHo Online Entertainment","g":"DCCG","r":"July 5","l":"https://en.wikipedia.org/wiki/Teppen"},{"t":"Terminator: Resistance","p":["Windows","PlayStation 4","Xbox One"],"u":"Reef Entertainment","g":"FPS","r":"November 14","l":"https://www.igdb.com/games/terminator-resistance","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1s30.jpg","s":"Terminator: Resistance, is a first-person shooter set during the 'Future War' scenario that was only glimpsed at in the iconic films, 'THE TERMINATOR' and 'T2: JUDGMENT DAY'. The machines are destined to lose, but at what cost?"},{"t":"Tetris 99","p":["Nintendo Switch"],"u":"Nintendo","g":"Puzzle, Battle royale","r":"February 13","l":"https://en.wikipedia.org/wiki/Tetris_99","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cock8f.jpg","s":"A blockbuster battle royale!\n99 players but only one will remain! Tetris 99 is the iconic puzzle game as you've never seen it before. Can you pick the right strategy to best 98 other players online - all at the same time?!"},{"t":"Tetris Effect","p":["Windows"],"d":"Monstars, Resonair","u":"Enhance Games","g":"Puzzle","r":"July 23, 2019","l":"https://en.wikipedia.org/wiki/Tetris_Effect"},{"t":"The Addams Family Mystery Mansion","p":[],"l":"https://en.wikipedia.org/wiki/The_Addams_Family_Mystery_Mansion"},{"t":"The Alliance Alive HD Remastered","p":["Nintendo Switch","PlayStation 4"],"u":"NIS America","g":"RPG","r":"October 8","l":"https://en.wikipedia.org/wiki/The_Alliance_Alive_HD_Remastered"},{"t":"The Angry Birds Movie 2 VR: Under Pressure","p":["PlayStation 4"],"d":"XR Games","u":"Rovio Entertainment","g":"Party","r":"August 6"},{"t":"The Bard's Tale IV: Director's Cut","p":["Windows","macOS","Linux","PlayStation 4","Xbox One"],"u":"inXile Entertainment","g":"Roguelike","r":"August 27"},{"t":"The Bard's Tale Trilogy","p":["Xbox One"],"u":"inXile Entertainment","g":"Roguelike","r":"August 13","l":"https://en.wikipedia.org/wiki/The_Bard%27s_Tale_Trilogy"},{"t":"The Beast Inside","p":["Windows"],"d":"Illusion Ray Studio","u":"Movie Games S.A.","g":"Role-playing (RPG), Adventure, Indie","r":"October 17, 2019","l":"https://www.igdb.com/games/the-beast-inside","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co20uk.jpg","s":"The Beast Inside is a gripping new twist on thriller and survival horror genres, telling a multi-layered story about cryptanalyst discovering a hundred-year-old murder-mystery that not only remains unresolved, but also puts his very life at risk."},{"t":"The Book of Unwritten Tales 2","p":["Nintendo Switch"],"u":"THQ Nordic","g":"PCA","r":"February 5","l":"https://en.wikipedia.org/wiki/The_Book_of_Unwritten_Tales_2"},{"t":"The Caligula Effect: Overdose","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"NIS America","g":"RPG","r":"March 12","l":"https://en.wikipedia.org/wiki/The_Caligula_Effect"},{"t":"The Church in the Darkness","p":["Windows","macOS","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Fellow Traveler","g":"Action-adventure","r":"August 2","l":"https://en.wikipedia.org/wiki/The_Church_in_the_Darkness"},{"t":"The Coin Game","p":["Windows"],"u":"Devotid","g":"Life sim","r":"February 22"},{"t":"The Cycle: Frontier","p":["Windows"],"d":"Yager Development","u":"Yager Development","g":"First-person shooter, extraction shooter","l":"https://en.wikipedia.org/wiki/The_Cycle:_Frontier"},{"t":"The Dark Pictures Anthology: Man of Medan","p":["PlayStation 4","Windows","Xbox One"],"d":"Supermassive Games","u":"Bandai Namco Entertainment","g":"Interactive drama, Survival horror","r":"August 30, 2019","l":"https://en.wikipedia.org/wiki/The_Dark_Pictures_Anthology:_Man_of_Medan","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1omz.jpg","s":"Enter the world of The Dark Pictures - A series of standalone cinematic horror games. Players will be challenged to explore and uncover each story with the knowledge that all their choices have consequences and all playable characters can live, any and all can die..."},{"t":"The Dark Pictures: Man of Medan","p":["Windows","PlayStation 4","Xbox One"],"u":"Bandai Namco Entertainment","g":"Adventure, Survival horror","r":"August 30"},{"t":"The Eternal Castle Remastered","p":["Windows"],"d":"Leonard Menchiari, Daniele Vicinanzo, Giulio Perrone","u":"SEVERED PRESS PTY LTD","g":"Adventure, platform","r":"January 5, 2019","l":"https://en.wikipedia.org/wiki/The_Eternal_Castle_Remastered"},{"t":"The Grand Tour Game","p":["PlayStation 4","Xbox One"],"d":"Amazon Game Studios Seattle","u":"Amazon Game Studios","g":"Racing game","r":"January 15, 2019","l":"https://en.wikipedia.org/wiki/The_Grand_Tour_Game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wnx.jpg","s":"Ever wish you could get behind the wheel with Clarkson, Hammond, and May from The Grand Tour? Now it's your turn! One moment you're watching the hosts attempt some questionable automotive antics... the next you're at the wheel yourself - same car, same location, same chance to make a massive mess of it."},{"t":"The House in Fata Morgana: Dream of the Revenants Edition","p":["PlayStation Vita","PlayStation 4"],"u":"Mighty Rabbit Studios","g":"Visual novel","r":"May 28"},{"t":"The Invisible Guardian","p":["Windows"],"g":"Visual novel","r":"January 23","l":"https://en.wikipedia.org/wiki/The_Invisible_Guardian_(video_game)"},{"t":"The Jackbox Party Pack 6","p":["Windows","macOS","Linux","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Jackbox Games","g":"Party","r":"October 17","l":"https://en.wikipedia.org/wiki/The_Jackbox_Party_Pack_6","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4zep.jpg","s":"It's the wildest Party Pack yet, with the absurd deathmatch Trivia Murder Party 2, the weird word circus Dictionarium, the hidden identity game Push The Button, the comedy contest Joke Boat and the offbeat personality test Role Models. Use your phones or tablets as controllers and play with up to 10 players, plus an audience of up to 10,000!"},{"t":"The King's Bird","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"Graffiti Games","g":"Platformer","r":"February 12","l":"https://en.wikipedia.org/wiki/The_King%27s_Bird"},{"t":"The Legend of Bum-bo","p":["Windows"],"d":"Edmund McMillen, James Interactive","u":"Edmund McMillen, The Label, Nicalis","g":"Roguelike deck-building, puzzle","r":"November 12, 2019","l":"https://en.wikipedia.org/wiki/The_Legend_of_Bum-bo","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1suk.jpg","s":"The Legend of Bum-bo is a randomly generated turn based puzzle RPG. It's a spin-off of Binding of Isaac: Rebirth."},{"t":"The Legend of Heroes: Trails of Cold Steel","p":["PlayStation 4"],"u":"Xseed Games","g":"RPG","r":"March 26"},{"t":"The Legend of Heroes: Trails of Cold Steel II","p":["PlayStation 4"],"u":"Xseed Games","g":"RPG","r":"June 4"},{"t":"The Legend of Heroes: Trails of Cold Steel III","p":["PlayStation 4"],"u":"Xseed Games","g":"RPG","r":"October 22"},{"t":"The Legend of Zelda: A Link to the Past","p":["Nintendo Switch"],"g":"Action-adventure","r":"September 5"},{"t":"The Legend of Zelda: Link's Awakening","p":["Nintendo Switch"],"u":"Nintendo","g":"Action-adventure","r":"September 20","l":"https://www.igdb.com/games/the-legend-of-zelda-links-awakening--1","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qve.jpg","s":"As Link, you awaken in a strange land away from Hyrule, where animals talk and monsters roam. To uncover the truth behind your whereabouts and rouse the legendary Wind Fish, explore Koholint Island and all its trap-ridden dungeons, reimagined in stunning detail for this new release of one of the most beloved The Legend of Zelda games. Along the way, you'll meet a hilarious assortment of charming characters to which you'll never want to say goodbye.\n\nIn this new version of the game, the classic soundtrack has been reborn with new arrangements, and now you can equip more items at once, review key conversations, and navigate the map in new ways. Try your hand at the renovated mini-games to earn dolls based on the Super Mario series...or Chamber Stones, which you can use to arrange your own Chamber Dungeons. Each one is a puzzle in and of itself!"},{"t":"The Lego Movie 2 Videogame","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Warner Bros. Interactive Entertainment","g":"Action-adventure","r":"February 26","l":"https://en.wikipedia.org/wiki/The_Lego_Movie_2_Videogame"},{"t":"The Liar Princess and the Blind Prince","p":["Nintendo Switch","PlayStation 4"],"u":"Nippon Ichi Software","g":"Action-adventure","r":"February 12","l":"https://en.wikipedia.org/wiki/The_Liar_Princess_and_the_Blind_Prince"},{"t":"The Lord of the Rings Online: Minas Morgul","p":["Windows"],"d":"Standing Stone Games","u":"Daybreak Game Company","g":"MMORPG","r":"November 5, 2019","l":"https://en.wikipedia.org/wiki/The_Lord_of_the_Rings_Online:_Minas_Morgul"},{"t":"The Ninja Saviors: Return of the Warriors","p":["Nintendo Switch","PlayStation 4"],"u":"ININ Games","g":"Brawler","r":"August 30"},{"t":"The Occupation","p":["Windows","PlayStation 4","Xbox One"],"u":"Humble Bundle","g":"Stealth","r":"March 5","l":"https://en.wikipedia.org/wiki/The_Occupation"},{"t":"The Outer Worlds","p":["Windows","PlayStation 4","Xbox One"],"u":"Private Division","g":"RPG, FPS","r":"October 25","l":"https://en.wikipedia.org/wiki/The_Outer_Worlds","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2eew.jpg","s":"The Outer Worlds is a new single-player sci-fi RPG from Obsidian Entertainment and Private Division. As you explore the furthest reaches of space and encounter a host of factions all vying for power, who you decide to become will determine the fate of everyone in Halcyon. In the corporate equation for the colony, you are the unplanned variable."},{"t":"The Raven Remastered","p":["Nintendo Switch"],"u":"THQ Nordic","g":"PCA","r":"January 22"},{"t":"The Seven Deadly Sins: Grand Cross","p":["iOS","Android","Windows"],"d":"Netmarble","u":"Netmarble","g":"Tactical RPG","r":"June 4"},{"t":"The Sims 4: Discover University","p":[],"l":"https://en.wikipedia.org/wiki/The_Sims_4:_Discover_University"},{"t":"The Sims 4: Island Living","p":[],"l":"https://en.wikipedia.org/wiki/The_Sims_4:_Island_Living"},{"t":"The Sims 4: Realm of Magic","p":[],"l":"https://en.wikipedia.org/wiki/The_Sims_4:_Realm_of_Magic"},{"t":"The Sims 4: StrangerVille","p":[],"l":"https://en.wikipedia.org/wiki/The_Sims_4:_StrangerVille"},{"t":"The Sinking City","p":["Windows","PlayStation 4","Xbox One"],"u":"Bigben Interactive","g":"Action-adventure, Survival horror","r":"June 27","l":"https://en.wikipedia.org/wiki/The_Sinking_City","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co7kpe.jpg","s":"The Sinking City is a game of investigation genre taking place in a fictional open world inspired by the works of H.P. Lovecraft.\nThe player incarnates a private investigator in 1920s, who finds himself in a city of New England, Oakmont Massachusetts. It's currently suffering from extensive waterflood, and its cause is clearly supernatural."},{"t":"The Stillness of the Wind","p":["Windows","Nintendo Switch"],"d":"Lambic Studios","u":"Fellow Traveler","g":"Simulation","r":"February 7, 2019","l":"https://en.wikipedia.org/wiki/The_Stillness_of_the_Wind","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2l3e.jpg","s":"One by one, everyone left the once bustling village for the city. Everyone, except Talma. Now approaching the end of her days, she maintains a simple, solitary way of life, surviving, subsisting, tending to her homestead and her goats.\n\nDevelop your own personal routine as you care for your farm and your animals. Tend to your goats, make cheese with their milk, collect eggs and cook meals, grow vegetables and barter with the travelling merchant who brings increasingly disturbing letters from your family in the city.\n\nA follow up to the critically acclaimed Where the Goats Are, The Stillness of the Wind is a quiet rumination on life and loss."},{"t":"The Stretchers","p":["Nintendo Switch"],"d":"Tarsier Studios","u":"Nintendo","g":"Action puzzle","r":"November 8, 2019","l":"https://en.wikipedia.org/wiki/The_Stretchers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xjj.jpg","s":"The world has a bad case of the Dizzies - residents dizzied by Captain Brains - and only you can rescue them! Work with a friend in co-op or skillfully control two medics on your own to overcome the physics-based puzzles of each madcap mission. Either way, how you go about it is totally up to you, whether you work together to transport many Dizzies at once on a stretcher or work in parallel by splitting up dragging the Dizzies to the ambulance one by one. As you play and replay missions, you'll complete bonus objectives and uncover hidden collectibles with hilarious results!"},{"t":"The Surge 2","p":["Windows","PlayStation 4","Xbox One"],"u":"Focus Home Interactive","g":"Action RPG","r":"September 24","l":"https://en.wikipedia.org/wiki/The_Surge_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1y0k.jpg","s":"The Surge 2 keeps what fans and critics loved about the original while also expanding greatly upon the formula. The Surge 2 takes place in a brand new environment: a sprawling, devastated city with larger, more ambitious level design and improved engine. Combat is more brutal and tactical than ever, with even more options thanks to an expanded limb targeting system."},{"t":"The TakeOver","p":["Windows","macOS"],"u":"Pelikan13","g":"Brawler","r":"November 10","l":"https://en.wikipedia.org/wiki/The_TakeOver"},{"t":"The Textorcist: The Story of Ray Bibbia","p":["Windows","macOS"],"d":"Morbidware","u":"Headup Games","g":"Bullet hell, typing","r":"February 14, 2019","l":"https://en.wikipedia.org/wiki/The_Textorcist:_The_Story_of_Ray_Bibbia","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2kft.jpg","s":"Get ready for an electrifying mix between a bullet game and a typing hell! Dodge bullets while typing exorcisms at the very same time: turn on both sides of your brain and jump into the adventure of Ray Bibbia!"},{"t":"The Touryst","p":["Nintendo Switch"],"d":"Shin'en Multimedia","u":"Shin'en Multimedia","g":"Action-adventure","r":"November 21, 2019","l":"https://en.wikipedia.org/wiki/The_Touryst","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2eix.jpg","s":"Discover exotic islands, explore ancient monuments, uncover secret passageways, and make the trip you always wanted in The Touryst\n\nYou are just arriving at the Monument Islands. Want to go swimming? Or rather take a dive into the deep sea? Or do you want to visit the amusement arcade, do some shopping, dance at the beach party? Fancy some surfing? Or will you talk with the strange old tourist and listen what he has to say about these ancient mysterious monuments.."},{"t":"The Under Presents","p":["Oculus Rift","Meta Quest"],"d":"Tender Claws","u":"Tender Claws","g":"Magic system, interactive film, artgame, cooperative video game","r":"November 19, 2019","l":"https://en.wikipedia.org/wiki/The_Under_Presents","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2poz.jpg","s":"Enter The Under, our otherworldly multiplayer hub, and discover a vast mystical desert with other players. Explore and engage with your fellow Time Sprites to unlock and discover the secrets buried beneath the sands. Learn and perform magic in collective rituals to alter the world around you. You never know who you might cross paths with while catching a show on the Under stage, investigating the Observatory, or tending the MC's garden..."},{"t":"The Walking Dead: The Final Season – Episode 3: Broken Toys","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Skybound Entertainment","g":"Graphic adventure","r":"January 15"},{"t":"The Walking Dead: The Final Season – Episode 4: Take Us Back","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Skybound Entertainment","g":"Graphic adventure","r":"March 26"},{"t":"The Wanderer: Frankenstein's Creature","p":["Windows","Nintendo Switch","iOS","Android","PlayStation 4","Xbox One"],"u":"ARTE France","g":"Adventure","r":"October 29"},{"t":"The Wild Eight","p":["Windows"],"d":"Eight Points","u":"HypeTrain Digital","g":"Survival","r":"October 3, 2019","l":"https://en.wikipedia.org/wiki/The_Wild_Eight","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qhc.jpg","s":"The Wild Eight is an intense survival action-adventure set in the frozen wilderness of Alaska. Team up with friends in online co-op or go solo, explore the mysterious land, craft weapons and fight to live another day."},{"t":"The Witcher 3: Wild Hunt Complete Edition","p":["Nintendo Switch"],"u":"Warner Bros. Interactive Entertainment","g":"Action RPG","r":"October 15"},{"t":"The World Next Door","p":["macOS","Windows","Nintendo Switch"],"d":"Rose City Games","u":"Viz Media","g":"Visual novel, puzzle","r":"March 28, 2019","l":"https://en.wikipedia.org/wiki/The_World_Next_Door_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2rog.jpg","s":"The World Next Door is a narrative-driven, action adventure game that follows Jun, a rebellious teen girl trapped in a parallel world inhabited by magical creatures. Inspired by the emotional storytelling and thrilling action of both anime and indie games, players can expect to meet and develop friendships with an eclectic cast of characters while uncovering the mysteries hidden within this world."},{"t":"Thea 2: The Shattering","p":["Windows"],"d":"MuHa Games","u":"MuHa Games, RockGame","g":"Strategy","r":"May 13, 2019","l":"https://en.wikipedia.org/wiki/Thea_2:_The_Shattering","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1hj6.jpg","s":"In the dark lands inspired by Slavic myth, life is a struggle for survival against ever increasing odds, be it natural or malevolent. Can you lead your flock to prosperity in this innovative blend of 4X strategy, RPG and card game?"},{"t":"They Are Billions","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Numantian Games","u":"Numantian Games, BlitWorks","g":"Real-time strategy, survival","r":"June 18, 2019","l":"https://en.wikipedia.org/wiki/They_Are_Billions","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n7h.jpg","s":"They Are Billions is a Steampunk strategy game set on a post-apocalyptic planet. Build and defend colonies to survive against the billions of the infected that seek to annihilate the few remaining living humans. Can humanity survive after the zombie apocalypse?"},{"t":"Time Stall","p":["Meta Quest"],"d":"Force Field Entertainment","u":"Oculus Studios","g":"Puzzle, Space/ Universe","r":"August 15, 2019","l":"https://en.wikipedia.org/wiki/Time_Stall","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1y8p.jpg","s":"Welcome aboard the Fantastic Leap, Earth's only crowdfunded, luxury escape craft! As the only human serving alongside a robotic crew, your job is to keep the ship safe using Time Stall, the ship's time-bending safety protocol.\nWhen disaster strikes, Time Stall temporarily freezes time aboard the ship, allowing you to manipulate objects, divert projectiles and combine various objects… whatever it takes to save the ship and her Captain from destruction!"},{"t":"Timespinner","p":["Nintendo Switch"],"u":"Lunar Ray Games","g":"Metroidvania","r":"June 4","l":"https://en.wikipedia.org/wiki/Timespinner","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co24ag.jpg","s":"Timespinner is a 2D metroidvania platformer about a young woman who travels through time to destroy the empire that killed her family.\n\nAt its heart, the game is a child of the great pixelated classics of the SNES and PS1 age. From the rich story worlds of Star Ocean, the expansive gothic castle to explore in Castlevania: Symphony of the Night, and the tight gameplay of Megaman X, Timespinner seeks to weave all of these elements into one amazing game."},{"t":"Tiny Metal: Full Metal Rumble","p":["Windows","Nintendo Switch"],"u":"Unties","g":"TBT","r":"July 11","l":"https://en.wikipedia.org/wiki/Tiny_Metal"},{"t":"ToeJam & Earl: Back in the Groove","p":["Windows","macOS","Linux","Nintendo Switch","PlayStation 4","Xbox One"],"u":"HumaNature Studios","g":"Action, Platformer","r":"March 1"},{"t":"Tokyo Chronos","p":["PlayStation 4"],"u":"Sekai Project","g":"Adventure","r":"August 22","l":"https://en.wikipedia.org/wiki/Tokyo_Chronos"},{"t":"Tokyo Ghoul: re Call to Exist","p":["Windows","PlayStation 4"],"u":"Bandai Namco Entertainment","g":"Action, Survival","r":"November 15"},{"t":"Tom Clancy's Ghost Recon Breakpoint","p":["Windows","PlayStation 4","Xbox One"],"u":"Ubisoft","g":"Tactical shooter","r":"October 4","l":"https://en.wikipedia.org/wiki/Tom_Clancy%27s_Ghost_Recon_Breakpoint","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocogs.jpg","s":"Tom Clancy's Ghost Recon Breakpoint is a military shooter set in a diverse and hostile open world entirely playable solo or in up to four-player co-op. Players will discover Auroa, a mysterious island where the most technically advanced facilities meet wild and untamed nature. Home to drone creators, tech giant Skell Technology, Auroa has fallen into the wrong hands and all contact has been lost."},{"t":"Tom Clancy's The Division 2","p":["Windows","PlayStation 4","Xbox One"],"u":"Ubisoft","g":"Action RPG","r":"March 15","l":"https://en.wikipedia.org/wiki/Tom_Clancy%27s_The_Division_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xrm.jpg","s":"The Division 2 is an action-shooter RPG set in an open-world. Play in co-op and PvP modes that offer more variety in missions and challenges, new progression systems with unique twists and surprises, and fresh gaming innovations to engage players for years to come."},{"t":"Tomb Raider","p":["Stadia"],"u":"Square Enix","g":"Action-adventure","r":"November 19","l":"https://en.wikipedia.org/wiki/Tomb_Raider_(2013_video_game)"},{"t":"Tools Up!","p":["PlayStation 4","Nintendo Switch","Windows","Xbox One"],"d":"The Knights of Unity","u":"All in! Games SA","g":"Action","r":"December 3, 2019","l":"https://en.wikipedia.org/wiki/Tools_Up!","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1tpp.jpg","s":"Gather up to 4 players for this fun couch co-op experience for people of all skills! Renovate the apartments in the mysterious skyscraper while the tenants are away. Be sure to follow their wishes left behind on the blueprints. Tear off wallpapers, bring down walls, bust down doors, and cover the floor with vibrant carpets and panels - just be sure to do it in time and clean up after yourself!"},{"t":"Total War: Three Kingdoms","p":["Windows"],"u":"Sega","g":"TBS, RTT","r":"May 23","l":"https://www.igdb.com/games/total-war-three-kingdoms","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coc2o2.jpg","s":"Total War: Three Kingdoms is the first in the series to recreate epic conflict across ancient China. Combining a gripping turn-based campaign of empire-building & conquest with stunning real-time battles, Three Kingdoms redefines the series in an age of heroes & legends."},{"t":"Touhou Luna Nights","p":["Windows","Xbox One","Nintendo Switch"],"u":"Playism Active Gaming Media","g":"Action-adventure","r":"February 25","l":"https://en.wikipedia.org/wiki/Touhou_Luna_Nights","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2g47.jpg","s":"Touhou Luna Night's is a 2D search action (Metroidvania) video game.\nAfter creating many action games, this is a new project from Team Ladybug."},{"t":"Touhou Shoujo: Tale of Beautiful Memories","p":["Windows"],"u":"DLsite","g":"Action RPG","r":"August 22","l":"https://en.wikipedia.org/wiki/Touhou_Project"},{"t":"Tracks – The Train Set Game","p":["Windows","Xbox One","Nintendo Switch"],"d":"Whoop Games","u":"Excalibur Publishing","g":"Simulation","r":"October 11, 2019","l":"https://en.wikipedia.org/wiki/Tracks_%E2%80%93_The_Train_Set_Game"},{"t":"Trailmakers","p":["Windows","Xbox One"],"d":"Flashbulb Games","u":"Flashbulb Games","g":"Sandbox, simulation","r":"September 18, 2019","l":"https://en.wikipedia.org/wiki/Trailmakers","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8u8s.jpg","s":"In the toughest motoring expedition in the universe, you and your friends will build your own vehicles to cross a dangerous wasteland. Explore, crash horribly, use your wits to build a better rig, and get as far as you can with whatever spare parts you find on your way."},{"t":"Transport Fever 2","p":["Windows","Linux"],"d":"Urban Games","u":"Good Shepherd Entertainment, Nacon","g":"Business simulation","r":"December 11, 2019","l":"https://en.wikipedia.org/wiki/Transport_Fever_2","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/coaavx.jpg","s":"The classic transport simulation genre has a new gold standard with Transport Fever 2. Discover a whole new world by navigating transport routes through land, water and air. May progress and prosperity find their way!"},{"t":"Travis Strikes Again: No More Heroes","p":["Nintendo Switch"],"u":"Grasshopper Manufacture","g":"Action-adventure","r":"January 18"},{"t":"Travis Strikes Again: No More Heroes Complete Edition","p":["Windows","PlayStation 4"],"u":"Marvelous","g":"Action-adventure","r":"October 17"},{"t":"Trials Rising","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Ubisoft","g":"Racing, Platformer","r":"February 26","l":"https://en.wikipedia.org/wiki/Trials_Rising","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2697.jpg","s":"Trials Rising is a stunning comeback of the acclaimed gameplay with all new features, more competition and fresh visual look. With more tracks than ever before, beginners are in for a smooth ride towards mastery, while the skills and nerves of experienced players will be put to the test in the most advanced challenges. This is Trials at its best."},{"t":"Trine 4: The Nightmare Prince","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Modus Games","g":"Platformer","r":"October 8","l":"https://www.igdb.com/games/trine-4-the-nightmare-prince","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1qsm.jpg","s":"Featuring an all-new story that reunites Amadeus, Pontius, and Zoya, Trine 4: The Nightmare Prince returns to the magic of 2.5D with the puzzle-platforming gameplay that defined a genre in Trine 1 and 2. Play as the three iconic heroes in the most extensive Trine adventure yet, complete with stunning new environments and dynamic, physics-based puzzles that fans have grown to know and love.\n\nAfter years apart, the Astral Academy has requested help from the three heroes to find Prince Selius, whose intensely dark nightmares have begun to slip into reality and wreak havoc on the waking world. Encounter more epic boss fights than ever before, solve fascinating puzzles, unlock new skills, explore lush, vibrant landscapes, and experience a hauntingly beautiful new soundtrack by the composer of Trine 1-3. Additionally, and for the first time ever, Trine adds four-player co-op to its feature list."},{"t":"Tropico 6","p":["Windows","macOS","Linux","PlayStation 4","Xbox One"],"u":"Kalypso Media","g":"CMS, Government sim","r":"March 29","l":"https://en.wikipedia.org/wiki/Tropico_6","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1idx.jpg","s":"El Presidente is back! Prove yourself once again as a feared dictator or peace-loving statesman on the island state of Tropico and shape the fate of your very own banana republic through four distinctive eras."},{"t":"Trover Saves the Universe","p":["PlayStation 4","Windows","Nintendo Switch","Xbox One"],"u":"Squanch Games","g":"Action, Platformer","r":"May 31","l":"https://en.wikipedia.org/wiki/Trover_Saves_the_Universe","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4v3y.jpg","s":"Wonderful. Your dogs have been dognapped by a beaked lunatic who stuffed them into his eye holes and is using their life essence to destroy the universe. Does that make any sense? You've partnered with Trover, a little purple eye hole monster to save them. Find power babies and plug them into his eye holes so that he can absorb their power, track down Glorkon, and save your dogs (and the Universe)."},{"t":"Trüberbrook","p":["Linux","macOS","PlayStation 4","Nintendo Switch","Windows","Xbox One"],"d":"btf","u":"Headup Games, WhisperGames","g":"Point-and-click, Puzzle, Adventure, Indie","r":"March 12, 2019","l":"https://www.igdb.com/games/truberbrook","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8x8q.jpg","s":"Enjoy an adventurous vacation to a 1960's parallel universe! A Sci-Fi-Mystery Adventure Game with handmade scenery."},{"t":"Tsuppari Ōzumō","p":["Nintendo Switch"],"g":"Sports (wrestling)","r":"February 13"},{"t":"Twitch Sings","p":["Windows","macOS"],"d":"Harmonix","u":"Twitch","g":"Karaoke","r":"April 13, 2019","l":"https://en.wikipedia.org/wiki/Twitch_Sings","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1q36.jpg","s":"\"Twitch Sings is built from the ground up for streamers. With live singing, multiplayer modes, and features that let chat direct the show, our first game lets you and your community make one-of-a-kind performances together.\""},{"t":"Tänzer","p":["Genesis / Mega Drive"],"d":"Mikael Tillander","u":"Mega Cat Studios","g":"platform","l":"https://en.wikipedia.org/wiki/T%C3%A4nzer_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2kqf.jpg","s":"Tänzer is a homebrew action title inspired by games like Strider, OSman and Hagane: The Final Conflict, the art of Keita Amemiya and Roger Dean, and anime series like Guyver. The protagonist is a ballet dancer who is unexpectedly hit by a bright purple light at night in an apartment, just a week before the premiere of the ballet version of The Ariane. After the character wakes up the body is transformed and the world is in chaos. Each level has a different setting, ranging from the Old West to Ancient Rome. Levels are made up of several stages with mini bosses and then a large boss at the end of the level, acting as the guardian of that era."},{"t":"UBOAT","p":["Windows"],"u":"PlayWay S.A.","g":"Vehicle sim (submarine)","r":"April 30","l":"https://en.wikipedia.org/wiki/UBOAT"},{"t":"UglyDolls: An Imperfect Adventure","p":["Nintendo Switch","Windows","Xbox One","PlayStation 4"],"g":"Puzzle, Adventure, Indie","l":"https://en.wikipedia.org/wiki/UglyDolls:_An_Imperfect_Adventure","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co249n.jpg","s":"Robots are cool when they're blinking lights and zooming by with their sleek metallic finish. In UglyDolls: An Imperfect Adventure, a whole horde of robots are on the loose and taking over Uglyville trying to make it 'perfect!'."},{"t":"Ultracore","p":["Genesis / Mega Drive","Xbox Series X/S"],"d":"DICE, Strictly Limited Games","u":"Strictly Limited Games, Columbus Circle","g":"Run and gun","r":"March 25, 2019","l":"https://en.wikipedia.org/wiki/Ultracore","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2t7f.jpg","s":"Hardcore finally awakes.\n\nExcept for a few people, no one has ever seen or played this gem. But thanks to friends and our wonderful ‘A-Team’, the original data has finally been recovered. So after nearly 25 years of deep sleep, Hardcore will finally be published in 2019 under the name Ultracore!\n\nUltracore is being developed using original Sega Mega Drive development hardware. It will then be ported to run on modern platforms. We intend to finish the game the way it was meant to be played!\n\nEverything is being handled with care, to guarantee gamers get the best possible version of this masterpiece."},{"t":"Umihara Kawase Fresh!","p":["Nintendo Switch"],"u":"Nicalis","g":"Action","r":"April 25","l":"https://en.wikipedia.org/wiki/Umihara_Kawase_Fresh!"},{"t":"Un pas fragile","p":["Android","iOS","Windows"],"d":"Un pas fragile Team","u":"Opal Games","g":"Adventure, Indie","r":"June 24, 2019","l":"https://en.wikipedia.org/wiki/Un_pas_fragile","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co8lr9.jpg","s":"Follow the journey of Camille, a frog who dreams of becoming a ballet dancer!"},{"t":"Unheard","p":["Windows","macOS","Linux"],"u":"NEXT Studios","g":"Puzzle","r":"March 29"},{"t":"Uni's On Air","p":["Android","iOS"],"d":"Akatsuki Inc.","u":"Seed & Flower","g":"Rhythm game","r":"September 24, 2019","l":"https://en.wikipedia.org/wiki/Uni's_On_Air","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co6ejz.jpg","s":"Uni's On Air is a rhythm game featuring songs from Sakurazaka46 and Hinatazaka46. Players can experience various aspects of the real life of idols, communicating with avatars in the “office” area and creating original short stories in the “drama” section."},{"t":"Unity of Command II","p":["Windows"],"d":"2x2 Games","u":"2x2 Games, Croteam","g":"Turn-based strategy","r":"November 12, 2019","l":"https://en.wikipedia.org/wiki/Unity_of_Command_II","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co269k.jpg","s":"Unity of Command II is the sequel to one of the most critically acclaimed strategy games of all time; a game critics called 'the perfect gateway' into computer war games."},{"t":"Unravel Two","p":["Nintendo Switch"],"u":"Electronic Arts","g":"Platformer","r":"March 22","l":"https://en.wikipedia.org/wiki/Unravel_Two"},{"t":"Unruly Heroes","p":["Nintendo Switch","Windows","Xbox One","PlayStation 4","Android","iOS"],"d":"Magic Design Studios","u":"Magic Design Studios","g":"Platform","r":"January 23, 2019","l":"https://en.wikipedia.org/wiki/Unruly_Heroes","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1xlc.jpg","s":"Unruly Heroes is a 2D action-packed adventure game inspired by the famous chinese novel ‘A journey to the west’ better known as the Monkey King Legend. Through acrobatic challenges, players take control of four unlikely heroes and fight a diverse line-up of memorable enemies in solo or coop and be part of an epic adventure in a colorful and fantasy world! Set against lushly illustrated environments in a hand-drawn art style, the game updates that classic tale to make for an epic adventure that is more colorful and lighthearted than the original, while still highlighting the essence of what it takes to be a hero. In addition to this madcap adventure, players will be able to show their kung fu style by fighting their friends in local or online PvP."},{"t":"Untitled Goose Game","p":["Windows","Nintendo Switch"],"u":"Panic Inc.","g":"Stealth","r":"September 20","l":"https://en.wikipedia.org/wiki/Untitled_Goose_Game","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1vqc.jpg","s":"It's a lovely morning in the village and you are a horrible goose.\n\nUntitled Goose Game is a slapstick-stealth-sandbox, where you are a goose let loose on an unsuspecting village. Make your way around town, from peoples' back gardens to the high street shops to the village green, setting up pranks, stealing hats, honking a lot, and generally ruining everyone’s day."},{"t":"Utawarerumono","p":[],"l":"https://en.wikipedia.org/wiki/Utawarerumono"},{"t":"Utawarerumono: Zan","p":["PlayStation 4"],"u":"NIS America","g":"Action RPG, Brawler","r":"September 10"},{"t":"V-Rally 4","p":["Nintendo Switch"],"u":"Bigben Interactive","g":"Racing","r":"February 5","l":"https://en.wikipedia.org/wiki/V-Rally_4"},{"t":"Vader Immortal: A Star Wars VR Series","p":["Oculus Rift","Meta Quest"],"g":"Adventure","r":"May 21, 2019","l":"https://en.wikipedia.org/wiki/Vader_Immortal:_A_Star_Wars_VR_Series","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co31db.jpg","s":"Step inside a galaxy far, far away with Vader Immortal: A Star Wars VR Series. You are a smuggler operating near Mustafar, the fiery world Darth Vader calls home. When you are unexpectedly pulled out of hyperspace, you find yourself uncovering an ancient mystery at the behest of the Sith Lord himself.\n\nWith the help of your droid companion, ZO-E3, you’ll navigate the dangers of the fortress, hone your lightsaber skills, and meet new characters along the way as you discover what Vader is up to."},{"t":"Valfaris","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Merge Games","g":"Action, Platformer","r":"October 10","l":"https://en.wikipedia.org/wiki/Valfaris"},{"t":"Vambrace: Cold Soul","p":["Linux","macOS","Windows","Xbox One","Nintendo Switch","PlayStation 4"],"d":"Devespresso Games","u":"Headup, WhisperGames, Headup, Chorus Worldwide","g":"Roguelike, role-playing","r":"May 28, 2019","l":"https://en.wikipedia.org/wiki/Vambrace:_Cold_Soul","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co9roq.jpg","s":"Vambrace: Cold Soul is a roguelike fantasy-adventure set amidst a frozen landscape. Plan your expeditions underground, then journey to the cursed city surface with your team of heroes. Wield unique powers, avoid dangerous traps, brave strange encounters, and survive deadly combat!"},{"t":"Vampire: The Masquerade – Coteries of New York","p":["Windows","macOS","Linux"],"u":"Draw Distance","g":"Adventure","r":"December 11"},{"t":"Vampyr","p":["Nintendo Switch"],"u":"Focus Home Interactive","g":"Action RPG","r":"October 29","l":"https://en.wikipedia.org/wiki/Vampyr_(video_game)"},{"t":"Vane","p":["PlayStation 4","Windows"],"u":"Friend & Foe","g":"Adventure","r":"January 15","l":"https://en.wikipedia.org/wiki/Vane_(video_game)"},{"t":"Variable Barricade","p":["PlayStation Vita"],"d":"Otomate, Design Factory","u":"Idea Factory, Aksys Games","g":"Visual novel, otome game","r":"April 4, 2019","l":"https://en.wikipedia.org/wiki/Variable_Barricade","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co5ir4.jpg","s":"A member of a prestigious family and heir to a fortune, Hibari learns that her eccentric grandfather is determined to find her a husband. He arranges to house her in a luxurious villa along with four handsome, hand-picked bachelors and her private butler. As her suitors try to win her hand by any means necessary, Hibari endures endless everyday trials and temptations.\nHas her grandpa chosen poorly, or could there be more to these fellows than first meets the eye?\n\nThrough all of this, Hibari has two important goals: frighten off each of these marriage candidates, and absolutely refuse to fall in love."},{"t":"Various Daylife","p":["iOS"],"d":"DokiDoki Groove Works","u":"Square Enix","g":"Role-playing","r":"September 19, 2019","l":"https://en.wikipedia.org/wiki/Various_Daylife","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co59ty.jpg","s":"Various Daylife is an RPG set in the year 211 of the Imperial Era. Players explore a newly discovered continent while living life to the fullest in the city of Erebia."},{"t":"Vasara HD Collection","p":["Nintendo Switch","PlayStation 4","Xbox One"],"u":"QUByte Interactive","g":"Shoot 'em up","r":"August 15","l":"https://en.wikipedia.org/wiki/Vasara_(game)"},{"t":"Vectronom","p":["Windows","macOS","Nintendo Switch","iOS","Android"],"u":"ARTE Experience","g":"Rhythm","r":"May 29"},{"t":"Vice: Project Doom","p":["Nintendo Switch"],"g":"Fighting, Platformer, Racing, Shooter","r":"August 21"},{"t":"Virgo Versus the Zodiac","p":["macOS","Windows"],"u":"Degica Games","g":"RPG","r":"December 12","l":"https://en.wikipedia.org/wiki/Virgo_Versus_the_Zodiac"},{"t":"Void Bastards","p":["Windows","Xbox One"],"d":"Blue Manchu","u":"Humble Bundle","g":"FPS, Roguelike","r":"May 28","l":"https://en.wikipedia.org/wiki/Void_Bastards","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co497z.jpg","s":"\"Inspired by BioShock and System Shock 2, Void Bastards is a revolutionary new strategy-shooter that will test your wits as well as exercise your aim. Can you lead the misfit prisoners of the Void Ark through the derelict spaceships and myriad dangers of the Sargasso Nebula?\""},{"t":"Volleyball","p":["Nintendo Switch"],"g":"Sports","r":"June 12","l":"https://en.wikipedia.org/wiki/Volleyball_(video_game)"},{"t":"Vs. Excitebike","p":["Nintendo Switch"],"g":"Racing","r":"May 15","l":"https://en.wikipedia.org/wiki/Excitebike#Vs._Excitebike"},{"t":"Wacca","p":["Arcade"],"d":"Marvelous","u":"Marvelous","g":"Rhythm game","r":"July 18, 2019","l":"https://en.wikipedia.org/wiki/Wacca_(video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3d74.jpg","s":"Wacca is Marvelous's first arcade rhythm game developed in collaboration with the independent Japanese record label HARDCORE TANO*C, known for their contributions to other rhythm games like beatmania IIDX and Sound Voltex. Gameplay can be thought of an amalgamation of the touchbar of Chunithm and the circular playfield of Maimai. The game is networked to SEGA.NET/aime for profile saving and content updates. The online service for Wacca entered end-of-life on August 31, 2022, with all arcade cabinets subsequently placed in offline mode."},{"t":"Wanderlust Travel Stories","p":["Windows","macOS","iOS","Nintendo Switch"],"d":"Different Tales","u":"Walkabout Games","g":"Text adventure","r":"September 26, 2019","l":"https://en.wikipedia.org/wiki/Wanderlust_Travel_Stories","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1mvi.jpg","s":"Take the role of various modern travelers, live their adventures and shape their stories. Relish in discovery and awe, longing and hope as you journey from Africa to Antarctica, from Europe to Asia. The change brought by this odyssey will be your own.\n\nWanderlust is a bridge between literary experiences and gaming. A title that is meant to be taken in, experienced and felt. Perfect when you're traveling - or wish that you were."},{"t":"War of the Visions: Final Fantasy Brave Exvius","p":["iOS","Android"],"u":"Square Enix","g":"Tactical RPG","r":"November 14"},{"t":"Wargroove","p":["Windows","Nintendo Switch","Xbox One"],"u":"Chucklefish","g":"TBT","r":"February 1","l":"https://en.wikipedia.org/wiki/Wargroove","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co4hgb.jpg","s":"Wargroove is a turn-based strategy game for up to 4 players, in which each player takes control of an army and its commander unit to wage war on their enemies! Wargroove is extremely easy to pickup, with accessibility at the forefront of its design, and very difficult to master, with deep gameplay mechanics that complement strategic play."},{"t":"Warhammer: Chaosbane","p":["Windows","PlayStation 4","Xbox One"],"u":"Bigben Interactive","g":"RPG","r":"June 4","l":"https://www.igdb.com/games/warhammer-chaosbane","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cocshz.jpg","s":"In a world ravaged by war and dominated by magic, you must rise up to face the Chaos hordes. Playing solo or with up to four in local or online co-op, choose a hero from four character classes and prepare for epic battles wielding some of the most powerful artefacts of the Old World."},{"t":"Warsaw","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Pixelated Milk","g":"Action RPG","r":"October 2","l":"https://en.wikipedia.org/wiki/Warsaw_(video_game)"},{"t":"Wattam","p":["Windows","PlayStation 4"],"u":"Annapurna Interactive","g":"Action","r":"December 17","l":"https://en.wikipedia.org/wiki/Wattam"},{"t":"What the Golf?","p":["Windows","iOS"],"u":"The Label","g":"Puzzle","r":"October 1","l":"https://en.wikipedia.org/wiki/What_the_Golf%3F","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1rgr.jpg","s":"The golf game for people who hate golf. A silly physics-based golf parody where every golf course is a new surprising type of golf, some brilliant or hilarious, others so absurd they will make you go: What the golf!"},{"t":"When Ski Lifts Go Wrong","p":["Windows","macOS","Nintendo Switch"],"d":"Hugecalf Studios","u":"Curve Digital","g":"Construction and management simulation","r":"January 23, 2019","l":"https://en.wikipedia.org/wiki/When_Ski_Lifts_Go_Wrong","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1ix9.jpg","s":"It's time to get carried away with the deliriously fun, bloody physics-based construction puzzler packed full of creative challenges, sports and bloody disasters!"},{"t":"Where in the World Is Carmen Sandiego? The Trivia Game","p":[],"l":"https://en.wikipedia.org/wiki/Where_in_the_World_Is_Carmen_Sandiego%3F_The_Trivia_Game"},{"t":"Where on Google Earth is Carmen Sandiego?","p":[],"l":"https://en.wikipedia.org/wiki/Where_on_Google_Earth_is_Carmen_Sandiego%3F"},{"t":"Where the Bees Make Honey","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One","Xbox Series X/S","Xbox"],"d":"Whitethorn Digital","u":"Wakefield Interactive","g":"Adventure","r":"March 26, 2019","l":"https://en.wikipedia.org/wiki/Where_the_Bees_Make_Honey","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2492.jpg","s":"Where the Bees Make Honey tells a story about reflecting on different moments from your childhood, which are played and experienced from an adult perspective. At its core Where The Bees Make Honey is a puzzle adventure game, but gameplay variation is filtered throughout."},{"t":"Whispers of a Machine","p":["Windows","macOS","Android","iOS"],"d":"Clifftop Games, Faravid Interactive","u":"Raw Fury","g":"Point-and-click adventure","r":"April 17, 2019","l":"https://en.wikipedia.org/wiki/Whispers_of_a_Machine","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co26a9.jpg","s":"Whispers of a Machine is a Sci-Fi Nordic Noir that tells the story of Vera, a cybernetically augmented detective in a post-AI world, who investigates a string of murders and unravels a dark conflict over forbidden technology."},{"t":"Wilmot's Warehouse","p":["macOS","Nintendo Switch","Windows","Xbox One","PlayStation 4"],"d":"Hollow Ponds","u":"Finji","g":"Puzzle","r":"August 29, 2019","l":"https://en.wikipedia.org/wiki/Wilmot's_Warehouse","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2fe6.jpg","s":"Wilmot's Warehouse is a puzzle game about keeping a warehouse running in tip-top shape. You play as Wilmot, a hard working warehouse employee tasked with pushing, sorting and stacking a variety of products. Over time more and more truckloads of these products will arrive, gradually filling up the warehouse. How you arrange them all is entirely up to you - organize by color, type, the Dewey Decimal System, or some wild format that only you understand - it's all good! Just remember where you put everything, because when the service hatch opens, you'll need to find the things people want quickly, in order to earn the coveted Performance Stars required for all manner of labor-saving upgrades."},{"t":"Wily Beast and Weakest Creature","p":["Windows"],"d":"Team Shanghai Alice","u":"Team Shanghai Alice","g":"Vertical danmaku scrolling shooter","r":"August 12, 2019","l":"https://en.wikipedia.org/wiki/Wily_Beast_and_Weakest_Creature"},{"t":"Winds of Change","p":["Windows"],"u":"Crunching Koalas","g":"Visual novel, RPG, Adventure","r":"August 21"},{"t":"Wintermoor Tactics Club","p":["PlayStation 4","Windows","Xbox One","Nintendo Switch"],"d":"EVC Games","u":"Versus Evil","g":"Tactical role-playing","l":"https://en.wikipedia.org/wiki/Wintermoor_Tactics_Club","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2gk8.jpg","s":"Wintermoor Tactics Club is a story about surviving high school, with gameplay inspired by tactics RPGs and visual novels."},{"t":"Wolfenstein: Cyberpilot","p":["Windows","PlayStation 4"],"u":"Bethesda Softworks","g":"FPS, Action-adventure","r":"July 26"},{"t":"Wolfenstein: Youngblood","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Bethesda Softworks","g":"FPS","r":"July 26","l":"https://www.igdb.com/games/wolfenstein-youngblood","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co21by.jpg","s":"Wolfenstein: Youngblood is a brand-new co-op experience from MachineGames, the award-winning studio that developed the critically acclaimed Wolfenstein II: The New Colossus.\n\nSet in 1980, 19 years after BJ Blazkowicz ignited the second American Revolution, Wolfenstein: Youngblood introduces the next Blazkowicz generation to the fight against the Nazis. Play as one of BJ’s twin daughters, Jess and Soph, as you search for your missing father in Nazi-occupied Paris."},{"t":"World End Syndrome","p":["Nintendo Switch","PlayStation 4"],"u":"Arc System Works","g":"Visual novel","r":"May 14","l":"https://en.wikipedia.org/wiki/World_End_Syndrome"},{"t":"World of Warcraft Classic","p":["Windows","macOS"],"u":"Blizzard Entertainment","g":"RPG","r":"August 27","l":"https://en.wikipedia.org/wiki/World_of_Warcraft_Classic"},{"t":"World War Z","p":["Windows","PlayStation 4","Xbox One"],"u":"Mad Dog Games","g":"Survival horror, TPS","r":"April 16","l":"https://en.wikipedia.org/wiki/World_War_Z_(2019_video_game)","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2i4r.jpg","s":"Humanity is on the brink of extinction. From New York to Moscow and Jerusalem, the undead apocalypse continues to spread. As the end looms, a hardened few bands together to defeat the horde and outlive the dead.\n\nWorld War Z is a heart-pounding co-op third-person shooter for up to 4 players featuring swarms of hundreds of zombies. Based on the Paramount Pictures film, World War Z focuses on fast-paced gameplay while exploring new storylines from around the world."},{"t":"WRC 8","p":["Windows","PlayStation 4","Xbox One","Nintendo Switch"],"d":"Kylotonn","u":"Bigben Interactive","g":"Racing","r":"September 10, 2019","l":"https://en.wikipedia.org/wiki/WRC_8","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co3wlv.jpg","s":"Never before has the official WRC simulation been this authentic. New off-road physics on all road surfaces, completely redesigned career mode, dynamic weather, 50 teams, 14 countries, 100+ stages, weekly challenges and the eSports mode… Aim for the top in the most intense WRC experience yet!"},{"t":"Wrecking Crew","p":["Nintendo Switch"],"g":"Action, Puzzle","r":"July 17","l":"https://en.wikipedia.org/wiki/Wrecking_Crew_(video_game)"},{"t":"WWE 2K20","p":["Windows","PlayStation 4","Xbox One"],"u":"2K Sports","g":"Sports","r":"October 22","l":"https://en.wikipedia.org/wiki/WWE_2K20"},{"t":"Xeno Crisis","p":["Genesis / Mega Drive","Linux","macOS","Windows","Nintendo Switch","PlayStation 4","PlayStation 5","Xbox One","PlayStation","Evercade"],"d":"Bitmap Bureau","u":"Bitmap Bureau","g":"Multidirectional shooter","r":"October 28, 2019","l":"https://en.wikipedia.org/wiki/Xeno_Crisis","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1uh0.jpg","s":"Xeno Crisis is an arena shooter in which one or two players take control of battle-hardened marines embarking on a deadly mission to confront an alien menace and get home alive! Run and gun your way through thousands of adversaries as you explore the devastated research outpost, searching for survivors, and ultimately facing the origin of the outpost's demise. Outpost 88 is divided into seven distinct areas, each being randomly generated with each play, meaning that your strategy must evolve on the fly if you're to succeed in your mission. Collect dog-tags from vanquished enemies to upgrade your equipment between areas and look out for special weapons which will give you a momentary advantage."},{"t":"Xenon Racer","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Soedesco","g":"Racing","r":"March 26","l":"https://en.wikipedia.org/wiki/Xenon_Racer"},{"t":"Yakuza 3","p":["PlayStation 4"],"u":"Sega","g":"Action-adventure","r":"August 20","l":"https://en.wikipedia.org/wiki/Yakuza_3"},{"t":"Yakuza 4","p":["PlayStation 4"],"u":"Sega","g":"Action-adventure","r":"January 17","l":"https://en.wikipedia.org/wiki/Yakuza_4"},{"t":"Yakuza 4 Remastered","p":["PlayStation 4"],"d":"Ryu Ga Gotoku Studio","u":"Sega, Sega Games","g":"Role-playing (RPG), Simulator, Sport, Hack and slash/Beat 'em up, Adventure","r":"January 17, 2019","l":"https://www.igdb.com/games/yakuza-4-remastered","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2s10.jpg","s":"The game from 2010 has been remastered for the PS4 with one of Yakuza 4's main protagonists, Masayoshi Tanimura, being recast and getting a visual makeover.\n\nKamurocho, the entertainment district, is about to be bloodbath again. This time, we have four rising dragons. Each of the protagonists has a different fighting style and each of them has to go through sets of impossible trials to find their destiny. The line between game and reality is further blurred, earlier, in 2009, Sega hosts a beauty pageant, and the seven winners became models of their game avatars. Some of them are bar girls, some are hostesses, visit the \"play spots\" with them, ask them to date in the spas and sing karaoke with them. The Rising Dragon is looking for a successor, will you be it?"},{"t":"Yakuza 5","p":["PlayStation 4"],"u":"Sega","g":"Action-adventure","r":"June 20","l":"https://en.wikipedia.org/wiki/Yakuza_5"},{"t":"Yakuza 5 Remastered","p":["PlayStation 4"],"d":"Ryu Ga Gotoku Studio","u":"Sega, Sega Games","g":"Adventure","r":"June 20, 2019","l":"https://www.igdb.com/games/yakuza-5-remastered","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2s11.jpg","s":"Experience the fifth chapter of the Kazuma Kiryu saga in 1080p and 60fps. Get ready for a Yakuza experience of unprecedented scale. Follow five characters across five Japanese cities, each trying to achieve their dream. The connections between them bring them together, but the conflict that unfolds is nothing any of them could have predicted."},{"t":"Yakuza Kiwami","p":["Windows"],"u":"Sega","g":"Action-adventure","r":"February 19","l":"https://en.wikipedia.org/wiki/Yakuza_Kiwami"},{"t":"Yakuza Kiwami 2","p":["Windows"],"u":"Sega","g":"Action-adventure","r":"May 9","l":"https://en.wikipedia.org/wiki/Yakuza_Kiwami_2"},{"t":"Yie Ar Kung-Fu","p":["Nintendo Switch"],"g":"Fighting","r":"March 13","l":"https://en.wikipedia.org/wiki/Yie_Ar_Kung-Fu"},{"t":"YIIK: A Postmodern RPG","p":["Windows","macOS","Nintendo Switch","PlayStation 4","PlayStation Vita"],"u":"Ysbryd Games","g":"RPG","r":"January 17"},{"t":"Ylands","p":["Windows","Android","iOS"],"d":"Bohemia Interactive","u":"Bohemia Interactive","g":"Survival","r":"December 5, 2019","l":"https://en.wikipedia.org/wiki/Ylands"},{"t":"Yo-kai Watch 4","p":["Nintendo Switch"],"u":"Level-5","g":"RPG","r":"June 20","l":"https://en.wikipedia.org/wiki/Yo-kai_Watch_4"},{"t":"Yooka-Laylee and the Impossible Lair","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"u":"Team17","g":"Platformer","r":"October 8","l":"https://en.wikipedia.org/wiki/Yooka-Laylee_and_the_Impossible_Lair","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2z9b.jpg","s":"Yooka and Laylee are back for a brand new adventure! Get ready for the ultimate challenge - the Impossible Lair!\n\nCapital B has created a Hivemind device and used it to enslave the toughest bees in the Royal Stingdom - the Royal Beettalion Guard!\n\nLiberate them from chapters filled with only the tastiest 2D platforming trimmings, and take on a 3D overworld that contains a wealth of puzzles, secrets and some familiar faces!"},{"t":"Yoshi's Crafted World","p":["Nintendo Switch"],"u":"Nintendo","g":"Platformer","r":"March 29","l":"https://en.wikipedia.org/wiki/Yoshi%27s_Crafted_World","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/cobav7.jpg","s":"Lead Yoshi on a brand new adventure that will turn everything you've come to expect from side-scrolling games upside down! Explore a great, big world decorated like a miniature diorama in a new art style for the franchise, where each side-scrolling stage has the traditional front side as well as a flip side with different views and surprises. Look for items throughout the stage as Yoshi makes his way to the goal. You can even join up with a friend!"},{"t":"Ys IX: Monstrum Nox","p":["PlayStation 4"],"u":"Nihon Falcom","g":"RPG","r":"September 26","l":"https://www.igdb.com/games/ys-ix-monstrum-nox","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co2ate.jpg","s":"While imprisoned in Balduq, Adol is cursed and becomes a Monstrum. With his newfound powers, he must stop the Grimwald Nox from consuming the city."},{"t":"Yu-Gi-Oh! Legacy of the Duelist: Link Evolution","p":["Nintendo Switch"],"u":"Konami","g":"TBS","r":"August 20"},{"t":"YU-NO: A Girl Who Chants Love at the Bound of this World","p":["Windows","Nintendo Switch","PlayStation 4"],"u":"Spike Chunsoft","g":"Adventure, Visual novel","r":"October 1"},{"t":"Yuppie Psycho","p":["macOS","Windows","Linux"],"d":"Baroque Decay","u":"Neon Doctrine","g":"Survival horror","r":"April 25, 2019","l":"https://en.wikipedia.org/wiki/Yuppie_Psycho","i":"https://images.igdb.com/igdb/image/upload/t_cover_small/co1n1e.jpg","s":"Join Brian Pasternack on his first day at one of the world’s largest companies, Sintracorp. Uncertain, unprepared, and massively unqualified, will Pasternack have what it takes to shine in Sintracorp's hierarchy? It all depends on how he performs on his first assignment… and whether he survives it."},{"t":"Zanki Zero: Last Beginning","p":["Windows","PlayStation 4"],"u":"Spike Chunsoft","g":"RPG, Dungeon crawl","r":"April 9"},{"t":"Zelda II: The Adventure of Link","p":["Nintendo Switch"],"g":"Action RPG","r":"January 16"},{"t":"Zombieland: Double Tap – Road Trip","p":["Windows","Nintendo Switch","PlayStation 4","Xbox One"],"d":"High Voltage Software","u":"GameMill Entertainment, Maximum Games","g":"Shoot 'em up","r":"October 15, 2019","l":"https://en.wikipedia.org/wiki/Zombieland:_Double_Tap_%E2%80%93_Road_Trip"},{"t":"Zumba Burn It Up!","p":[],"l":"https://en.wikipedia.org/wiki/Zumba_Burn_It_Up!"}];
